<?php
defined('ALTUMCODE') || die();

function fcc_ai_get_assistant_types(): array {
    static $assistant_types = null;

    if($assistant_types !== null) {
        return $assistant_types;
    }

    $assistant_types = require APP_PATH . 'includes/fcc_ai_assistant_types.php';

    return $assistant_types;
}

function fcc_ai_get_assistant_type(string $assistant_type): ?array {
    $assistant_type = trim(mb_strtolower($assistant_type));
    $assistant_types = fcc_ai_get_assistant_types();

    return $assistant_types[$assistant_type] ?? null;
}

function fcc_ai_get_assistant_label(string $assistant_type, string $fallback = 'AI'): string {
    $assistant_type = trim(mb_strtolower($assistant_type));
    $definition = $assistant_type !== '' ? fcc_ai_get_assistant_type($assistant_type) : null;
    $label = trim((string) ($definition['label'] ?? ''));

    if($label !== '') {
        return $label;
    }

    if($assistant_type !== '') {
        return $assistant_type;
    }

    return $fallback;
}

function fcc_ai_get_soft_resolved_feedback_ids(): array {
    static $ids = null;

    if($ids !== null) {
        return $ids;
    }

    /* Historical live feedback cases already fixed in the recommendation engine but not writable-resolved in production DB. */
    $ids = [43, 45, 46, 48, 49, 50, 51, 53, 54, 60, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78, 79, 80, 81];

    return $ids;
}

function fcc_ai_is_soft_resolved_feedback_id(int $feedback_id): bool {
    static $lookup = null;

    if($lookup === null) {
        $lookup = array_fill_keys(array_map('intval', fcc_ai_get_soft_resolved_feedback_ids()), true);
    }

    return $feedback_id > 0 && isset($lookup[$feedback_id]);
}

function fcc_ai_get_feedback_visibility_sql(string $alias = ''): string {
    $ids = array_values(array_filter(array_map('intval', fcc_ai_get_soft_resolved_feedback_ids()), static function(int $feedback_id): bool {
        return $feedback_id > 0;
    }));

    if(empty($ids)) {
        return '1=1';
    }

    $alias = trim($alias);
    $qualified_column = $alias !== ''
        ? '`' . trim($alias, "` \t\n\r\0\x0B") . '`.`fcc_ai_message_feedback_id`'
        : '`fcc_ai_message_feedback_id`';

    return $qualified_column . ' NOT IN (' . implode(',', $ids) . ')';
}

function fcc_ai_is_coach_assistant(string $assistant_type): bool {
    return trim(mb_strtolower($assistant_type)) === 'coach';
}

function fcc_ai_get_public_assistant_types(): array {
    return array_filter(fcc_ai_get_assistant_types(), static function($assistant_type) {
        return !empty($assistant_type['is_public']);
    });
}

function fcc_ai_validate_assistant_type(string $assistant_type, bool $public_only = false): ?string {
    $assistant_type = trim(mb_strtolower($assistant_type));
    $definition = fcc_ai_get_assistant_type($assistant_type);

    if(!$definition) {
        return null;
    }

    if($public_only && empty($definition['is_public'])) {
        return null;
    }

    return $assistant_type;
}

function fcc_ai_normalize_scope(string $scope, string $assistant_type): string {
    $scope = trim(mb_strtolower($scope));
    $definition = fcc_ai_get_assistant_type($assistant_type);

    if(!$definition) {
        return $scope !== '' ? $scope : 'public_app';
    }

    $allowed_scopes = $definition['allowed_scopes'] ?? [];
    if($scope !== '' && in_array($scope, $allowed_scopes, true)) {
        return $scope;
    }

    return (string) ($definition['default_scope'] ?? 'public_app');
}

function fcc_ai_get_public_storage_key(): string {
    return 'fcc_ai_public_conversation_id';
}

function fcc_ai_get_public_context_storage_key(): string {
    return 'fcc_ai_public_context';
}

function fcc_ai_get_internal_storage_key(): string {
    return 'fcc_ai_internal_conversation_id';
}

function fcc_ai_get_internal_context_storage_key(): string {
    return 'fcc_ai_internal_context';
}

function fcc_ai_normalize_user_preferences($preferences): \stdClass {
    if(is_string($preferences)) {
        $preferences = json_decode($preferences ?? '{}');
    }

    if(is_array($preferences)) {
        $preferences = (object) $preferences;
    }

    if(!$preferences instanceof \stdClass) {
        $preferences = (object) [];
    }

    return $preferences;
}

function fcc_ai_get_internal_coach_campaigns(): array {
    static $campaigns = null;

    if($campaigns !== null) {
        return $campaigns;
    }

    $path = APP_PATH . 'includes/fcc_ai_internal_campaigns.php';
    if(file_exists($path)) {
        $loaded = require $path;
        $campaigns = is_array($loaded) ? array_values(array_filter($loaded, 'is_array')) : [];
    } else {
        $campaigns = [];
    }

    return $campaigns;
}

function fcc_ai_get_internal_coach_campaign_field(array $campaign, string $field, string $language = 'hr', $default = '') {
    $language = fcc_ai_resolve_public_reply_language($language);
    $value = $campaign[$field] ?? $default;

    if(is_array($value) && (isset($value['hr']) || isset($value['en']) || isset($value['sl']) || isset($value['bg']))) {
        return $value[$language] ?? $value['hr'] ?? $value['en'] ?? $default;
    }

    return $value;
}

function fcc_ai_parse_campaign_datetime(string $value, string $fallback = ''): ?\DateTimeImmutable {
    $value = trim($value);

    if($value === '') {
        $value = trim($fallback);
    }

    if($value === '') {
        return null;
    }

    try {
        return new \DateTimeImmutable($value, new \DateTimeZone(date_default_timezone_get() ?: 'Europe/Zagreb'));
    } catch(\Throwable $exception) {
        try {
            return new \DateTimeImmutable($value);
        } catch(\Throwable $secondary_exception) {
            return null;
        }
    }
}

function fcc_ai_is_internal_coach_campaign_active(array $campaign, ?\DateTimeImmutable $now = null): bool {
    $now = $now ?: new \DateTimeImmutable('now', new \DateTimeZone(date_default_timezone_get() ?: 'Europe/Zagreb'));
    $starts_at = fcc_ai_parse_campaign_datetime((string) ($campaign['starts_at'] ?? ''));
    $ends_at = fcc_ai_parse_campaign_datetime((string) ($campaign['ends_at'] ?? ''), '9999-12-31 23:59:59');

    if($starts_at && $now < $starts_at) {
        return false;
    }

    if($ends_at && $now > $ends_at) {
        return false;
    }

    return true;
}

function fcc_ai_format_internal_coach_campaign_period(array $campaign, string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $starts_at = fcc_ai_parse_campaign_datetime((string) ($campaign['starts_at'] ?? ''));
    $ends_at = fcc_ai_parse_campaign_datetime((string) ($campaign['ends_at'] ?? ''));

    if(!$starts_at && !$ends_at) {
        return '';
    }

    if($language === 'en') {
        $start_label = $starts_at ? $starts_at->format('M j, Y') : '';
        $end_label = $ends_at ? $ends_at->format('M j, Y') : '';

        if($start_label !== '' && $end_label !== '') {
            return $start_label . ' - ' . $end_label;
        }

        return $start_label !== '' ? $start_label : $end_label;
    }

    $start_label = $starts_at ? $starts_at->format('d.m.Y.') : '';
    $end_label = $ends_at ? $ends_at->format('d.m.Y.') : '';

    if($start_label !== '' && $end_label !== '') {
        return $start_label . ' - ' . $end_label;
    }

    return $start_label !== '' ? $start_label : $end_label;
}

function fcc_ai_get_active_internal_coach_campaign($user = null, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $campaigns = fcc_ai_get_internal_coach_campaigns();

    if(empty($campaigns)) {
        return [];
    }

    usort($campaigns, static function(array $a, array $b) {
        return ((int) ($b['priority'] ?? 0) <=> (int) ($a['priority'] ?? 0));
    });

    $active_campaign = null;
    foreach($campaigns as $campaign) {
        if(fcc_ai_is_internal_coach_campaign_active($campaign)) {
            $active_campaign = $campaign;
            break;
        }
    }

    if(!$active_campaign) {
        return [];
    }

    $user_id = is_object($user) ? (int) ($user->user_id ?? 0) : 0;
    $main_link_id = 0;
    if($user_id > 0 && function_exists('fc_get_user_main_biolink_id')) {
        $main_link_id = (int) (fc_get_user_main_biolink_id($user_id) ?? 0);
    }

    $primary_url = $main_link_id > 0
        ? url('link/' . $main_link_id . '?tab=blocks')
        : url('links?type=biolink');
    $offer_labels = fcc_ai_get_internal_coach_campaign_field($active_campaign, 'offer_labels', $language, []);
    $setup_steps = fcc_ai_get_internal_coach_campaign_field($active_campaign, 'setup_steps', $language, []);

    return [
        'id' => (string) ($active_campaign['id'] ?? ''),
        'title' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'title', $language, ''),
        'eyebrow' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'eyebrow', $language, ''),
        'summary' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'summary', $language, ''),
        'welcome_line' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'welcome_line', $language, ''),
        'period_label' => fcc_ai_format_internal_coach_campaign_period($active_campaign, $language),
        'primary_url' => $primary_url,
        'primary_label' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'primary_label', $language, ''),
        'primary_description' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'primary_description', $language, ''),
        'prompt_label' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'prompt_label', $language, ''),
        'prompt' => (string) fcc_ai_get_internal_coach_campaign_field($active_campaign, 'prompt', $language, ''),
        'setup_steps' => is_array($setup_steps) ? array_values(array_filter(array_map(static function($step) {
            return is_scalar($step) ? trim((string) $step) : '';
        }, $setup_steps))) : [],
        'offer_labels' => is_array($offer_labels) ? array_values(array_filter(array_map(static function($offer) {
            return is_scalar($offer) ? trim((string) $offer) : '';
        }, $offer_labels))) : [],
        'offer_urls' => array_values(array_filter(array_map(static function($url) {
            return is_scalar($url) ? trim((string) $url) : '';
        }, (array) ($active_campaign['offer_urls'] ?? [])))),
    ];
}

function fcc_ai_get_user_sidebar_signal_state(object $user): array {
    $payload = [
        'count' => 0,
        'new_leads' => 0,
        'new_feedback' => 0,
        'latest_lead_id' => 0,
        'latest_feedback_id' => 0,
    ];

    $user_id = (int) ($user->user_id ?? 0);
    if($user_id <= 0 || !fcc_ai_tables_ready()) {
        return $payload;
    }

    $preferences = fcc_ai_normalize_user_preferences($user->preferences ?? null);
    $last_seen_lead_id = (int) ($preferences->fcc_ai_last_seen_lead_id ?? 0);
    $last_seen_feedback_id = (int) ($preferences->fcc_ai_last_seen_feedback_id ?? 0);

    $lead_row = database()->query("SELECT
            MAX(`fcc_ai_lead_id`) AS `latest_id`,
            COUNT(*) AS `total`
        FROM `fcc_ai_leads`
        WHERE `user_id` = {$user_id}
          AND `fcc_ai_lead_id` > {$last_seen_lead_id}")->fetch_object();

    if($lead_row) {
        $payload['latest_lead_id'] = (int) ($lead_row->latest_id ?? 0);
        $payload['new_leads'] = (int) ($lead_row->total ?? 0);
    }

    $feedback_row = database()->query("SELECT
            MAX(`f`.`fcc_ai_message_feedback_id`) AS `latest_id`,
            COUNT(*) AS `total`
        FROM `fcc_ai_message_feedback` AS `f`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `f`.`fcc_ai_conversation_id`
        WHERE `f`.`user_id` = {$user_id}
          AND `f`.`fcc_ai_message_feedback_id` > {$last_seen_feedback_id}
          AND `f`.`feedback_type` = 'down'
          AND COALESCE(`f`.`status`, 'new') != 'resolved'
          AND " . fcc_ai_get_feedback_visibility_sql('f') . "
          AND COALESCE(`c`.`assistant_type`, '') != 'coach'")->fetch_object();

    if($feedback_row) {
        $payload['latest_feedback_id'] = (int) ($feedback_row->latest_id ?? 0);
        $payload['new_feedback'] = (int) ($feedback_row->total ?? 0);
    }

    $payload['count'] = (int) $payload['new_leads'] + (int) $payload['new_feedback'];

    return $payload;
}

function fcc_ai_mark_user_sidebar_signals_seen(object $user): \stdClass {
    $preferences = fcc_ai_normalize_user_preferences($user->preferences ?? null);
    $user_id = (int) ($user->user_id ?? 0);

    if($user_id <= 0 || !fcc_ai_tables_ready()) {
        return $preferences;
    }

    $signal_state = fcc_ai_get_user_sidebar_signal_state($user);
    $latest_lead_id = max((int) ($preferences->fcc_ai_last_seen_lead_id ?? 0), (int) ($signal_state['latest_lead_id'] ?? 0));
    $latest_feedback_id = max((int) ($preferences->fcc_ai_last_seen_feedback_id ?? 0), (int) ($signal_state['latest_feedback_id'] ?? 0));

    if(
        $latest_lead_id <= (int) ($preferences->fcc_ai_last_seen_lead_id ?? 0)
        && $latest_feedback_id <= (int) ($preferences->fcc_ai_last_seen_feedback_id ?? 0)
    ) {
        return $preferences;
    }

    $preferences->fcc_ai_last_seen_lead_id = $latest_lead_id;
    $preferences->fcc_ai_last_seen_feedback_id = $latest_feedback_id;

    db()->where('user_id', $user_id)->update('users', [
        'preferences' => json_encode($preferences),
    ]);

    cache()->deleteItemsByTag('user_id=' . $user_id);

    return $preferences;
}

function fcc_ai_generate_public_id(int $bytes = 18): string {
    try {
        return bin2hex(random_bytes($bytes));
    } catch(\Throwable $exception) {
        return md5(uniqid((string) mt_rand(), true) . microtime(true));
    }
}

function fcc_ai_get_tables(): array {
    return [
        'fcc_ai_assistants',
        'fcc_ai_conversations',
        'fcc_ai_messages',
        'fcc_ai_events',
        'fcc_ai_leads',
        'fcc_ai_daily_stats',
    ];
}

function fcc_ai_tables_ready(bool $refresh = false): bool {
    static $is_ready = null;

    if(!$refresh && $is_ready !== null) {
        return $is_ready;
    }

    $is_ready = true;

    foreach(fcc_ai_get_tables() as $table) {
        $result = database()->query("SHOW TABLES LIKE '{$table}'");
        if(!$result || !$result->num_rows) {
            $is_ready = false;
            break;
        }
    }

    return $is_ready;
}

