function fcc_ai_humanize_choice(string $category, $value, string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);

    if(is_array($value)) {
        $parts = array_values(array_filter(array_map(static function($item) use ($category, $language) {
            return fcc_ai_humanize_choice($category, $item, $language);
        }, $value)));

        return implode(', ', $parts);
    }

    $value = trim((string) $value);

    if($value === '') {
        return '';
    }

    $labels = fcc_ai_get_coach_choice_labels();
    $label = $labels[$category][$value][$language] ?? null;

    if($label !== null) {
        return $label;
    }

    $fallback = str_replace(['_', '-'], ' ', $value);
    $fallback = preg_replace('/\s+/u', ' ', $fallback) ?? $fallback;

    return trim($fallback);
}

function fcc_ai_normalize_phone(string $phone, ?string $country_code = null): array {
    $country_code = mb_strtoupper(trim((string) $country_code));
    $country_options = get_contact_phone_country_options_array();
    $dial_codes = get_contact_phone_dial_codes_array();

    if(!array_key_exists($country_code, $country_options)) {
        $country_code = 'HR';
    }

    $dial_code = $dial_codes[$country_code] ?? '';
    $raw_digits = preg_replace('/\D+/', '', $phone);
    $trimmed_digits = ltrim($raw_digits, '0');

    if(!$trimmed_digits) {
        return [
            'raw' => trim($phone),
            'country_code' => $country_code,
            'dial_code' => $dial_code,
            'e164' => '',
            'is_valid' => false,
        ];
    }

    if($dial_code && str_starts_with($raw_digits, $dial_code)) {
        $trimmed_digits = $raw_digits;
    } elseif($dial_code) {
        $trimmed_digits = $dial_code . $trimmed_digits;
    }

    $e164 = '+' . $trimmed_digits;

    return [
        'raw' => trim($phone),
        'country_code' => $country_code,
        'dial_code' => $dial_code,
        'e164' => $e164,
        'is_valid' => mb_strlen($trimmed_digits) >= 8 && mb_strlen($trimmed_digits) <= 15,
    ];
}

function fcc_ai_get_chat_lead_counts_by_dimension(string $dimension, array $ids, string $period_start_datetime, ?string $period_end_datetime = null): array {
    $allowed_dimensions = ['link_id', 'user_id'];

    if(!in_array($dimension, $allowed_dimensions, true)) {
        return [];
    }

    $ids = array_values(array_unique(array_filter(array_map('intval', $ids), static function($value) {
        return $value > 0;
    })));

    if(empty($ids)) {
        return [];
    }

    $ids_sql = implode(',', $ids);
    $period_end_sql = $period_end_datetime !== null && trim($period_end_datetime) !== ''
        ? " AND `datetime` < '{$period_end_datetime}'"
        : '';
    $result = database()->query("SELECT `{$dimension}` AS `dimension_id`, COUNT(*) AS `total`
        FROM `data`
        WHERE `type` = 'ai_chat_lead'
          AND `datetime` >= '{$period_start_datetime}'
          {$period_end_sql}
          AND `{$dimension}` IN ({$ids_sql})
        GROUP BY `{$dimension}`");

    $counts = [];

    while($row = $result->fetch_object()) {
        $dimension_id = (int) ($row->dimension_id ?? 0);

        if($dimension_id <= 0) {
            continue;
        }

        $counts[$dimension_id] = (int) ($row->total ?? 0);
    }

    return $counts;
}

function fcc_ai_get_chat_lead_counts_by_link_ids(array $link_ids, string $period_start_datetime, ?string $period_end_datetime = null): array {
    return fcc_ai_get_chat_lead_counts_by_dimension('link_id', $link_ids, $period_start_datetime, $period_end_datetime);
}

function fcc_ai_get_chat_lead_counts_by_user_ids(array $user_ids, string $period_start_datetime, ?string $period_end_datetime = null): array {
    return fcc_ai_get_chat_lead_counts_by_dimension('user_id', $user_ids, $period_start_datetime, $period_end_datetime);
}

function fcc_ai_get_assistant_id_for_user(int $user_id, string $assistant_type, string $scope): ?int {
    fcc_ai_seed_user_assistants($user_id);

    $assistant_id = db()
        ->where('user_id', $user_id)
        ->where('assistant_type', $assistant_type)
        ->where('scope', $scope)
        ->getValue('fcc_ai_assistants', 'fcc_ai_assistant_id');

    return $assistant_id ? (int) $assistant_id : null;
}

function fcc_ai_get_assistant_by_id(int $assistant_id): ?object {
    if($assistant_id <= 0) {
        return null;
    }

    fcc_ai_ensure_tables();

    $assistant = db()->where('fcc_ai_assistant_id', $assistant_id)->getOne('fcc_ai_assistants');

    if(!$assistant) {
        return null;
    }

    if(is_string($assistant->settings ?? null)) {
        $assistant->settings = json_decode($assistant->settings ?? '{}');
    }

    if(!is_object($assistant->settings ?? null)) {
        $assistant->settings = (object) [];
    }

    return $assistant;
}

function fcc_ai_get_assistant_for_user(int $user_id, string $assistant_type, string $scope): ?object {
    if($user_id <= 0) {
        return null;
    }

    $assistant_type = fcc_ai_validate_assistant_type($assistant_type);
    if(!$assistant_type) {
        return null;
    }

    $scope = fcc_ai_normalize_scope($scope, $assistant_type);

    fcc_ai_seed_user_assistants($user_id);

    $assistant = db()
        ->where('user_id', $user_id)
        ->where('assistant_type', $assistant_type)
        ->where('scope', $scope)
        ->getOne('fcc_ai_assistants');

    if(!$assistant) {
        return null;
    }

    if(is_string($assistant->settings ?? null)) {
        $assistant->settings = json_decode($assistant->settings ?? '{}');
    }

    if(!is_object($assistant->settings ?? null)) {
        $assistant->settings = (object) [];
    }

    return $assistant;
}

function fcc_ai_get_public_assistant_default_language(int $user_id, string $assistant_type, string $scope = 'public_app', string $fallback_language = 'hr'): string {
    $fallback_language = fcc_ai_normalize_language($fallback_language);

    if($fallback_language === 'auto') {
        $fallback_language = (string) (\Altum\Language::$code ?? \Altum\Language::$default_code ?? 'hr');
    }

    $fallback_language = fcc_ai_resolve_public_reply_language($fallback_language);

    $assistant = fcc_ai_get_assistant_for_user($user_id, $assistant_type, $scope);
    if(!$assistant) {
        return $fallback_language;
    }

    $assistant_language = fcc_ai_normalize_language((string) ($assistant->language ?? ''));
    if($assistant_language !== 'auto') {
        return fcc_ai_resolve_public_reply_language($assistant_language);
    }

    $settings = $assistant->settings ?? (object) [];
    $settings_language = fcc_ai_normalize_language((string) ($settings->language_mode ?? ''));

    if($settings_language !== 'auto') {
        return fcc_ai_resolve_public_reply_language($settings_language);
    }

    return $fallback_language;
}

function fcc_ai_get_user_plan_settings($user): \stdClass {
    if(is_numeric($user)) {
        $user_id = (int) $user;
        $user = $user_id > 0
            ? db()->where('user_id', $user_id)->getOne('users', ['user_id', 'plan_id', 'plan_settings'])
            : null;
    }

    if(!$user || !is_object($user)) {
        return (object) [];
    }

    $current_plan_settings = fcc_ai_to_object($user->plan_settings ?? null);
    $resolved_plan_settings = null;
    $plan_id = (string) ($user->plan_id ?? '');

    if($plan_id === 'free') {
        $resolved_plan_settings = fcc_ai_to_object(settings()->plan_free->settings ?? null);
    } elseif($plan_id === 'custom') {
        $resolved_plan_settings = fcc_ai_to_object(settings()->plan_custom->settings ?? null);
    } elseif(is_numeric($plan_id) && (int) $plan_id > 0) {
        $plan_row = db()->where('plan_id', (int) $plan_id)->getOne('plans', ['plan_id', 'settings']);

        if($plan_row && isset($plan_row->settings)) {
            $resolved_plan_settings = fcc_ai_to_object($plan_row->settings ?? null);
        }
    }

    if(!$resolved_plan_settings instanceof \stdClass || empty((array) $resolved_plan_settings)) {
        return $current_plan_settings;
    }

    $user_id = (int) ($user->user_id ?? 0);
    if($user_id > 0 && json_encode($current_plan_settings) !== json_encode($resolved_plan_settings)) {
        db()->where('user_id', $user_id)->update('users', [
            'plan_settings' => json_encode($resolved_plan_settings),
        ]);

        cache()->deleteItemsByTag('user_id=' . $user_id);
    }

    return $resolved_plan_settings;
}

function fcc_ai_user_has_public_ai_access($user): bool {
    if(\Altum\Authentication::is_admin()) {
        return true;
    }

    $plan_settings = fcc_ai_get_user_plan_settings($user);

    if(!property_exists($plan_settings, 'fcc_ai_is_enabled')) {
        return true;
    }

    return (bool) ($plan_settings->fcc_ai_is_enabled ?? false);
}

function fcc_ai_user_has_coach_access($user): bool {
    if(\Altum\Authentication::is_admin()) {
        return true;
    }

    $plan_settings = fcc_ai_get_user_plan_settings($user);

    if(!property_exists($plan_settings, 'fcc_coach_is_enabled')) {
        return true;
    }

    return (bool) ($plan_settings->fcc_coach_is_enabled ?? false);
}

function fcc_ai_is_plan_expiration_active(?string $plan_expiration_date = null): bool {
    $plan_expiration_date = trim((string) ($plan_expiration_date ?? ''));

    if($plan_expiration_date === '') {
        return true;
    }

    try {
        return (new \DateTimeImmutable($plan_expiration_date)) >= (new \DateTimeImmutable());
    } catch(\Throwable $exception) {
        return false;
    }
}

function fcc_ai_user_has_active_growth_pro($user): bool {
    if(\Altum\Authentication::is_admin()) {
        return true;
    }

    $plan_settings = fcc_ai_get_user_plan_settings($user);

    if(empty($plan_settings->ai_growth_plan_is_enabled ?? false)) {
        return false;
    }

    return fcc_ai_is_plan_expiration_active((string) ($user->plan_expiration_date ?? ''));
}

function fcc_ai_get_leader_ai_access_object($preferences): \stdClass {
    $preferences = fcc_ai_to_object($preferences);
    $access = fcc_ai_to_object($preferences->leader_ai_access ?? null);

    return $access instanceof \stdClass ? $access : (object) [];
}

function fcc_ai_normalize_manual_ai_tier(string $manual_tier): string {
    $manual_tier = trim(mb_strtolower($manual_tier));

    return match($manual_tier) {
        'qualified', 'signal_ready', 'analysis_ready', 'pro_active' => 'qualified',
        'top', 'top_qualified', 'top_signal', 'pro_vip' => 'top',
        'pro', 'pro_start' => 'pro',
        default => '',
    };
}

function fcc_ai_get_active_manual_ai_tier($access, int $duration_days = 30): string {
    $access = fcc_ai_to_object($access);
    $manual_tier = fcc_ai_normalize_manual_ai_tier((string) ($access->manual_tier ?? ''));
    $manual_unlocked_at = trim((string) ($access->manual_unlocked_at ?? ''));

    if($manual_tier === '' || $manual_unlocked_at === '') {
        return '';
    }

    try {
        $expires_at = (new \DateTimeImmutable($manual_unlocked_at))->modify('+' . max(1, $duration_days) . ' days');
        return $expires_at >= (new \DateTimeImmutable()) ? $manual_tier : '';
    } catch(\Throwable $exception) {
        return '';
    }
}

function fcc_ai_is_valid_forever_sales_link_url($url): bool {
    if(function_exists('fc_is_valid_forever_sales_link_url')) {
        return fc_is_valid_forever_sales_link_url($url);
    }

    $url = mb_strtolower(trim((string) $url));

    return str_starts_with($url, 'https://thealoeveraco.shop/');
}

function fcc_ai_get_user_sales_link_summary(object $user, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $user_id = (int) ($user->user_id ?? 0);
    $main_biolink_id = $user_id > 0 ? (int) (fc_get_user_main_biolink_id($user_id) ?? 0) : 0;
    $editor_url = $main_biolink_id > 0 ? url('link/' . $main_biolink_id . '?tab=blocks') : url('links');
    $links_url = url('links');
    $education_url = url('fcc-education');
    $video_tutorial_url = 'https://www.youtube.com/watch?v=8tBJiDu1EWc';

    $summary = [
        'main_biolink_id' => $main_biolink_id,
        'editor_url' => $editor_url,
        'links_url' => $links_url,
        'education_url' => $education_url,
        'video_tutorial_url' => $video_tutorial_url,
        'block_type' => 'link_discount',
        'has_any_block' => false,
        'has_enabled_block' => false,
        'has_valid_enabled_link' => false,
        'has_invalid_enabled_link' => false,
        'has_disabled_block' => false,
        'main_app_has_block' => false,
        'main_app_has_enabled_block' => false,
        'main_app_has_valid_enabled_link' => false,
        'main_app_has_invalid_enabled_link' => false,
        'main_app_has_disabled_block' => false,
        'main_app_apply_to_all_products' => false,
        'product_referral_ready' => false,
        'is_priority_missing' => false,
        'status_key' => 'missing',
        'status_label' => $language === 'en' ? 'Forever sales link is missing' : 'Forever prodajni link nije postavljen',
    ];

    if($user_id <= 0) {
        return $summary;
    }

    $sales_blocks = db()
        ->where('user_id', $user_id)
        ->where('type', 'link_discount')
        ->orderBy('is_enabled', 'DESC')
        ->orderBy('link_id', 'ASC')
        ->orderBy('`order`', 'ASC')
        ->get('biolinks_blocks', null, ['biolink_block_id', 'link_id', 'is_enabled', 'location_url', 'settings']);

    foreach((array) $sales_blocks as $sales_block) {
        $summary['has_any_block'] = true;
        $link_id = (int) ($sales_block->link_id ?? 0);
        $is_enabled = (int) ($sales_block->is_enabled ?? 0) === 1;
        $is_valid = $is_enabled && fcc_ai_is_valid_forever_sales_link_url($sales_block->location_url ?? '');
        $settings = fcc_ai_decode_biolink_block_settings($sales_block->settings ?? null);
        $apply_to_all_products = !empty($settings->apply_to_all_products);
        $is_main_app_block = $main_biolink_id > 0 && $link_id === $main_biolink_id;

        if($is_enabled) {
            $summary['has_enabled_block'] = true;
        } else {
            $summary['has_disabled_block'] = true;
        }

        if($is_valid) {
            $summary['has_valid_enabled_link'] = true;
        } elseif($is_enabled) {
            $summary['has_invalid_enabled_link'] = true;
        }

        if(!$is_main_app_block) {
            continue;
        }

        $summary['main_app_has_block'] = true;

        if($is_enabled) {
            $summary['main_app_has_enabled_block'] = true;
        } else {
            $summary['main_app_has_disabled_block'] = true;
        }

        if($is_valid) {
            $summary['main_app_has_valid_enabled_link'] = true;
            $summary['main_app_apply_to_all_products'] = $summary['main_app_apply_to_all_products'] || $apply_to_all_products;
        } elseif($is_enabled) {
            $summary['main_app_has_invalid_enabled_link'] = true;
        }
    }

    $summary['product_referral_ready'] = $summary['main_app_has_valid_enabled_link'] && $summary['main_app_apply_to_all_products'];
    $summary['is_priority_missing'] = !$summary['has_valid_enabled_link'];

    if($summary['has_valid_enabled_link']) {
        if($summary['main_app_has_valid_enabled_link'] && !$summary['main_app_apply_to_all_products']) {
            $summary['status_key'] = 'ready_limited';
            $summary['status_label'] = $language === 'en'
                ? 'Forever sales link is active, but not applied to all products'
                : 'Forever prodajni link je aktivan, ali nije primijenjen na sve proizvode';
        } else {
            $summary['status_key'] = 'ready';
            $summary['status_label'] = $language === 'en'
                ? 'Forever sales link is active'
                : 'Forever prodajni link je aktivan';
        }
    } elseif($summary['has_invalid_enabled_link']) {
        $summary['status_key'] = 'invalid';
        $summary['status_label'] = $language === 'en'
            ? 'Forever sales link exists, but it is not valid'
            : 'Forever prodajni link postoji, ali nije valjan';
    } elseif($summary['has_disabled_block']) {
        $summary['status_key'] = 'disabled';
        $summary['status_label'] = $language === 'en'
            ? 'Forever sales link is currently disabled'
            : 'Forever prodajni link je trenutno ugašen';
    } else {
        $summary['status_key'] = 'missing';
        $summary['status_label'] = $language === 'en'
            ? 'Forever sales link is missing'
            : 'Forever prodajni link nije postavljen';
    }

    return $summary;
}

function fcc_ai_decode_biolink_block_settings($value): \stdClass {
    if(is_string($value)) {
        $value = json_decode($value ?? '{}');
    }

    if(is_array($value)) {
        $value = (object) $value;
    }

    return $value instanceof \stdClass ? $value : (object) [];
}

function fcc_ai_is_whatsapp_signal_block(string $type, \stdClass $settings): bool {
    $type = trim(mb_strtolower($type));

    if($type === 'custom_html_whatsapp') {
        return true;
    }

    if($type === 'socials') {
        $socials = $settings->socials ?? null;

        if(is_object($socials)) {
            $socials = (array) $socials;
        }

        if(!is_array($socials)) {
            return false;
        }

        $whatsapp_value = trim((string) ($socials['whatsapp'] ?? ''));
        if($whatsapp_value === '') {
            return false;
        }

        foreach($socials as $social_key => $social_value) {
            if($social_key === 'whatsapp') {
                continue;
            }

            if(trim((string) $social_value) !== '') {
                return false;
            }
        }

        return true;
    }

    if($type !== 'link') {
        return false;
    }

    $location_url = trim((string) ($settings->location_url ?? ''));
    if($location_url === '') {
        return false;
    }

    $location_url = mb_strtolower($location_url);

    return str_contains($location_url, 'wa.me')
        || str_contains($location_url, 'api.whatsapp.com');
}

function fcc_ai_get_user_growth_signal_snapshot(int $user_id, int $link_id = 0): array {
    $payload = [
        'main_link_id' => 0,
        'growth_signal_30d' => 0,
        'growth_signal_7d' => 0,
        'shop_contacts_30d' => 0,
        'shop_contacts_7d' => 0,
        'whatsapp_contacts_30d' => 0,
        'whatsapp_contacts_7d' => 0,
        'funnel_registrations_30d' => 0,
        'funnel_registrations_7d' => 0,
        'ai_chat_leads_30d' => 0,
        'ai_chat_leads_7d' => 0,
        'qualified_target' => 15,
        'top_target' => 50,
        'weekly_check_target' => 15,
    ];

    if($user_id <= 0) {
        return $payload;
    }

    if($link_id <= 0) {
        $link_id = (int) (fc_get_user_main_biolink_id($user_id) ?? 0);
    }

    $payload['main_link_id'] = $link_id;

    if($link_id <= 0) {
        return $payload;
    }

    $tracked_blocks = [
        'shop' => [],
        'whatsapp' => [],
        'funnel' => [],
    ];
    $shop_block_types = [
        'link_discount',
        'link_forever_living_bih',
        'link_forever_living_alb_kosovo',
        'link_forever_living_albania_kosovo',
        'link_forever_shop',
    ];

    $blocks_result = database()->query("SELECT `biolink_block_id`, `type`, `settings`
        FROM `biolinks_blocks`
        WHERE `link_id` = {$link_id}
          AND `is_enabled` = 1");

    if($blocks_result) {
        while($row = $blocks_result->fetch_object()) {
            $block_id = (int) ($row->biolink_block_id ?? 0);
            $type = trim((string) ($row->type ?? ''));
            $settings = fcc_ai_decode_biolink_block_settings($row->settings ?? null);

            if($block_id <= 0 || $type === '') {
                continue;
            }

            if(in_array($type, $shop_block_types, true)) {
                $tracked_blocks['shop'][] = $block_id;
            }

            if($type === 'lead_funnel') {
                $tracked_blocks['funnel'][] = $block_id;
            }

            if(fcc_ai_is_whatsapp_signal_block($type, $settings)) {
                $tracked_blocks['whatsapp'][] = $block_id;
            }
        }
    }

    $periods = [
        '30d' => (new \DateTimeImmutable())->sub(new \DateInterval('P29D'))->format('Y-m-d 00:00:00'),
        '7d' => (new \DateTimeImmutable())->sub(new \DateInterval('P6D'))->format('Y-m-d 00:00:00'),
    ];

    foreach($periods as $period_key => $period_start_datetime) {
        $all_track_block_ids = array_values(array_unique(array_merge($tracked_blocks['shop'], $tracked_blocks['whatsapp'])));

        if(!empty($all_track_block_ids)) {
            $block_ids_sql = implode(',', array_map('intval', $all_track_block_ids));
            $track_result = database()->query("SELECT `biolink_block_id`, COUNT(*) AS `total`
                FROM `track_links`
                WHERE `datetime` >= '{$period_start_datetime}'
                  AND `is_unique` = 1
                  AND `biolink_block_id` IN ({$block_ids_sql})
                GROUP BY `biolink_block_id`");

            if($track_result) {
                while($track_row = $track_result->fetch_object()) {
                    $block_id = (int) ($track_row->biolink_block_id ?? 0);
                    $total = (int) ($track_row->total ?? 0);

                    if(in_array($block_id, $tracked_blocks['shop'], true)) {
                        $payload['shop_contacts_' . $period_key] += $total;
                    }

                    if(in_array($block_id, $tracked_blocks['whatsapp'], true)) {
                        $payload['whatsapp_contacts_' . $period_key] += $total;
                    }
                }
            }
        }

        if(!empty($tracked_blocks['funnel'])) {
            $funnel_ids_sql = implode(',', array_map('intval', $tracked_blocks['funnel']));
            $funnel_result = database()->query("SELECT `biolink_block_id`, COUNT(*) AS `total`
                FROM `data`
                WHERE `type` = 'lead_funnel'
                  AND `datetime` >= '{$period_start_datetime}'
                  AND `biolink_block_id` IN ({$funnel_ids_sql})
                GROUP BY `biolink_block_id`");

            if($funnel_result) {
                while($funnel_row = $funnel_result->fetch_object()) {
                    $payload['funnel_registrations_' . $period_key] += (int) ($funnel_row->total ?? 0);
                }
            }
        }

        $chat_leads = fcc_ai_get_chat_lead_counts_by_link_ids([$link_id], $period_start_datetime);
        $payload['ai_chat_leads_' . $period_key] = (int) ($chat_leads[$link_id] ?? 0);
        $payload['growth_signal_' . $period_key] = (int) (
            (int) ($payload['shop_contacts_' . $period_key] ?? 0)
            + (int) ($payload['whatsapp_contacts_' . $period_key] ?? 0)
            + (int) ($payload['funnel_registrations_' . $period_key] ?? 0)
            + (int) ($payload['ai_chat_leads_' . $period_key] ?? 0)
        );
    }

    return $payload;
}

function fcc_ai_get_user_public_visibility_signal_snapshot(int $user_id): array {
    $payload = [
        'qualified_clicks_30d' => 0,
        'qualified_clicks_7d' => 0,
        'app_clicks_30d' => 0,
        'app_clicks_7d' => 0,
        'blog_clicks_30d' => 0,
        'blog_clicks_7d' => 0,
        'qualified_target' => 15,
        'top_target' => 50,
        'weekly_check_target' => 15,
        /* Backward-compatible aliases for public-layer callers and views. */
        'growth_signal_30d' => 0,
        'growth_signal_7d' => 0,
    ];

    if($user_id <= 0) {
        return $payload;
    }

    $qualified_block_types = \Altum\Link::get_fcc_results_qualified_block_types();
    $qualified_block_types_sql = "'" . implode("','", array_map(static function($value) {
        return database()->real_escape_string((string) $value);
    }, $qualified_block_types)) . "'";
    $blog_mediums = \Altum\Link::get_fcc_results_qualified_blog_mediums();
    $blog_mediums_sql = "'" . implode("','", array_map(static function($value) {
        return database()->real_escape_string((string) $value);
    }, $blog_mediums)) . "'";
    $qualified_click_condition_sql = \Altum\Link::get_fcc_results_qualified_click_condition_sql('`track_links`', '`biolinks_blocks`');

    $periods = [
        '30d' => (new \DateTimeImmutable())->sub(new \DateInterval('P29D'))->format('Y-m-d 00:00:00'),
        '7d' => (new \DateTimeImmutable())->sub(new \DateInterval('P6D'))->format('Y-m-d 00:00:00'),
    ];

    foreach($periods as $period_key => $period_start_datetime) {
        $result = database()->query("SELECT
                SUM(CASE WHEN {$qualified_click_condition_sql} AND `track_links`.`is_unique` = 1 THEN 1 ELSE 0 END) AS `qualified_clicks`,
                SUM(CASE WHEN `biolinks_blocks`.`type` IN ({$qualified_block_types_sql}) AND `track_links`.`is_unique` = 1 THEN 1 ELSE 0 END) AS `app_clicks`,
                SUM(CASE WHEN `track_links`.`utm_medium` IN ({$blog_mediums_sql}) AND `track_links`.`is_unique` = 1 THEN 1 ELSE 0 END) AS `blog_clicks`
            FROM `track_links`
            LEFT JOIN `biolinks_blocks` ON `track_links`.`biolink_block_id` = `biolinks_blocks`.`biolink_block_id`
            WHERE `track_links`.`user_id` = {$user_id}
              AND `track_links`.`datetime` >= '{$period_start_datetime}'");

        $row = $result ? $result->fetch_object() : null;
        $qualified_clicks = max(0, (int) ($row->qualified_clicks ?? 0));
        $app_clicks = max(0, (int) ($row->app_clicks ?? 0));
        $blog_clicks = max(0, (int) ($row->blog_clicks ?? 0));

        $payload['qualified_clicks_' . $period_key] = $qualified_clicks;
        $payload['app_clicks_' . $period_key] = $app_clicks;
        $payload['blog_clicks_' . $period_key] = $blog_clicks;
        $payload['growth_signal_' . $period_key] = $qualified_clicks;
    }

    return $payload;
}

