function fcc_ai_safe_settings_bucket(string $key): \stdClass {
    try {
        $settings = settings();
        $bucket = $settings->{$key} ?? null;

        return is_object($bucket) ? $bucket : (object) [];
    } catch(\Throwable $exception) {
        return (object) [];
    }
}

function fcc_ai_get_openai_api_key(): string {
    $main_settings = fcc_ai_safe_settings_bucket('main');
    $aix_settings = fcc_ai_safe_settings_bucket('aix');
    $main_api_key = trim((string) ($main_settings->openai_api_key ?? ''));

    if($main_api_key !== '') {
        return $main_api_key;
    }

    return trim((string) ($aix_settings->openai_api_key ?? ''));
}

function fcc_ai_get_available_models(): array {
    return [
        'gpt-5.4',
        'gpt-5.4-mini',
        'gpt-5.4-nano',
        'gpt-5.4-pro',
        'gpt-5-mini',
        'gpt-5-nano',
        'gpt-4.1',
        'gpt-4.1-mini',
    ];
}

function fcc_ai_get_global_default_model(): string {
    $main_settings = fcc_ai_safe_settings_bucket('main');
    $aix_settings = fcc_ai_safe_settings_bucket('aix');
    $configured_model = trim((string) ($main_settings->openai_model ?? ''));

    if($configured_model === '') {
        $configured_model = trim((string) ($aix_settings->openai_model ?? ''));
    }

    return fc_get_resolved_openai_model($configured_model);
}

function fcc_ai_get_model_routing_defaults(): array {
    return [
        'coach_beginner' => '',
        'coach_vip' => '',
        'product_advisor' => '',
        'pets_advisor' => '',
        'los_team_strategist' => '',
        'los_leader_detail' => '',
        'support_ticket_ai' => '',
        'fallback' => '',
    ];
}

function fcc_ai_get_model_routing_config(): array {
    $settings_bucket = fcc_ai_safe_settings_bucket('fcc_ai');
    $raw_routing = $settings_bucket->model_routing ?? [];

    if(is_object($raw_routing)) {
        $raw_routing = (array) $raw_routing;
    }

    if(!is_array($raw_routing)) {
        $raw_routing = [];
    }

    $available_models = array_fill_keys(fcc_ai_get_available_models(), true);
    $routing = fcc_ai_get_model_routing_defaults();

    if(!empty($raw_routing['coach'])) {
        $legacy_coach_model = trim((string) $raw_routing['coach']);

        if(empty($raw_routing['coach_beginner'])) {
            $raw_routing['coach_beginner'] = $legacy_coach_model;
        }

        if(empty($raw_routing['coach_vip'])) {
            $raw_routing['coach_vip'] = $legacy_coach_model;
        }
    }

    foreach($routing as $route_key => $default_value) {
        $candidate = trim((string) ($raw_routing[$route_key] ?? ''));
        $routing[$route_key] = $candidate !== '' && isset($available_models[$candidate]) ? fc_get_resolved_openai_model($candidate) : '';
    }

    return $routing;
}

function fcc_ai_resolve_model_route(string $route_key = 'fallback'): string {
    $routing = fcc_ai_get_model_routing_config();
    $route_key = array_key_exists($route_key, $routing) ? $route_key : 'fallback';
    $configured_model = trim((string) ($routing[$route_key] ?? ''));

    if($configured_model === '' && $route_key !== 'fallback') {
        $configured_model = trim((string) ($routing['fallback'] ?? ''));
    }

    if($configured_model === '') {
        $configured_model = fcc_ai_get_global_default_model();
    }

    return fc_get_resolved_openai_model($configured_model);
}

function fcc_ai_get_assistant_model_route_key(string $assistant_type): string {
    $assistant_type = trim($assistant_type);

    return match($assistant_type) {
        'coach' => 'coach_vip',
        'pets_advisor' => 'pets_advisor',
        'product_advisor' => 'product_advisor',
        default => 'fallback',
    };
}

function fcc_ai_resolve_assistant_model(?object $assistant = null): string {
    $assistant_type = trim((string) ($assistant->assistant_type ?? ''));
    $route_key = fcc_ai_get_assistant_model_route_key($assistant_type);

    if($route_key !== 'fallback') {
        return fcc_ai_resolve_model_route($route_key);
    }

    $assistant_model = trim((string) ($assistant->model ?? ''));
    if($assistant_model !== '') {
        return fc_get_resolved_openai_model($assistant_model);
    }

    return fcc_ai_resolve_model_route($route_key);
}

function fcc_ai_get_user_ai_plan_summary(object $user, string $language = 'hr'): array {
    $preferences = fcc_ai_to_object($user->preferences ?? null);
    $plan_settings = fcc_ai_to_object($user->plan_settings ?? null);
    $access = fcc_ai_get_leader_ai_access_object($preferences);
    $profile = fcc_ai_to_object($preferences->leader_ai_profile ?? null);
    $mentor = fcc_ai_to_object($preferences->leader_ai_admin_coaching ?? null);

    $weekly_checkins = [];
    foreach(fcc_ai_to_array($preferences->leader_ai_weekly_checkins ?? []) as $item) {
        $item = fcc_ai_to_array($item);

        if(!$item) {
            continue;
        }

        $weekly_checkins[] = [
            'submitted_at' => $item['submitted_at'] ?? null,
            'weekly_priority' => (string) ($item['weekly_priority'] ?? ''),
            'weekly_priority_label' => fcc_ai_humanize_choice('weekly_priority', $item['weekly_priority'] ?? '', $language),
            'content_commitment' => (string) ($item['content_commitment'] ?? ''),
            'content_commitment_label' => fcc_ai_humanize_choice('content_commitment', $item['content_commitment'] ?? '', $language),
            'follow_up_volume' => (string) ($item['follow_up_volume'] ?? ''),
            'follow_up_volume_label' => fcc_ai_humanize_choice('follow_up_volume', $item['follow_up_volume'] ?? '', $language),
            'ai_need' => (string) ($item['ai_need'] ?? ''),
            'ai_need_label' => fcc_ai_humanize_choice('ai_need', $item['ai_need'] ?? '', $language),
            'weekly_energy' => (string) ($item['weekly_energy'] ?? ''),
            'weekly_energy_label' => fcc_ai_humanize_choice('weekly_energy', $item['weekly_energy'] ?? '', $language),
            'weekly_context' => (string) ($item['weekly_context'] ?? ''),
            'weekly_context_preview' => fcc_ai_excerpt((string) ($item['weekly_context'] ?? ''), 240),
            'adaptive_answer' => (string) ($item['adaptive_answer'] ?? ''),
            'adaptive_answer_preview' => fcc_ai_excerpt((string) ($item['adaptive_answer'] ?? ''), 180),
        ];
    }
    $weekly_checkins = fcc_ai_sort_items_by_datetimes($weekly_checkins, ['submitted_at']);

    $weekly_plans = [];
    foreach(fcc_ai_to_array($preferences->leader_ai_weekly_plans ?? []) as $item) {
        $item = fcc_ai_to_array($item);

        if(!$item) {
            continue;
        }

        $daily_plan = [];
        foreach(array_slice(fcc_ai_to_array($item['daily_plan'] ?? []), 0, 3) as $day_item) {
            $day_item = fcc_ai_to_array($day_item);

            if(!$day_item) {
                continue;
            }

            $tasks = array_values(array_filter(array_map(static function($task) {
                return is_scalar($task) ? trim((string) $task) : '';
            }, fcc_ai_to_array($day_item['tasks'] ?? []))));

            $daily_plan[] = [
                'day' => (string) ($day_item['day'] ?? ''),
                'title' => (string) ($day_item['title'] ?? ''),
                'tasks' => array_slice($tasks, 0, 3),
            ];
        }

        $weekly_plans[] = [
            'checkin_submitted_at' => $item['checkin_submitted_at'] ?? null,
            'generated_at' => $item['generated_at'] ?? null,
            'headline' => (string) ($item['headline'] ?? ''),
            'summary' => (string) ($item['summary'] ?? ''),
            'summary_preview' => fcc_ai_excerpt((string) ($item['summary'] ?? ''), 260),
            'focus' => (string) ($item['focus'] ?? ''),
            'coach_intro' => (string) ($item['coach_intro'] ?? ''),
            'brutal_truth' => (string) ($item['brutal_truth'] ?? ''),
            'brutal_truth_preview' => fcc_ai_excerpt((string) ($item['brutal_truth'] ?? ''), 220),
            'power_move' => (string) ($item['power_move'] ?? ''),
            'why_this_week' => (string) ($item['why_this_week'] ?? ''),
            'encouragement' => (string) ($item['encouragement'] ?? ''),
            'priority_channels' => array_values(array_filter(array_map(static function($channel) use ($language) {
                return is_scalar($channel) ? fcc_ai_humanize_choice('active_channels', (string) $channel, $language) : '';
            }, fcc_ai_to_array($item['priority_channels'] ?? [])))),
            'content_ideas' => array_slice(array_values(array_filter(array_map(static function($idea) {
                return is_scalar($idea) ? trim((string) $idea) : '';
            }, fcc_ai_to_array($item['content_ideas'] ?? [])))), 0, 3),
            'coach_ideas' => array_slice(array_values(array_filter(array_map(static function($idea) {
                return is_scalar($idea) ? trim((string) $idea) : '';
            }, fcc_ai_to_array($item['coach_ideas'] ?? (!empty($item['follow_up_script']) ? [$item['follow_up_script']] : []))))), 0, 3),
            'do_not_do' => array_slice(array_values(array_filter(array_map(static function($entry) {
                return is_scalar($entry) ? trim((string) $entry) : '';
            }, fcc_ai_to_array($item['do_not_do'] ?? [])))), 0, 3),
            'daily_plan' => $daily_plan,
        ];
    }
    $weekly_plans = fcc_ai_sort_items_by_datetimes($weekly_plans, ['checkin_submitted_at', 'generated_at']);

    $weekly_outcomes = [];
    foreach(fcc_ai_to_array($preferences->leader_ai_weekly_outcomes ?? []) as $item) {
        $item = fcc_ai_to_array($item);

        if(!$item) {
            continue;
        }

        $weekly_outcomes[] = [
            'checkin_submitted_at' => $item['checkin_submitted_at'] ?? null,
            'plan_generated_at' => $item['plan_generated_at'] ?? null,
            'selected_link_id' => max(0, (int) ($item['selected_link_id'] ?? 0)),
            'completion_level' => (string) ($item['completion_level'] ?? ''),
            'completion_level_label' => fcc_ai_humanize_choice('completion_level', $item['completion_level'] ?? '', $language),
            'best_response' => (string) ($item['best_response'] ?? ''),
            'main_blocker_now' => (string) ($item['main_blocker_now'] ?? ''),
            'biggest_lesson' => (string) ($item['biggest_lesson'] ?? ''),
            'next_adjustment' => (string) ($item['next_adjustment'] ?? ''),
            'submitted_at' => $item['submitted_at'] ?? null,
        ];
    }
    $weekly_outcomes = fcc_ai_sort_items_by_datetimes($weekly_outcomes, ['checkin_submitted_at', 'submitted_at']);

    $app_reviews = [];
    foreach(fcc_ai_to_array($preferences->leader_ai_app_reviews ?? []) as $item) {
        $item = fcc_ai_to_array($item);

        if(!$item) {
            continue;
        }

        $performance_snapshot = fcc_ai_to_array($item['performance_snapshot'] ?? []);

        $app_reviews[] = [
            'generated_at' => $item['generated_at'] ?? null,
            'review_key' => (string) ($item['review_key'] ?? ($item['generated_at'] ?? '')),
            'selected_link_id' => max(0, (int) ($item['selected_link_id'] ?? 0)),
            'selected_app_name' => (string) ($item['selected_app_name'] ?? ''),
            'selected_app_url' => (string) ($item['selected_app_url'] ?? ''),
            'quality_score' => max(0, (int) ($item['quality_score'] ?? 0)),
            'quality_level' => (string) ($item['quality_level'] ?? ''),
            'headline' => (string) ($item['headline'] ?? ''),
            'summary' => (string) ($item['summary'] ?? ''),
            'summary_preview' => fcc_ai_excerpt((string) ($item['summary'] ?? ''), 220),
            'top_recommendation' => (string) ($item['top_recommendation'] ?? ''),
            'top_recommendation_preview' => fcc_ai_excerpt((string) ($item['top_recommendation'] ?? ''), 220),
            'first_move' => (string) ($item['first_move'] ?? ''),
            'weighted_signal_score' => max(0, (int) ($performance_snapshot['weighted_signal_score'] ?? 0)),
        ];
    }
    $app_reviews = fcc_ai_sort_items_by_datetimes($app_reviews, ['generated_at']);

    $has_profile = trim((string) ($profile->primary_goal ?? '')) !== '';
    $profile_complete = (bool) (
        trim((string) ($profile->primary_goal ?? '')) !== ''
        && trim((string) ($profile->priority_offer ?? '')) !== ''
        && !empty(fcc_ai_to_array($profile->active_channels ?? []))
        && trim((string) ($profile->available_time ?? '')) !== ''
        && trim((string) ($profile->biggest_blocker ?? '')) !== ''
        && trim((string) ($profile->communication_style ?? '')) !== ''
        && trim((string) ($profile->follow_up_readiness ?? '')) !== ''
        && trim((string) ($profile->weekly_change ?? '')) !== ''
    );

    $latest_weekly_checkin = $weekly_checkins[0] ?? [];
    $latest_weekly_plan = $weekly_plans[0] ?? [];
    $latest_weekly_outcome = $weekly_outcomes[0] ?? [];
    $latest_app_review = $app_reviews[0] ?? [];
    $manual_tier = fcc_ai_get_active_manual_ai_tier($access);
    $mentor_guidance = trim((string) ($mentor->ai_guidance ?? ''));
    $is_pro = fcc_ai_user_has_active_growth_pro($user);
    $coach_summary = fcc_ai_get_internal_coach_mode_payload($user, $language);
    $sales_link_summary = fcc_ai_get_user_sales_link_summary($user, $language);
    $portfolio_summary = fcc_ai_get_user_app_portfolio_summary($user, $language);
    $active_campaign = fcc_ai_get_active_internal_coach_campaign($user, $language);
    $signal_snapshot = fcc_ai_get_user_growth_signal_snapshot(
        (int) ($user->user_id ?? 0),
        (int) (fc_get_user_main_biolink_id((int) ($user->user_id ?? 0)) ?? 0)
    );
    $public_signal_snapshot = fcc_ai_get_user_public_visibility_signal_snapshot((int) ($user->user_id ?? 0));
    $growth_signal_30d = (int) ($signal_snapshot['growth_signal_30d'] ?? 0);
    $growth_signal_7d = (int) ($signal_snapshot['growth_signal_7d'] ?? 0);
    $public_signal_30d = (int) ($public_signal_snapshot['growth_signal_30d'] ?? 0);
    $public_signal_7d = (int) ($public_signal_snapshot['growth_signal_7d'] ?? 0);
    $analysis_unlocked = $is_pro && ($growth_signal_30d >= 15 || in_array($manual_tier, ['qualified', 'top'], true));
    $top_performer = $is_pro && ($public_signal_30d >= 50 || $manual_tier === 'top');
    $weekly_check_passed = $public_signal_7d >= 15;
    $starter_app_review_used = min(1, max(0, (int) ($access->starter_app_review_used ?? (!empty($app_reviews) ? 1 : 0))));
    $starter_weekly_plan_used = min(1, max(0, (int) ($access->starter_weekly_plan_used ?? (!empty($weekly_plans) ? 1 : 0))));
    $starter_app_review_available = $is_pro && !$analysis_unlocked && !$starter_app_review_used;
    $starter_weekly_plan_available = $is_pro && !$analysis_unlocked && !$starter_weekly_plan_used;
    $starter_cycle_available = $starter_app_review_available || $starter_weekly_plan_available;
    $app_review_cooldown = $analysis_unlocked ? fcc_ai_get_unlock_cooldown_payload((string) ($latest_app_review['generated_at'] ?? ''), 7) : ['is_locked' => false, 'next_at' => null];
    $weekly_cooldown = $analysis_unlocked ? fcc_ai_get_unlock_cooldown_payload((string) ($latest_weekly_checkin['submitted_at'] ?? ''), 7) : ['is_locked' => false, 'next_at' => null];
    $has_latest_app_review = !empty($latest_app_review['generated_at']);
    $weekly_requires_review = $has_latest_app_review;
    $app_review_available_now = \Altum\Authentication::is_admin()
        || $starter_app_review_available
        || ($analysis_unlocked && empty($app_review_cooldown['is_locked']));
    $weekly_available_now = \Altum\Authentication::is_admin()
        || ($starter_weekly_plan_available && $weekly_requires_review)
        || ($analysis_unlocked && $weekly_requires_review && empty($weekly_cooldown['is_locked']));
    $app_review_locked = !$starter_app_review_available && $analysis_unlocked && !empty($app_review_cooldown['is_locked']);
    $weekly_locked = !$starter_weekly_plan_available && $analysis_unlocked && $weekly_requires_review && !empty($weekly_cooldown['is_locked']);
    $app_review_next_at = $app_review_locked ? (string) ($app_review_cooldown['next_at'] ?? '') : '';
    $weekly_next_at = $weekly_locked ? (string) ($weekly_cooldown['next_at'] ?? '') : '';
    $app_review_countdown_days = fcc_ai_get_unlock_countdown_days($app_review_next_at);
    $weekly_countdown_days = fcc_ai_get_unlock_countdown_days($weekly_next_at);
    $app_review_next_label = fcc_ai_format_unlock_datetime($app_review_next_at);
    $weekly_next_label = fcc_ai_format_unlock_datetime($weekly_next_at);
    $billing_label = \Altum\Authentication::is_admin()
        ? ($language === 'en' ? 'Admin' : 'Admin')
        : ($is_pro ? 'PRO' : 'Beginner');
    if(!$is_pro) {
        $access_label = $language === 'en' ? 'Beginner package active' : 'Aktivan je Beginner paket';
    } elseif($analysis_unlocked) {
        $access_label = $language === 'en' ? 'PRO with weekly AI cycle unlocked' : 'PRO s otključanim tjednim AI ciklusom';
    } elseif($starter_app_review_available && $starter_weekly_plan_available) {
        $access_label = $language === 'en'
            ? 'PRO is active and your initial app review plus first weekly plan are available now'
            : 'PRO je aktivan i početna analiza aplikacije te prvi tjedni plan dostupni su odmah';
    } elseif($starter_app_review_available) {
        $access_label = $language === 'en'
            ? 'PRO is active and your initial app review is available now'
            : 'PRO je aktivan i početna analiza aplikacije dostupna je odmah';
    } elseif($starter_weekly_plan_available) {
        $access_label = $language === 'en'
            ? 'PRO is active and your first weekly plan is available now'
            : 'PRO je aktivan i prvi tjedni plan dostupan je odmah';
    } else {
        $access_label = $language === 'en' ? 'PRO is active, signal is building toward 15+' : 'PRO je aktivan, signal se gradi prema 15+';
    }

    return [
        'has_profile' => $has_profile,
        'profile_complete' => $profile_complete,
        'has_access' => $is_pro,
        'manual_tier' => $manual_tier,
        'access_summary' => [
            'has_access' => $is_pro,
            'is_pro' => $is_pro,
            'billing_label' => $billing_label,
            'manual_tier' => $manual_tier,
            'label' => $access_label,
            'analysis_unlocked' => $analysis_unlocked,
            'top_performer' => $top_performer,
            'weekly_check_passed' => $weekly_check_passed,
            'starter_cycle_available' => $starter_cycle_available,
            'starter_app_review_available' => $starter_app_review_available,
            'starter_weekly_plan_available' => $starter_weekly_plan_available,
        ],
        'coach_summary' => $coach_summary,
        'sales_link_summary' => $sales_link_summary,
        'portfolio_summary' => $portfolio_summary,
        'active_campaign' => $active_campaign,
        'starter_summary' => [
            'app_review_used' => $starter_app_review_used,
            'weekly_plan_used' => $starter_weekly_plan_used,
            'app_review_available' => $starter_app_review_available,
            'weekly_plan_available' => $starter_weekly_plan_available,
            'starter_cycle_available' => $starter_cycle_available,
        ],
        'availability_summary' => [
            'app_review_available_now' => $app_review_available_now,
            'app_review_locked' => $app_review_locked,
            'app_review_next_at' => $app_review_next_at !== '' ? $app_review_next_at : null,
            'app_review_next_label' => $app_review_next_label,
            'app_review_countdown_days' => $app_review_countdown_days,
            'weekly_available_now' => $weekly_available_now,
            'weekly_locked' => $weekly_locked,
            'weekly_next_at' => $weekly_next_at !== '' ? $weekly_next_at : null,
            'weekly_next_label' => $weekly_next_label,
            'weekly_countdown_days' => $weekly_countdown_days,
        ],
        'signal_summary' => [
            'growth_signal_30d' => $growth_signal_30d,
            'growth_signal_7d' => $growth_signal_7d,
            'shop_contacts_30d' => (int) ($signal_snapshot['shop_contacts_30d'] ?? 0),
            'shop_contacts_7d' => (int) ($signal_snapshot['shop_contacts_7d'] ?? 0),
            'whatsapp_contacts_30d' => (int) ($signal_snapshot['whatsapp_contacts_30d'] ?? 0),
            'whatsapp_contacts_7d' => (int) ($signal_snapshot['whatsapp_contacts_7d'] ?? 0),
            'funnel_registrations_30d' => (int) ($signal_snapshot['funnel_registrations_30d'] ?? 0),
            'funnel_registrations_7d' => (int) ($signal_snapshot['funnel_registrations_7d'] ?? 0),
            'ai_chat_leads_30d' => (int) ($signal_snapshot['ai_chat_leads_30d'] ?? 0),
            'ai_chat_leads_7d' => (int) ($signal_snapshot['ai_chat_leads_7d'] ?? 0),
            'qualified_target' => (int) ($signal_snapshot['qualified_target'] ?? 15),
            'top_target' => (int) ($signal_snapshot['top_target'] ?? 50),
            'weekly_check_target' => (int) ($signal_snapshot['weekly_check_target'] ?? 15),
            'missing_to_qualified' => max(0, 15 - $growth_signal_30d),
            'missing_to_top' => max(0, 50 - $growth_signal_30d),
            'missing_to_weekly_check' => max(0, 15 - $growth_signal_7d),
            'weekly_check_passed' => $weekly_check_passed,
        ],
        'public_signal_summary' => [
            'growth_signal_30d' => $public_signal_30d,
            'growth_signal_7d' => $public_signal_7d,
            'app_clicks_30d' => (int) ($public_signal_snapshot['app_clicks_30d'] ?? 0),
            'app_clicks_7d' => (int) ($public_signal_snapshot['app_clicks_7d'] ?? 0),
            'blog_clicks_30d' => (int) ($public_signal_snapshot['blog_clicks_30d'] ?? 0),
            'blog_clicks_7d' => (int) ($public_signal_snapshot['blog_clicks_7d'] ?? 0),
            'qualified_target' => (int) ($public_signal_snapshot['qualified_target'] ?? 15),
            'top_target' => (int) ($public_signal_snapshot['top_target'] ?? 50),
            'weekly_check_target' => (int) ($public_signal_snapshot['weekly_check_target'] ?? 15),
            'missing_to_qualified' => max(0, 15 - $public_signal_30d),
            'missing_to_top' => max(0, 50 - $public_signal_30d),
            'missing_to_weekly_check' => max(0, 15 - $public_signal_7d),
            'weekly_check_passed' => $weekly_check_passed,
        ],
        'profile' => [
            'submitted_at' => $profile->submitted_at ?? null,
            'updated_at' => $profile->updated_at ?? null,
            'primary_goal' => (string) ($profile->primary_goal ?? ''),
            'primary_goal_label' => fcc_ai_humanize_choice('primary_goal', $profile->primary_goal ?? '', $language),
            'priority_offer' => (string) ($profile->priority_offer ?? ''),
            'priority_offer_label' => fcc_ai_humanize_choice('priority_offer', $profile->priority_offer ?? '', $language),
            'active_channels' => array_values(array_filter(array_map(static function($channel) use ($language) {
                return is_scalar($channel) ? fcc_ai_humanize_choice('active_channels', (string) $channel, $language) : '';
            }, fcc_ai_to_array($profile->active_channels ?? [])))),
            'available_time' => (string) ($profile->available_time ?? ''),
            'available_time_label' => fcc_ai_humanize_choice('available_time', $profile->available_time ?? '', $language),
            'biggest_blocker' => (string) ($profile->biggest_blocker ?? ''),
            'biggest_blocker_label' => fcc_ai_humanize_choice('biggest_blocker', $profile->biggest_blocker ?? '', $language),
            'communication_style' => (string) ($profile->communication_style ?? ''),
            'communication_style_label' => fcc_ai_humanize_choice('communication_style', $profile->communication_style ?? '', $language),
            'follow_up_readiness' => (string) ($profile->follow_up_readiness ?? ''),
            'follow_up_readiness_label' => fcc_ai_humanize_choice('follow_up_readiness', $profile->follow_up_readiness ?? '', $language),
            'weekly_change' => (string) ($profile->weekly_change ?? ''),
            'weekly_change_label' => fcc_ai_humanize_choice('weekly_change', $profile->weekly_change ?? '', $language),
            'audience_focus' => trim((string) ($profile->audience_focus ?? '')),
            'product_focus' => trim((string) ($profile->product_focus ?? '')),
            'notes' => fcc_ai_excerpt((string) ($profile->notes ?? ''), 220),
        ],
        'latest_weekly_checkin' => $latest_weekly_checkin,
        'latest_weekly_plan' => $latest_weekly_plan,
        'latest_weekly_outcome' => $latest_weekly_outcome,
        'latest_app_review' => $latest_app_review,
        'mentor_guidance' => [
            'has_guidance' => $mentor_guidance !== '',
            'preview' => fcc_ai_excerpt($mentor_guidance, 260),
        ],
        'counts' => [
            'weekly_checkins' => count($weekly_checkins),
            'weekly_plans' => count($weekly_plans),
            'weekly_outcomes' => count($weekly_outcomes),
            'app_reviews' => count($app_reviews),
        ],
    ];
}

function fcc_ai_get_internal_coach_current_step(array $ai_plan_summary): string {
    $sales_link_summary = is_array($ai_plan_summary['sales_link_summary'] ?? null) ? $ai_plan_summary['sales_link_summary'] : [];

    if(!empty($sales_link_summary['is_priority_missing'])) {
        return 'sales_link';
    }

    if(empty($ai_plan_summary['profile_complete'])) {
        return 'profile';
    }

    if(empty($ai_plan_summary['latest_app_review']['generated_at'])) {
        return 'app_review';
    }

    if(empty($ai_plan_summary['latest_weekly_checkin']['submitted_at']) || empty($ai_plan_summary['latest_weekly_plan']['generated_at'])) {
        return 'weekly';
    }

    return 'plan';
}

function fcc_ai_get_internal_coach_primary_destination(array $ai_plan_summary, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $current_step = fcc_ai_get_internal_coach_current_step($ai_plan_summary);
    $access_summary = is_array($ai_plan_summary['access_summary'] ?? null) ? $ai_plan_summary['access_summary'] : [];
    $starter_summary = is_array($ai_plan_summary['starter_summary'] ?? null) ? $ai_plan_summary['starter_summary'] : [];
    $availability_summary = is_array($ai_plan_summary['availability_summary'] ?? null) ? $ai_plan_summary['availability_summary'] : [];
    $sales_link_summary = is_array($ai_plan_summary['sales_link_summary'] ?? null) ? $ai_plan_summary['sales_link_summary'] : [];
    $latest_app_review = is_array($ai_plan_summary['latest_app_review'] ?? null) ? $ai_plan_summary['latest_app_review'] : [];
    $app_review_locked = !empty($availability_summary['app_review_locked']);
    $app_review_next_label = trim((string) ($availability_summary['app_review_next_label'] ?? ''));
    $weekly_locked = !empty($availability_summary['weekly_locked']);
    $weekly_next_label = trim((string) ($availability_summary['weekly_next_label'] ?? ''));

    if($current_step === 'sales_link') {
        $status_key = trim((string) ($sales_link_summary['status_key'] ?? 'missing'));
        $editor_url = trim((string) ($sales_link_summary['editor_url'] ?? url('links')));
        $title = match($status_key) {
            'disabled' => $language === 'en' ? 'Reactivate Forever Web Shop block' : 'Ponovno ukljuci Forever Web trgovina blok',
            'invalid' => $language === 'en' ? 'Fix Forever Web Shop block' : 'Popravi Forever Web trgovina blok',
            default => $language === 'en' ? 'Add Forever Web Shop block' : 'Dodaj Forever Web trgovina blok',
        };

        return [
            'key' => 'sales_link_setup',
            'title' => $title,
            'url' => $editor_url !== '' ? $editor_url : url('links'),
            'description' => match($status_key) {
                'disabled' => $language === 'en'
                    ? 'Your Forever sales link block already exists, but it is turned off. Turn it back on and confirm the Link Builder URL is valid.'
                    : 'Tvoj Forever prodajni link blok vec postoji, ali je ugasen. Ponovno ga ukljuci i potvrdi da je Link Builder URL ispravan.',
                'invalid' => $language === 'en'
                    ? 'Your block exists, but it needs your own valid Forever Link Builder URL that starts with the Aloe Vera Co. link.'
                    : 'Blok vec postoji, ali treba tvoj vlastiti valjani Forever Link Builder URL koji pocinje s The Aloe Vera Co. linkom.',
                default => $language === 'en'
                    ? 'First add the Forever Web Shop block because FCC cannot turn interest into webshop results without it.'
                    : 'Prvo dodaj Forever Web trgovina blok jer bez njega FCC ne moze pretvoriti interes u webshop rezultate.',
            },
        ];
    }

    if(empty($access_summary['is_pro'])) {
        return [
            'key' => 'account_plan',
            'title' => $language === 'en' ? 'Activate PRO' : 'Aktiviraj PRO',
            'url' => url('account-plan'),
            'description' => $language === 'en'
                ? 'Turn on PRO or trial to unlock VIP Coach and the stronger AI cycle.'
                : 'Uključi PRO ili trial kako bi otključao VIP Coach i jači AI ciklus.',
        ];
    }

    if($current_step === 'profile') {
        return [
            'key' => 'ai_profile',
            'title' => $language === 'en' ? 'AI profile' : 'AI profil',
            'url' => url('ai-plan?section=profile#ai-plan-profile-start'),
            'description' => $language === 'en'
                ? 'Complete your growth profile so Coach can personalize the next steps.'
                : 'Dovršite AI profil da Coach može personalizirati sljedeće korake.',
        ];
    }

    if(!empty($starter_summary['app_review_available'])) {
        return [
            'key' => 'ai_app_review',
            'title' => $language === 'en' ? 'Initial app review' : 'Početna analiza aplikacije',
            'url' => url('ai-plan?section=app_review#ai-plan-app-review'),
            'description' => $language === 'en'
                ? 'Run the initial app review now so Coach gets a clear base for your next 7 days.'
                : 'Pokreni početnu analizu aplikacije sada kako bi Coach dobio jasnu bazu za idućih 7 dana.',
        ];
    }

    if(!empty($starter_summary['weekly_plan_available']) && !empty($ai_plan_summary['latest_app_review']['generated_at'])) {
        return [
            'key' => 'ai_weekly',
            'title' => $language === 'en' ? 'First weekly plan' : 'Prvi tjedni plan',
            'url' => url('ai-plan?section=weekly'),
            'description' => $language === 'en'
                ? 'Use your first weekly plan now so Coach can connect the review, your context and the next 7 days.'
                : 'Iskoristi prvi tjedni plan sada kako bi Coach povezao analizu, tvoj kontekst i sljedećih 7 dana.',
        ];
    }

    if(empty($access_summary['analysis_unlocked']) && !empty($ai_plan_summary['profile_complete'])) {
        return [
            'key' => 'dashboard',
            'title' => $language === 'en' ? 'Build signal to 15+' : 'Dođi do 15+',
            'url' => url('dashboard'),
            'description' => $language === 'en'
                ? 'Use the dashboard and daily actions to reach 15+ in the last 30 days.'
                : 'Kroz dashboard i dnevne poteze dođi do 15+ u zadnjih 30 dana.',
        ];
    }

    if($current_step === 'app_review') {
        if($app_review_locked && $app_review_next_label !== '') {
            if(!empty($latest_app_review['selected_link_id'])) {
                return [
                    'key' => 'reviewed_app',
                    'title' => trim((string) ($latest_app_review['selected_app_name'] ?? '')) !== ''
                        ? trim((string) $latest_app_review['selected_app_name'])
                        : ($language === 'en' ? 'Last reviewed app' : 'Zadnja analizirana aplikacija'),
                    'url' => url('link/' . (int) $latest_app_review['selected_link_id'] . '?tab=blocks'),
                    'description' => $language === 'en'
                        ? 'The next app review unlocks on ' . $app_review_next_label . '. Until then, use this app to implement the last recommendations.'
                        : 'Sljedeća analiza aplikacije otključava se ' . $app_review_next_label . '. Do tada na ovoj aplikaciji provedi zadnje preporuke.',
                ];
            }

            return [
                'key' => 'apps',
                'title' => $language === 'en' ? 'Applications' : 'Aplikacije',
                'url' => url('links?type=biolink'),
                'description' => $language === 'en'
                    ? 'The next app review unlocks on ' . $app_review_next_label . '. Until then, improve the live app blocks and structure.'
                    : 'Sljedeća analiza aplikacije otključava se ' . $app_review_next_label . '. Do tada doradi blokove i strukturu aktivne aplikacije.',
            ];
        }

        return [
            'key' => 'ai_app_review',
            'title' => $language === 'en' ? 'App review' : 'Pregled aplikacije',
            'url' => url('ai-plan?section=app_review#ai-plan-app-review'),
            'description' => $language === 'en'
                ? 'Run the latest app review and turn it into concrete app improvements.'
                : 'Pokreni pregled aplikacije i pretvori ga u konkretne dorade.',
        ];
    }

    if($current_step === 'weekly') {
        if($weekly_locked && $weekly_next_label !== '') {
            return [
                'key' => 'ai_plan',
                'title' => $language === 'en' ? 'Current weekly plan' : 'Aktualni tjedni plan',
                'url' => url('ai-plan?section=plan'),
                'description' => $language === 'en'
                    ? 'The next weekly check-in unlocks on ' . $weekly_next_label . '. Until then, execute the current focus and power move.'
                    : 'Novi tjedni check-in otključava se ' . $weekly_next_label . '. Do tada odradi aktualni fokus i power move.',
            ];
        }

        return [
            'key' => 'ai_weekly',
            'title' => $language === 'en' ? 'Weekly check-in' : 'Tjedni check-in',
            'url' => url('ai-plan?section=weekly'),
            'description' => $language === 'en'
                ? 'Submit the weekly context so Coach can build the next plan.'
                : 'Pošaljite tjedni kontekst da Coach složi novi plan.',
        ];
    }

    return [
        'key' => 'ai_plan',
        'title' => $language === 'en' ? 'Weekly plan' : 'Tjedni plan',
        'url' => url('ai-plan?section=plan'),
        'description' => $language === 'en'
            ? 'Review your current focus, power move and execution feedback.'
            : 'Pregledajte aktualni fokus, power move i povratnu informaciju izvedbe.',
    ];
}

function fcc_ai_get_internal_coach_page_context(array $payload, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $source_page_url = trim((string) ($payload['source_page_url'] ?? ''));
    $source_page_slug = trim((string) ($payload['source_page_slug'] ?? ''));
    $source_page_title = trim((string) ($payload['source_page_title'] ?? ''));
    $source_page_section = trim((string) ($payload['source_page_section'] ?? ''));

    if($source_page_slug === '' && $source_page_url !== '') {
        $source_page_slug = trim((string) parse_url($source_page_url, PHP_URL_PATH), '/');
    }

    if($source_page_section === '' && $source_page_url !== '') {
        parse_str((string) parse_url($source_page_url, PHP_URL_QUERY), $query);
        $source_page_section = trim((string) ($query['section'] ?? ''));
    }

    $slug_parts = array_values(array_filter(explode('/', $source_page_slug), static function($part) {
        return $part !== '';
    }));

    $route = $slug_parts[0] ?? '';

    if(in_array($route, ['en', 'hr'], true) && isset($slug_parts[1])) {
        $route = $slug_parts[1];
    }

    $label = $source_page_title;

    if($label === '') {
        $route_labels = [
            'dashboard' => $language === 'en' ? 'Dashboard' : 'Kontrolna ploča',
            'ai-plan' => $language === 'en' ? 'AI Plan' : 'AI Plan',
            'ai-app-review' => $language === 'en' ? 'App review' : 'Pregled aplikacije',
            'links' => $language === 'en' ? 'Applications' : 'Aplikacije',
            'link' => $language === 'en' ? 'Application editor' : 'Uređivač aplikacije',
            'data' => $language === 'en' ? 'Contacts' : 'Kontakti',
            'fcc-ai' => $language === 'en' ? 'AI settings' : 'AI postavke',
            'account-plan' => $language === 'en' ? 'Account plan' : 'Plan paketa',
            'featured-apps' => $language === 'en' ? 'Featured Apps' : 'Istaknute aplikacije',
            'recommended-sponsors' => $language === 'en' ? 'Recommended sponsors' : 'Preporučeni sponzori',
            'fcc-education' => $language === 'en' ? 'FCC education' : 'FCC edukacija',
            'blog' => $language === 'en' ? 'FCC blog' : 'FCC blog',
        ];

        $label = $route_labels[$route] ?? ($language === 'en' ? 'FCC page' : 'FCC stranica');
    }

    if($route === 'ai-plan' && $source_page_section !== '') {
        $section_labels = [
            'profile' => $language === 'en' ? 'profile' : 'profil',
            'app_review' => $language === 'en' ? 'app review' : 'pregled aplikacije',
            'weekly' => $language === 'en' ? 'weekly check-in' : 'tjedni check-in',
            'plan' => $language === 'en' ? 'weekly plan' : 'tjedni plan',
        ];

        $label .= ' · ' . ($section_labels[$source_page_section] ?? $source_page_section);
    }

    return [
        'url' => $source_page_url,
        'slug' => $source_page_slug,
        'title' => $source_page_title,
        'section' => $source_page_section,
        'route' => $route,
        'label' => $label,
    ];
}

function fcc_ai_get_internal_coach_page_priority_instruction(array $page, string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $route = trim((string) ($page['route'] ?? ''));
    $section = trim((string) ($page['section'] ?? ''));
    $slug = trim((string) ($page['slug'] ?? ''));

    if($route === 'dashboard') {
        return $language === 'en'
            ? 'Page priority: help the collaborator identify the single best next move from the dashboard signal, then turn it into a concrete action.'
            : 'Prioritet stranice: pomozi suradniku da iz dashboard signala prepozna jedan najbolji sljedeći potez i pretvori ga u konkretnu akciju.';
    }

    if($route === 'ai-plan' && $section === 'profile') {
        return $language === 'en'
            ? 'Page priority: guide the collaborator through finishing the AI profile with simple field-by-field help, because goal, offer, channels, blocker and style must be clear before stronger execution.'
            : 'Prioritet stranice: vodi suradnika kroz dovršavanje AI profila jednostavno i po poljima, jer cilj, ponuda, kanali, blokada i stil moraju biti jasni prije jače izvedbe.';
    }

    if($route === 'ai-plan' && $section === 'app_review') {
        return $language === 'en'
            ? 'Page priority: keep the conversation centered on the latest app review, first move, top recommendation and the smallest useful edit that should happen next.'
            : 'Prioritet stranice: drži razgovor oko zadnjeg pregleda aplikacije, prvog poteza, top preporuke i najmanje korisne dorade koju sada treba napraviti.';
    }

    if($route === 'ai-plan' && $section === 'weekly') {
        return $language === 'en'
            ? 'Page priority: help the collaborator finish the weekly check-in clearly and turn the current situation into one focused weekly direction.'
            : 'Prioritet stranice: pomozi suradniku jasno završiti tjedni check-in i pretvoriti trenutačnu situaciju u jedan fokusirani tjedni smjer.';
    }

    if($route === 'ai-plan' && $section === 'plan') {
        return $language === 'en'
            ? 'Page priority: help the collaborator execute the weekly plan, protect focus, and translate the plan into daily action, content and follow-up.'
            : 'Prioritet stranice: pomozi suradniku provesti tjedni plan, zaštititi fokus i pretvoriti plan u dnevnu akciju, sadržaj i follow-up.';
    }

    if($route === 'links' || $route === 'link') {
        return $language === 'en'
            ? 'Page priority: improve the FCC app. Focus on clearer structure, stronger CTA, better block order and the next edit that can improve business result. If the Forever sales link is missing, invalid or disabled, prioritize fixing that before other app polish. If the collaborator talks about having too many apps, also help them simplify the portfolio and disable dead-end apps.'
            : 'Prioritet stranice: doradi FCC aplikaciju. Fokus je na jasnijoj strukturi, jacem CTA-u, boljem redoslijedu blokova i sljedecoj doradi koja moze popraviti poslovni rezultat. Ako Forever prodajni link nedostaje, neispravan je ili je ugasen, to popravi prije ostalog poliranja aplikacije. Ako suradnik prica da ima previse aplikacija, pomozi mu i pojednostaviti portfelj te ugasiti slijepa crijeva.';
    }

    if($route === 'data') {
        return $language === 'en'
            ? 'Page priority: help with contacts and follow-up. Point out who to reply to first, what to send next and how to move interest toward conversation or action.'
            : 'Prioritet stranice: pomozi oko kontakata i follow-upa. Izdvoji kome prvo odgovoriti, što poslati dalje i kako interes pomaknuti prema razgovoru ili akciji.';
    }

    if($route === 'fcc-ai') {
        return $language === 'en'
            ? 'Page priority: explain public AI assistants simply. Help the collaborator understand language, tone, intro and rules for the public assistants, without drifting into hidden admin routing or internal-only setup.'
            : 'Prioritet stranice: jednostavno objasni javne AI asistente. Pomozi suradniku razumjeti jezik, ton, intro i pravila za javne asistente, bez skretanja u skrivene admin postavke ili interni setup.';
    }

    if($route === 'account-plan') {
        return $language === 'en'
            ? 'Page priority: explain the plan difference simply, especially Beginner versus PRO, Beginner Coach versus VIP Coach, and which actions unlock the weekly AI cycle.'
            : 'Prioritet stranice: jednostavno objasni razliku paketa, posebno Beginner naspram PRO, Beginner Coach naspram VIP Coach i koje akcije otključavaju tjedni AI ciklus.';
    }

    if($route === 'featured-apps') {
        return $language === 'en'
            ? 'Page priority: explain that 15+ in 30 days is the first public proof layer for Featured Apps, while 50+ in 30 days is the main public goal because it unlocks homepage recommended sponsor positioning, stronger public brand visibility, and a cleaner Google/AI understanding of the collaborator through FCC. Treat 15+ in 7 days only as a rhythm confirmation.'
            : 'Prioritet stranice: objasni da je 15+ u 30 dana prvi javni sloj dokaza za Istaknute aplikacije, dok je 50+ u 30 dana glavni javni cilj jer otključava poziciju preporučenog sponzora na naslovnici, jaču javnu vidljivost branda i jasniji Google/AI signal kroz FCC. 15+ u 7 dana tretiraj samo kao provjeru ritma.';
    }

    if($route === 'recommended-sponsors') {
        return $language === 'en'
            ? 'Page priority: explain that homepage recommended sponsors are the strongest FCC public layer, connect that to the 50+ / 30d signal, and show the collaborator why that matters for sponsor positioning, stronger personal brand visibility, and better Google/AI understanding through FCC. Then guide them toward protecting setup quality, public clarity, and weekly rhythm.'
            : 'Prioritet stranice: objasni da su preporučeni sponzori na naslovnici najjači FCC javni sloj, poveži to s 50+ / 30d signalom i pokaži suradniku zašto je to važno za sponsor pozicioniranje, jaču vidljivost osobnog branda i bolju Google/AI razumljivost kroz FCC. Zatim ga vodi prema zaštiti kvalitete setupa, javne jasnoće i tjednog ritma.';
    }

    if($route === 'blog' && (str_contains($slug, 'blog/category/forever-proizvodi') || str_contains($slug, 'blog/category/forever-products'))) {
        return $language === 'en'
            ? 'Page priority: explain the logged-in product share helper clearly. Show how the collaborator should use the share/copy area at the top of product articles, warn them not to copy the raw URL, and connect Beginner sharing versus the PRO product block and 15+ click-building.'
            : 'Prioritet stranice: jasno objasni prijavljeni helper za dijeljenje proizvoda. Pokaži kako suradnik treba koristiti share/copy dio na vrhu članaka o proizvodima, upozori da ne kopira običan URL i poveži Beginner dijeljenje s PRO blokom proizvoda i gradnjom 15+ klikova.';
    }

    return $language === 'en'
        ? 'Page priority: stay grounded in the current FCC page and turn the user message into the clearest useful next move.'
        : 'Prioritet stranice: ostani vezan uz trenutačnu FCC stranicu i pretvori korisnikov upit u najjasniji korisni sljedeći potez.';
}

function fcc_ai_get_internal_coach_suggestions(array $context, string $message, int $limit = 4): array {
    $language = fcc_ai_resolve_public_reply_language((string) ($context['language'] ?? 'hr'), $message);
    $ai_plan_summary = $context['ai_plan'] ?? [];
    $sales_link_summary = is_array($ai_plan_summary['sales_link_summary'] ?? null) ? $ai_plan_summary['sales_link_summary'] : [];
    $active_campaign = is_array($ai_plan_summary['active_campaign'] ?? null) ? $ai_plan_summary['active_campaign'] : [];
    $page = $context['page'] ?? [];
    $page_route = trim((string) ($page['route'] ?? ''));
    $page_section = trim((string) ($page['section'] ?? ''));
    $normalized_message = mb_strtolower(trim($message));

    $pages = [
        'dashboard' => [
            'title' => $language === 'en' ? 'Dashboard' : 'Dashboard',
            'url' => url('dashboard'),
            'description' => $language === 'en' ? 'Your main FCC overview and next actions.' : 'Glavni FCC pregled i sljedeći koraci.',
        ],
        'ai_profile' => [
            'title' => $language === 'en' ? 'AI profile' : 'AI profil',
            'url' => url('ai-plan?section=profile#ai-plan-profile-start'),
            'description' => $language === 'en' ? 'Goals, offer, channels and blockers.' : 'Ciljevi, ponuda, kanali i blokade.',
        ],
        'ai_app_review' => [
            'title' => $language === 'en' ? 'App review' : 'Pregled aplikacije',
            'url' => url('ai-plan?section=app_review#ai-plan-app-review'),
            'description' => $language === 'en' ? 'Review the app and prioritize improvements.' : 'Pregledajte aplikaciju i prioritetne dorade.',
        ],
        'ai_weekly' => [
            'title' => $language === 'en' ? 'Weekly check-in' : 'Tjedni check-in',
            'url' => url('ai-plan?section=weekly'),
            'description' => $language === 'en' ? 'Update weekly focus and current context.' : 'Ažurirajte tjedni fokus i trenutačni kontekst.',
        ],
        'ai_plan' => [
            'title' => $language === 'en' ? 'Weekly plan' : 'Tjedni plan',
            'url' => url('ai-plan?section=plan'),
            'description' => $language === 'en' ? 'Focus, power move and execution feedback.' : 'Fokus, power move i povratna informacija izvedbe.',
        ],
        'apps' => [
            'title' => $language === 'en' ? 'Applications' : 'Aplikacije',
            'url' => url('links?type=biolink'),
            'description' => $language === 'en' ? 'Open and refine your live FCC apps.' : 'Otvorite i doradite svoje FCC aplikacije.',
        ],
        'contacts' => [
            'title' => $language === 'en' ? 'Contacts inbox' : 'Kontakti',
            'url' => url('data'),
            'description' => $language === 'en' ? 'Review leads, contacts and follow-up.' : 'Pregled leadova, kontakata i follow-upa.',
        ],
        'account_plan' => [
            'title' => $language === 'en' ? 'Account plan' : 'Plan paketa',
            'url' => url('account-plan'),
            'description' => $language === 'en' ? 'Compare Beginner and PRO, including VIP Coach.' : 'Usporedi Beginner i PRO, uključujući VIP Coach.',
        ],
        'featured_apps' => [
            'title' => $language === 'en' ? 'Featured Apps' : 'Istaknute aplikacije',
            'url' => url('featured-apps'),
            'description' => $language === 'en' ? 'See the 15+ / 30d Featured Apps list as the first public proof layer and the path toward 50+ / 30d sponsor visibility.' : 'Pogledaj 15+ / 30d popis Istaknutih aplikacija kao prvi javni sloj dokaza i put prema 50+ / 30d sponsor vidljivosti.',
        ],
        'recommended_sponsors' => [
            'title' => $language === 'en' ? 'Recommended sponsors' : 'Preporučeni sponzori',
            'url' => url('recommended-sponsors'),
            'description' => $language === 'en' ? 'See the 50+ / 30d homepage sponsor layer, public sponsor profiles, and the stronger FCC signal for Google/AI understanding of your brand.' : 'Pogledaj 50+ / 30d sloj sponsora za naslovnicu, javne sponsor profile i jači FCC signal za Google/AI razumijevanje tvog branda.',
        ],
        'education' => [
            'title' => $language === 'en' ? 'FCC education' : 'FCC edukacija',
            'url' => url('fcc-education'),
            'description' => $language === 'en' ? 'Open FCC guides and learning materials.' : 'Otvori FCC vodiče i edukacije.',
        ],
        'sales_link_setup' => [
            'title' => match(trim((string) ($sales_link_summary['status_key'] ?? 'missing'))) {
                'disabled' => $language === 'en' ? 'Reactivate Forever Web Shop block' : 'Ponovno ukljuci Forever Web trgovina blok',
                'invalid' => $language === 'en' ? 'Fix Forever Web Shop block' : 'Popravi Forever Web trgovina blok',
                default => $language === 'en' ? 'Add Forever Web Shop block' : 'Dodaj Forever Web trgovina blok',
            },
            'url' => (string) ($sales_link_summary['editor_url'] ?? url('links')),
            'description' => $language === 'en'
                ? 'Open Blocks, add or fix the Forever Web Shop block, then paste your own Link Builder URL.'
                : 'Otvori Blokove, dodaj ili popravi Forever Web trgovina blok i zatim zalijepi svoj Link Builder URL.',
        ],
        'forever_products_blog' => [
            'title' => $language === 'en' ? 'Forever products blog' : 'Forever proizvodi blog',
            'url' => fc_get_forever_products_blog_category_url($language),
            'description' => $language === 'en'
                ? 'Open the product blog and use the logged-in share helper with your recommendation.'
                : 'Otvori blog proizvoda i koristi prijavljeni share helper sa svojom preporukom.',
        ],
        'ai_settings' => [
            'title' => $language === 'en' ? 'AI settings' : 'AI postavke',
            'url' => url('fcc-ai'),
            'description' => $language === 'en' ? 'Tune models, tone and assistant behavior.' : 'Podesite modele, ton i ponašanje asistenata.',
        ],
    ];

    if(!empty($active_campaign['id']) && !empty($active_campaign['primary_url'])) {
        $pages['active_campaign'] = [
            'title' => (string) ($active_campaign['title'] ?? ($language === 'en' ? 'Current promotion' : 'Aktualna akcija')),
            'url' => (string) ($active_campaign['primary_url'] ?? url('links?type=biolink')),
            'description' => (string) ($active_campaign['primary_description'] ?? $active_campaign['summary'] ?? ''),
        ];
    }

    $latest_app_review = $ai_plan_summary['latest_app_review'] ?? [];
    if(!empty($latest_app_review['selected_link_id'])) {
        $pages['reviewed_app'] = [
            'title' => trim((string) ($latest_app_review['selected_app_name'] ?? '')) !== ''
                ? trim((string) $latest_app_review['selected_app_name'])
                : ($language === 'en' ? 'Reviewed app' : 'Pregledana aplikacija'),
            'url' => url('link/' . (int) $latest_app_review['selected_link_id'] . '?tab=blocks'),
            'description' => $language === 'en'
                ? 'Open the app that Coach reviewed most recently.'
                : 'Otvorite aplikaciju koju je Coach zadnju analizirao.',
        ];
    }

    $primary_destination = fcc_ai_get_internal_coach_primary_destination($ai_plan_summary, $language);
    $suggestions = [];
    $used = [];

    $add_page = static function(string $key, int $score = 0) use (&$suggestions, &$used, $pages) {
        if(!isset($pages[$key])) {
            return;
        }

        $page = $pages[$key];

        if(isset($used[$page['url']])) {
            return;
        }

        $suggestions[] = [
            'title' => $page['title'],
            'url' => $page['url'],
            'description' => $page['description'],
            'kind' => 'internal_page',
            'score' => $score,
        ];
        $used[$page['url']] = true;
    };

    if(!empty($primary_destination['url'])) {
        $suggestions[] = [
            'title' => (string) ($primary_destination['title'] ?? ''),
            'url' => (string) ($primary_destination['url'] ?? ''),
            'description' => (string) ($primary_destination['description'] ?? ''),
            'kind' => 'internal_page',
            'score' => 120,
        ];
        $used[(string) ($primary_destination['url'] ?? '')] = true;
    }

    if(fcc_ai_contains_keywords($normalized_message, ['profil', 'goal', 'cilj', 'offer', 'ponud', 'blocker', 'kanal', 'channel'])) {
        $add_page('ai_profile', 100);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['review', 'pregled', 'app', 'aplik', 'biolink', 'link'])) {
        $add_page('ai_app_review', 95);
        $add_page('apps', 90);
        $add_page('reviewed_app', 89);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['previše aplik', 'vise aplik', 'više app', 'ugasi', 'isključi', 'iskljuci', 'arhivir', 'archive', 'cleanup', 'koju aplik', 'koja aplik', 'dodatne aplik', 'poveži aplik', 'povezi aplik', 'spoji aplik', 'portfolio'])) {
        $add_page('apps', 102);
        $add_page('reviewed_app', 84);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['weekly', 'tjed', 'plan', 'fokus', 'power move', 'outcome'])) {
        $add_page('ai_weekly', 92);
        $add_page('ai_plan', 91);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['pro', 'trial', 'paket', 'upgrade', 'vip coach', 'beginner coach', 'inteligenc'])) {
        $add_page('account_plan', 98);
    }

    if(!empty($active_campaign['id']) && ($normalized_message === '' || fcc_ai_contains_keywords($normalized_message, ['akcij', 'promo', 'popust', 'challenge', 'izazov', 'aloe', 'pro-b', '4 pack', 'paket aloe', 'kampanj']))) {
        $add_page('active_campaign', 103);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['prodajni link', 'sales link', 'webshop', 'web shop', 'link builder', 'thealoeveraco', 'popust', 'discount', 'forever web shop', 'forever web trgovina'])) {
        $add_page('sales_link_setup', 101);
        $add_page('education', 87);
        $add_page('apps', 84);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['top', 'featured', 'preporu', 'sponsor', 'sponzor', 'naslovn', 'brand', 'brend', 'google', 'indeks', 'index', 'chatgpt', 'ai search', 'vidljivost'])) {
        $add_page('featured_apps', 89);
        $add_page('recommended_sponsors', 93);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['proizvod', 'product', 'share', 'podijeli', 'kopir', 'copy link', 'referral', 'referr', 'foreverliving', 'forever proizvodi', 'forever products', 'link za preporuku', 'blok proizvoda'])) {
        $add_page('forever_products_blog', 96);
        $add_page('apps', 87);
        $add_page('account_plan', 82);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['blog', 'eduk', 'upute', 'guide', 'vodič'])) {
        $add_page('education', 86);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['kontakt', 'lead', 'data', 'inbox', 'follow-up', 'follow up', 'dm', 'whatsapp'])) {
        $add_page('contacts', 94);
        $add_page('apps', 86);
    }

    if(fcc_ai_contains_keywords($normalized_message, ['model', 'assistant', 'chat', 'coach', 'jezik', 'language', 'tone', 'ton'])) {
        $add_page('ai_settings', 88);
    }

    if($page_route === 'dashboard') {
        $add_page('apps', 84);
        $add_page('contacts', 82);

        if(!empty($active_campaign['id'])) {
            $add_page('active_campaign', 81);
        }
    }

    if($page_route === 'links' || $page_route === 'link') {
        $add_page('sales_link_setup', 92);
        $add_page('ai_app_review', 87);
        $add_page('contacts', 83);
    }

    if($page_route === 'data') {
        $add_page('ai_plan', 85);
        $add_page('apps', 81);
    }

    if($page_route === 'account-plan') {
        $add_page('dashboard', 84);
        $add_page('ai_profile', 82);
    }

    if($page_route === 'blog') {
        $add_page('forever_products_blog', 88);
        $add_page('apps', 82);
        $add_page('account_plan', 80);
    }

    if($page_route === 'ai-plan') {
        if($page_section === 'profile') {
            $add_page('ai_app_review', 86);
            $add_page('ai_weekly', 82);
        } elseif($page_section === 'app_review') {
            $add_page('reviewed_app', 91);
            $add_page('apps', 88);
            $add_page('ai_weekly', 80);
        } elseif($page_section === 'weekly') {
            $add_page('ai_plan', 90);
            $add_page('contacts', 80);
        } elseif($page_section === 'plan') {
            $add_page('contacts', 84);
            $add_page('apps', 83);
        }
    }

    $add_page('dashboard', 60);
    $add_page('apps', 59);
    $add_page('contacts', 58);
    $add_page('ai_settings', 57);
    $add_page('account_plan', 56);

    usort($suggestions, static function(array $a, array $b) {
        return (int) ($b['score'] ?? 0) <=> (int) ($a['score'] ?? 0);
    });

    return array_slice($suggestions, 0, max(1, min(5, $limit)));
}

function fcc_ai_extract_first_name(string $name = ''): string {
    $name = trim($name);

    if($name === '') {
        return '';
    }

    $parts = preg_split('/\s+/u', $name);

    if(!is_array($parts) || empty($parts[0])) {
        return $name;
    }

    return trim((string) $parts[0]);
}

function fcc_ai_hr_inflect_person_token_instrumental(string $token): string {
    $token = trim($token);

    if($token === '') {
        return '';
    }

    $lower = mb_strtolower($token);

    if(preg_match('/a$/u', $lower)) {
        return mb_substr($token, 0, -1) . 'om';
    }

    if(preg_match('/i$/u', $lower)) {
        return $token . 'jem';
    }

    if(preg_match('/je$/u', $lower)) {
        return mb_substr($token, 0, -1) . 'em';
    }

    if(preg_match('/[eou]$/u', $lower)) {
        return mb_substr($token, 0, -1) . 'om';
    }

    if(preg_match('/(lj|nj|dž|j|č|ć|đ|š|ž|c)$/u', $lower)) {
        return $token . 'em';
    }

    return $token . 'om';
}

function fcc_ai_hr_inflect_person_name_instrumental(string $name): string {
    $name = trim(preg_replace('/\s+/u', ' ', $name));

    if($name === '') {
        return '';
    }

    $parts = preg_split('/\s+/u', $name) ?: [];
    $parts = array_values(array_filter($parts, static function($part) {
        return trim((string) $part) !== '';
    }));

    if(empty($parts)) {
        return $name;
    }

    $inflected = array_map(static function($part) {
        return fcc_ai_hr_inflect_person_token_instrumental((string) $part);
    }, $parts);

    return trim(implode(' ', $inflected));
}

function fcc_ai_hr_join_with_person_name(string $name): string {
    $instrumental_name = fcc_ai_hr_inflect_person_name_instrumental($name);

    if($instrumental_name === '') {
        return '';
    }

    $first_token = fcc_ai_extract_first_name($instrumental_name);
    $first_lower = mb_strtolower($first_token);
    $preposition = preg_match('/^(s|š|z|ž|st|sp|sk|sm|sn|sv|sl|št|šk|zd|zb|zg|zm|zn|zv|zl)/u', $first_lower) ? 'sa' : 's';

    return trim($preposition . ' ' . $instrumental_name);
}

function fcc_ai_get_owner_name_reference(string $owner_name = '', string $language = 'hr', string $mode = 'plain'): string {
    $owner_name = trim($owner_name);
    $language = fcc_ai_resolve_public_reply_language($language);

    if($owner_name === '') {
        return '';
    }

    if($language !== 'hr') {
        return $owner_name;
    }

    if($mode === 'instrumental') {
        return fcc_ai_hr_inflect_person_name_instrumental($owner_name);
    }

    if($mode === 'with') {
        return fcc_ai_hr_join_with_person_name($owner_name);
    }

    return $owner_name;
}

function fcc_ai_extract_public_contact_candidate(string $message): array {
    $raw = trim((string) $message);

    if($raw === '') {
        return [
            'has_contact' => false,
            'name' => '',
            'email' => '',
            'phone' => '',
            'preferred_contact_channel' => 'whatsapp',
            'is_contact_only' => false,
        ];
    }

    $email = '';
    if(preg_match('/([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})/iu', $raw, $email_match)) {
        $email = trim((string) ($email_match[1] ?? ''));
    }

    $phone = '';
    if(preg_match_all('/(?:\+?\d[\d\s().\/-]{5,}\d)/u', $raw, $phone_matches)) {
        $best_candidate = '';
        $best_digits = 0;

        foreach((array) ($phone_matches[0] ?? []) as $candidate) {
            $candidate = trim((string) $candidate);
            $digits = preg_replace('/\D+/', '', $candidate);
            $digit_length = mb_strlen((string) $digits);

            if($digit_length >= 7 && $digit_length > $best_digits) {
                $best_candidate = $candidate;
                $best_digits = $digit_length;
            }
        }

        $phone = $best_candidate;
    }

    $stripped = $raw;

    if($email !== '') {
        $stripped = str_ireplace($email, ' ', $stripped);
    }

    if($phone !== '') {
        $stripped = str_replace($phone, ' ', $stripped);
    }

    $stripped = preg_replace('/\b(whatsapp|wa|viber|telefon|tel|phone|broj|kontakt|contact|ime|name|mail|email)\b/iu', ' ', $stripped);
    $stripped = preg_replace('/[,:;|\/]+/u', ' ', $stripped);
    $stripped = trim(preg_replace('/\s+/u', ' ', (string) $stripped));

    $name = '';
    if($stripped !== '') {
        $tokens = preg_split('/\s+/u', $stripped) ?: [];
        $tokens = array_values(array_filter(array_map(static function($token) {
            $token = trim((string) $token);

            if($token === '') {
                return '';
            }

            return preg_match('/^[\p{L}][\p{L}\-\'’\.]{0,30}$/u', $token) ? $token : '';
        }, $tokens)));

        if(!empty($tokens) && count($tokens) <= 4) {
            $name = trim(implode(' ', $tokens));
        }
    }

    $has_contact = $email !== '' || $phone !== '';
    $residual_length = mb_strlen(trim((string) $stripped));
    $is_contact_only = $has_contact && ($residual_length === 0 || ($residual_length <= 48 && count(preg_split('/\s+/u', trim((string) $stripped)) ?: []) <= 4));

    return [
        'has_contact' => $has_contact,
        'name' => $name,
        'email' => $email,
        'phone' => $phone,
        'preferred_contact_channel' => $phone !== '' ? 'whatsapp' : 'email',
        'is_contact_only' => $is_contact_only,
    ];
}

function fcc_ai_public_content_mentions_patterns(string $content, array $patterns): bool {
    $haystack = mb_strtolower(trim((string) $content));

    if($haystack === '') {
        return false;
    }

    foreach($patterns as $pattern) {
        $pattern = mb_strtolower(trim((string) $pattern));

        if($pattern !== '' && mb_stripos($haystack, $pattern) !== false) {
            return true;
        }
    }

    return false;
}

function fcc_ai_public_has_conversion_cta(string $content, string $language = 'hr'): bool {
    $patterns = $language === 'en'
        ? [
            'open the fcc article',
            'fastest next step',
            'next step is to open',
            'continue from that exact direction',
            'leave your contact',
            'contact request',
        ]
        : ($language === 'sl'
            ? [
                'odpreti fcc članek',
                'najhitrejši naslednji korak',
                'naslednji korak je odpreti',
                'pustite kontakt',
                'kontaktni zahtevek',
            ]
            : [
                'otvoriti fcc članak',
                'najbrži sljedeći korak',
                'sljedeći korak je otvoriti',
                'ostavite kontakt',
                'kontakt zahtjev',
                'nastaviti baš iz tog smjera',
            ]);

    return fcc_ai_public_content_mentions_patterns($content, $patterns);
}

function fcc_ai_get_internal_coach_welcome_message(string $language = 'hr', string $user_name = '', array $context = []): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $first_name = fcc_ai_extract_first_name($user_name);
    $name_prefix = $first_name !== '' ? $first_name . ', ' : '';
    $coach_summary = is_array($context['coach_summary'] ?? null) ? $context['coach_summary'] : [];
    $starter_summary = is_array($context['starter_summary'] ?? null) ? $context['starter_summary'] : [];
    $sales_link_summary = is_array($context['sales_link_summary'] ?? null) ? $context['sales_link_summary'] : [];
    $active_campaign = is_array($context['active_campaign'] ?? null) ? $context['active_campaign'] : [];
    $is_vip = !empty($coach_summary['is_vip']);
    $starter_app_review_available = !empty($starter_summary['app_review_available']);
    $starter_weekly_plan_available = !empty($starter_summary['weekly_plan_available']);
    $sales_link_missing = !empty($sales_link_summary['is_priority_missing']);
    $campaign_line = '';

    if(!empty($active_campaign['id'])) {
        $campaign_welcome = trim((string) ($active_campaign['welcome_line'] ?? ''));
        $campaign_title = trim((string) ($active_campaign['title'] ?? ''));

        if($campaign_welcome !== '') {
            $campaign_line = $sales_link_missing
                ? ($language === 'en'
                    ? ' First fix the Forever sales link, and right after that I can help you turn the current promotion into a dedicated app button, story and DM follow-up.'
                    : ' Prvo sredi Forever prodajni link, a odmah nakon toga mogu ti pomoći da aktualnu akciju pretvoriš u poseban gumb na aplikaciji, story i DM follow-up.')
                : ' ' . $campaign_welcome;
        } elseif($campaign_title !== '') {
            $campaign_line = $language === 'en'
                ? ' The active promotion right now is ' . $campaign_title . '.'
                : ' Trenutačno je aktivna akcija ' . $campaign_title . '.';
        }
    }

    if($language === 'en') {
        if($sales_link_missing) {
            return 'Hi ' . $name_prefix . 'I am your ' . ($is_vip ? 'VIP Coach' : 'Beginner Coach') . '. Before anything else, we need to activate your Forever sales link, because without that block FCC cannot drive real webshop clicks and product recommendation results. I will guide you through it step by step.' . $campaign_line;
        }

        if($is_vip && $starter_app_review_available && $starter_weekly_plan_available) {
            return 'Hi ' . $name_prefix . 'I am your VIP Coach. PRO is active, so I am using the strongest intelligence package. Right now you can immediately run one initial app review and one first weekly plan, and I will use that to guide you first toward 15+ / 30d and then toward the main public goal of 50+ / 30d sponsor visibility.' . $campaign_line;
        }

        if($is_vip && $starter_weekly_plan_available) {
            return 'Hi ' . $name_prefix . 'I am your VIP Coach. PRO is active, so I am using the strongest intelligence package. Your initial app review is already in place, and your first weekly plan is available now so we can turn it into a focused next 7 days.' . $campaign_line;
        }

        return $is_vip
            ? 'Hi ' . $name_prefix . 'I am your VIP Coach. PRO is active, so I am using the strongest intelligence package. I help you turn your plan, app, contacts and content into the clearest next move inside FCC, and I can also guide you toward 15+ / 30d for Featured Apps, 50+ / 30d as the main public sponsor goal, stronger homepage visibility, and a healthy 7-day rhythm.' . $campaign_line
            : 'Hi ' . $name_prefix . 'I am your Beginner Coach. Right now you are on the basic intelligence package, but I can already help you with the next move inside FCC, social content, follow-up, and app direction. When you activate PRO or trial, I switch into VIP Coach with the strongest intelligence package.' . $campaign_line;
    }

    if($sales_link_missing) {
        return 'Bok ' . $name_prefix . 'ja sam tvoj ' . ($is_vip ? 'VIP Coach' : 'Beginner Coach') . '. Prije svega trebamo aktivirati tvoj Forever prodajni link, jer bez tog bloka FCC ne može graditi stvarne webshop klikove i rezultate preporuke proizvoda. Vodit ću te kroz to korak po korak.' . $campaign_line;
    }

    if($is_vip && $starter_app_review_available && $starter_weekly_plan_available) {
        return 'Bok ' . $name_prefix . 'ja sam tvoj VIP Coach. PRO je aktivan pa sada koristim najjači paket inteligencije. Upravo sada možeš odmah napraviti jednu početnu analizu aplikacije i jedan prvi tjedni plan, a ja ću to iskoristiti da te vodim prvo prema 15+ / 30d, a zatim i prema glavnom javnom cilju 50+ / 30d.' . $campaign_line;
    }

    if($is_vip && $starter_weekly_plan_available) {
        return 'Bok ' . $name_prefix . 'ja sam tvoj VIP Coach. PRO je aktivan pa sada koristim najjači paket inteligencije. Početna analiza aplikacije je već spremna, a prvi tjedni plan možeš otvoriti odmah kako bismo složili fokusiranih sljedećih 7 dana.' . $campaign_line;
    }

    return $is_vip
        ? 'Bok ' . $name_prefix . 'ja sam tvoj VIP Coach. PRO je aktivan pa sada koristim najjači paket inteligencije. Pomažem ti pretvoriti plan, aplikaciju, kontakte i sadržaj u najjasniji sljedeći potez unutar FCC-a, a mogu te i voditi prema 15+ / 30d za Istaknute aplikacije, 50+ / 30d kao glavnom javnom sponsor cilju, jačoj vidljivosti na naslovnici i zdravom 7-dnevnom ritmu.' . $campaign_line
        : 'Bok ' . $name_prefix . 'ja sam tvoj Beginner Coach. Trenutno si na osnovnom paketu inteligencije, ali ti i dalje mogu pomoći oko sljedećeg poteza u FCC-u, sadržaja za društvene mreže, follow-upa i smjera za aplikaciju. Kad aktiviraš PRO ili trial, prebacujem se u VIP Coach s najjačim paketom inteligencije.' . $campaign_line;
}

