function fcc_ai_get_internal_coach_quick_followup_asset(array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $offer = trim((string) ($ai_plan['profile']['priority_offer_label'] ?? ''));

    if($language === 'en') {
        $focus = $offer !== '' ? ' around ' . $offer : '';

        return implode("\n", [
            'Quick follow-up message:',
            '"Hi! Thank you for checking my FCC app.',
            'If you want, I can guide you very simply' . $focus . ' and help you choose the best next step for you.',
            'Would you rather start with product recommendation or business collaboration?"',
        ]);
    }

    $focus = $offer !== '' ? ' oko teme ' . $offer : '';

    return implode("\n", [
        'Brza follow-up poruka:',
        '"Bok! Hvala ti što si pogledao/la moju FCC aplikaciju.',
        'Ako želiš, mogu te vrlo jednostavno usmjeriti' . $focus . ' i pomoći ti odabrati najbolji sljedeći korak za tebe.',
        'Je li ti trenutno zanimljivija preporuka proizvoda ili poslovna suradnja?"',
    ]);
}

function fcc_ai_get_internal_coach_quick_caption_asset(array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $goal = trim((string) ($ai_plan['profile']['primary_goal_label'] ?? ''));
    $offer = trim((string) ($ai_plan['profile']['priority_offer_label'] ?? ''));

    if($language === 'en') {
        $goal_line = $goal !== '' ? ' Right now my focus is ' . $goal . '.' : '';
        $offer_line = $offer !== '' ? ' That is exactly why I use ' . $offer . ' as my simple next-step system.' : '';

        return implode("\n", [
            'Quick caption:',
            '\"You do not need a complicated system to start stronger.' . $goal_line . $offer_line,
            'The key is to make the next conversation easier and clearer.',
            'If you want to see how I use it in practice, send me a message.\"',
        ]);
    }

    $goal_line = $goal !== '' ? ' Trenutno mi je fokus ' . $goal . '.' : '';
    $offer_line = $offer !== '' ? ' Upravo zato koristim ' . $offer . ' kao jednostavan sustav za sljedeći korak.' : '';

    return implode("\n", [
        'Kratki caption:',
        '"Ne treba ti kompliciran sustav da kreneš jače.' . $goal_line . $offer_line,
        'Najvažnije je da sljedeći razgovor bude lakši i jasniji.',
        'Ako želiš vidjeti kako to koristim u praksi, javi mi se porukom."',
    ]);
}

function fcc_ai_get_internal_coach_story_asset(array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $offer = trim((string) ($ai_plan['profile']['priority_offer_label'] ?? ''));

    if($language === 'en') {
        $middle = $offer !== '' ? 'That is why I use ' . $offer . ' to keep the next step simple.' : 'That is why I use a simple FCC flow to keep the next step clear.';

        return implode("\n", [
            'Simple story sequence:',
            '1. \"A lot of people want better results, but they do not know what to send first.\"',
            '2. \"' . $middle . '\"',
            '3. \"If you want, I can show you how it works for products or business collaboration. Message me.\"',
        ]);
    }

    $middle = $offer !== '' ? 'Zato koristim ' . $offer . ' da sljedeći korak ostane jednostavan.' : 'Zato koristim jednostavan FCC sustav da sljedeći korak bude jasan.';

    return implode("\n", [
        'Jednostavan story niz:',
        '1. "Puno ljudi želi bolje rezultate, ali ne zna što prvo poslati."',
        '2. "' . $middle . '"',
        '3. "Ako želiš, mogu ti pokazati kako to radi za proizvode ili poslovnu suradnju. Javi mi se."',
    ]);
}

function fcc_ai_get_internal_coach_product_referral_explainer(bool $is_pro, string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $products_blog_url = fc_get_forever_products_blog_category_url($language);

    if($language === 'en') {
        $lines = [
            'This option exists for both Beginner and PRO.',
            'On logged-in product articles inside the Forever products blog, there is a share/copy area at the top of the page. When you use that area, your recommendation is embedded automatically and the buyer is redirected to ForeverLiving in their country with your recommendation attached.',
            'Important: do not copy only the raw browser URL, because then your recommendation is not attached and the system cannot recognize it as your recommendation.',
        ];

        if($is_pro) {
            $lines[] = 'On PRO, you can also place the product recommendation block inside your FCC app. Those outbound Forever product clicks are one of the practical ways to build your 15+ signal.';
        } else {
            $lines[] = 'On Beginner, this is a strong move for a story, a DM, or a direct recommendation when you want to send one product or one product group quickly. On PRO, you additionally unlock the product recommendation block inside your FCC app.';
        }

        $lines[] = 'Best place to start: ' . $products_blog_url;

        return implode("\n", $lines);
    }

    $lines = [
        'Ova opcija postoji i za Beginner i za PRO korisnike.',
        'Na prijavljenim člancima u blog kategoriji Forever proizvodi gore se pojavljuje share/copy dio. Kada link kopiraš ili podijeliš baš preko tog dijela, tvoja preporuka se automatski ugradi i kupac se dalje preusmjerava na ForeverLiving stranicu svoje zemlje s tvojom preporukom.',
        'Važno: nemoj kopirati samo običan URL iz browsera, jer tada tvoja preporuka nije ugrađena i sustav ne zna da je to tvoja preporuka.',
    ];

    if($is_pro) {
        $lines[] = 'Ako si na PRO, isti princip možeš koristiti i kroz blok za preporuku proizvoda unutar FCC aplikacije. Ti odlazni klikovi prema Foreveru su jedan od praktičnih načina da gradiš svoj 15+ signal.';
    } else {
        $lines[] = 'Ako si na Beginneru, ovo je super varijanta za story, DM ili direktnu preporuku kad želiš nekome brzo poslati jedan proizvod ili jednu grupu proizvoda. Na PRO paketu dodatno otključavaš i blok za preporuku proizvoda unutar FCC aplikacije.';
    }

    $lines[] = 'Najbolje mjesto za početak: ' . $products_blog_url;

    return implode("\n", $lines);
}

function fcc_ai_get_internal_coach_sales_link_explainer(array $sales_link_summary = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $status_key = trim((string) ($sales_link_summary['status_key'] ?? 'missing'));
    $editor_url = trim((string) ($sales_link_summary['editor_url'] ?? url('links')));
    $education_url = trim((string) ($sales_link_summary['education_url'] ?? url('fcc-education')));
    $video_tutorial_url = trim((string) ($sales_link_summary['video_tutorial_url'] ?? 'https://www.youtube.com/watch?v=8tBJiDu1EWc'));
    $product_referral_ready = !empty($sales_link_summary['product_referral_ready']);

    if($language === 'en') {
        $lines = match($status_key) {
            'disabled' => [
                'First reopen your Forever Web Shop block. I can see the block already existed before, but it is currently turned off, and FCC cannot drive webshop results without an active block.',
            ],
            'invalid' => [
                'First fix your Forever Web Shop block. The block already exists, but the URL inside it is not a valid Forever Link Builder link.',
            ],
            default => [
                'First add the Forever Web Shop block. Without that block, FCC cannot turn interest into real webshop clicks and recommendation results.',
                'This is available on both Beginner and PRO.',
            ],
        };

        $lines[] = 'Use this exact order:';
        $lines[] = '- open your app Blocks screen: ' . $editor_url;
        $lines[] = '- click Add block';
        $lines[] = '- inside the Forever Card Club section choose the block: Forever Web Shop';
        $lines[] = '- watch the video guide first: ' . $video_tutorial_url;
        $lines[] = '- on Foreverliving.com open Link Builder and create your own webshop recommendation link';
        $lines[] = '- the link you paste into the block must start with: https://thealoeveraco.shop/';
        $lines[] = '- paste that full link into the Forever Web Shop block and save it';

        if($status_key === 'disabled') {
            $lines[] = '- because your block already exists, after pasting/checking the link just turn the block back on and save';
        } elseif($status_key === 'invalid') {
            $lines[] = '- replace the current URL inside the block with your own newly created Link Builder link and save';
        }

        if(!$product_referral_ready) {
            $lines[] = '- if you want product articles and product buttons to reuse the same recommendation flow, choose yes for applying the discount to all products';
        }

        $lines[] = 'Important: nobody can create that Link Builder link for you except you, because it must be created inside your own Foreverliving account.';
        $lines[] = 'If you get stuck, ask your sponsor or the team WhatsApp group for help, but they should guide you, not create the link for you.';
        $lines[] = 'After that, the block becomes active and starts working properly.';
        $lines[] = 'Blocks: ' . $editor_url;
        $lines[] = 'Education: ' . $education_url;
        $lines[] = 'Video: ' . $video_tutorial_url;

        return implode("\n", $lines);
    }

    $lines = match($status_key) {
        'disabled' => [
            'Prvo ponovno ukljuci svoj Forever Web trgovina blok. Vidim da je blok vec postojao, ali je sada ugasen, a bez aktivnog bloka FCC ne moze graditi webshop rezultate.',
        ],
        'invalid' => [
            'Prvo popravi svoj Forever Web trgovina blok. Blok vec postoji, ali URL u njemu nije valjan Forever Link Builder link.',
        ],
        default => [
            'Prvo dodaj Forever Web trgovina blok. Bez tog bloka FCC ne moze pretvoriti interes u stvarne webshop klikove i rezultate preporuke.',
            'To imaju i Beginner i PRO korisnici.',
        ],
    };

    $lines[] = 'Radi ovim tocnim redom:';
    $lines[] = '- otvori blokove svoje aplikacije: ' . $editor_url;
    $lines[] = '- klikni Dodaj blok';
    $lines[] = '- u rubrici Forever Card Club odaberi blok: Forever Web trgovina';
    $lines[] = '- prvo pogledaj video uputu: ' . $video_tutorial_url;
    $lines[] = '- zatim na Foreverliving.com stranici otvori Link Builder i sam izradi svoj webshop preporucni link';
    $lines[] = '- link koji lijepis u blok mora pocinjati s: https://thealoeveraco.shop/';
    $lines[] = '- taj puni link zalijepi u blok i spremi';

    if($status_key === 'disabled') {
        $lines[] = '- posto blok vec postoji, nakon provjere linka ga samo ponovno ukljuci i spremi';
    } elseif($status_key === 'invalid') {
        $lines[] = '- zamijeni postojeci URL svojim novim Link Builder linkom i spremi blok';
    }

    if(!$product_referral_ready) {
        $lines[] = '- ako zelis da clanci o proizvodima i produkt gumbi koriste isti preporucni tok, ukljuci primjenu popusta na sve proizvode';
    }

    $lines[] = 'Vazno: taj Link Builder link ne moze nitko kreirati umjesto tebe, nego samo ti u svom Foreverliving racunu.';
    $lines[] = 'Ako zapnes, trazi pomoc sponzora ili u timskoj WhatsApp grupi, ali oni ti mogu pomoci oko koraka, ne mogu umjesto tebe napraviti tvoj link.';
    $lines[] = 'Tek nakon toga blok postaje aktivan i radi ispravno.';
    $lines[] = 'Blokovi: ' . $editor_url;
    $lines[] = 'Edukacija: ' . $education_url;
    $lines[] = 'Video uputa: ' . $video_tutorial_url;

    return implode("\n", $lines);
}

function fcc_ai_get_internal_coach_portfolio_explainer(array $portfolio_summary = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $total_apps = max(0, (int) ($portfolio_summary['total_apps'] ?? 0));
    $enabled_apps = max(0, (int) ($portfolio_summary['enabled_apps'] ?? 0));
    $apps_with_recent_traffic = max(0, (int) ($portfolio_summary['apps_with_recent_traffic'] ?? 0));
    $apps_with_results = max(0, (int) ($portfolio_summary['apps_with_results'] ?? 0));
    $archive_candidate_count = max(0, (int) ($portfolio_summary['archive_candidate_count'] ?? 0));
    $recommended_focus_limit = max(1, (int) ($portfolio_summary['recommended_focus_limit'] ?? 3));
    $cleanup_needed = !empty($portfolio_summary['cleanup_needed']);
    $health_label = trim((string) ($portfolio_summary['health_label'] ?? ''));
    $focus_apps = array_values(array_filter((array) ($portfolio_summary['focus_apps'] ?? []), 'is_array'));
    $archive_candidates = array_values(array_filter((array) ($portfolio_summary['archive_candidates'] ?? []), 'is_array'));

    if($language === 'en') {
        $lines = [
            'I can see your FCC app portfolio, not just the main app.',
            'Right now you have ' . $total_apps . ' apps in total, ' . $enabled_apps . ' enabled, ' . $apps_with_recent_traffic . ' with recent traffic, and ' . $apps_with_results . ' that still carry some real signal or result.',
        ];

        if($health_label !== '') {
            $lines[] = 'Portfolio health: ' . $health_label . '.';
        }

        if($cleanup_needed) {
            $lines[] = 'To keep stronger focus, I would normally keep around ' . $recommended_focus_limit . ' apps in active focus and seriously review the extra ones.';
        }

        if(!empty($focus_apps)) {
            $lines[] = 'Apps with the most sense to keep in focus:';
            foreach(array_slice($focus_apps, 0, 3) as $app) {
                $lines[] = '- ' . trim((string) ($app['name'] ?? 'App')) . ' · ' . trim((string) ($app['status_label'] ?? '')) . ' · ' . trim((string) ($app['short_metrics_label'] ?? ''));
            }
        }

        if(!empty($archive_candidates)) {
            $lines[] = 'Weakest candidates to disable or archive:';
            foreach(array_slice($archive_candidates, 0, 3) as $app) {
                $lines[] = '- ' . trim((string) ($app['name'] ?? 'App')) . ' · ' . trim((string) ($app['short_metrics_label'] ?? ''));
            }
        } elseif($archive_candidate_count > 0) {
            $lines[] = 'There are ' . $archive_candidate_count . ' archive candidates in total, even if I am showing only the top priorities.';
        }

        $lines[] = $cleanup_needed
            ? 'Best next move: decide which apps stay in focus, which ones connect back to the main app, and which dead-end apps should be turned off.'
            : 'Best next move: keep the strong apps connected to the main app and avoid spreading focus over pages with no clear business role.';

        return implode("\n", $lines);
    }

    $lines = [
        'Vidim tvoj FCC portfelj aplikacija, ne samo glavnu aplikaciju.',
        'Trenutno imas ukupno ' . $total_apps . ' aplikacija, aktivno ih je ' . $enabled_apps . ', promet u zadnjih 90 dana ima ih ' . $apps_with_recent_traffic . ', a stvarni signal ili rezultat jos nosi njih ' . $apps_with_results . '.',
    ];

    if($health_label !== '') {
        $lines[] = 'Stanje portfelja: ' . $health_label . '.';
    }

    if($cleanup_needed) {
        $lines[] = 'Za jaci fokus obicno bih drzao oko ' . $recommended_focus_limit . ' aplikacije u aktivnom fokusu, a visak ozbiljno pregledao za gasenje ili arhivu.';
    }

    if(!empty($focus_apps)) {
        $lines[] = 'Aplikacije koje sada imaju najvise smisla drzati u fokusu:';
        foreach(array_slice($focus_apps, 0, 3) as $app) {
            $lines[] = '- ' . trim((string) ($app['name'] ?? 'Aplikacija')) . ' · ' . trim((string) ($app['status_label'] ?? '')) . ' · ' . trim((string) ($app['short_metrics_label'] ?? ''));
        }
    }

    if(!empty($archive_candidates)) {
        $lines[] = 'Najslabiji kandidati za gasenje ili arhivu:';
        foreach(array_slice($archive_candidates, 0, 3) as $app) {
            $lines[] = '- ' . trim((string) ($app['name'] ?? 'Aplikacija')) . ' · ' . trim((string) ($app['short_metrics_label'] ?? ''));
        }
    } elseif($archive_candidate_count > 0) {
        $lines[] = 'Ukupno imas ' . $archive_candidate_count . ' kandidata za arhivu, iako ti ovdje pokazujem samo glavne prioritete.';
    }

    $lines[] = $cleanup_needed
        ? 'Najbolji sljedeci potez je odluciti koje aplikacije ostaju u fokusu, koje samo povezujemo s glavnom aplikacijom, a koja slijepa crijeva gasimo.'
        : 'Najbolji sljedeci potez je drzati jake aplikacije povezane s glavnom i ne rasipati fokus na stranice bez jasne poslovne uloge.';

    return implode("\n", $lines);
}

function fcc_ai_get_internal_coach_sponsor_visibility_explainer(array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $access_summary = is_array($ai_plan['access_summary'] ?? null) ? $ai_plan['access_summary'] : [];
    $public_signal_summary = is_array($ai_plan['public_signal_summary'] ?? null) ? $ai_plan['public_signal_summary'] : [];
    $signal_summary = !empty($public_signal_summary) ? $public_signal_summary : (is_array($ai_plan['signal_summary'] ?? null) ? $ai_plan['signal_summary'] : []);
    $growth_signal_30d = max(0, (int) ($signal_summary['growth_signal_30d'] ?? 0));
    $growth_signal_7d = max(0, (int) ($signal_summary['growth_signal_7d'] ?? 0));
    $qualified_target = max(1, (int) ($signal_summary['qualified_target'] ?? 15));
    $top_target = max($qualified_target, (int) ($signal_summary['top_target'] ?? 50));
    $weekly_check_target = max(1, (int) ($signal_summary['weekly_check_target'] ?? 15));
    $missing_to_qualified = max(0, (int) ($signal_summary['missing_to_qualified'] ?? max(0, $qualified_target - $growth_signal_30d)));
    $missing_to_top = max(0, (int) ($signal_summary['missing_to_top'] ?? max(0, $top_target - $growth_signal_30d)));
    $analysis_unlocked = !empty($access_summary['analysis_unlocked']);
    $top_performer = !empty($access_summary['top_performer']) || $growth_signal_30d >= $top_target;

    if($language === 'en') {
        if($top_performer) {
            return implode("\n", [
                $top_target . '+ / 30d is your main public FCC goal and you already hold it.',
                'That is the simplest way for FCC to promote you as an active recommended sponsor on the homepage and through the public sponsor profile layer.',
                'It also gives Google and AI systems a cleaner signal about who you are, how you work inside FCC, and why you are relevant as an active sponsor with real results.',
                'The 15+ / 7d check stays only as a weekly rhythm confirmation: right now you are on ' . $growth_signal_7d . ' / ' . $weekly_check_target . '.',
            ]);
        }

        if($analysis_unlocked) {
            return implode("\n", [
                $qualified_target . '+ / 30d is your first public proof layer because it keeps you on Featured Apps.',
                'But the main public goal is ' . $top_target . '+ / 30d, because that is the simplest path for FCC to promote you as an active recommended sponsor on the homepage and through a public sponsor profile.',
                'That helps strengthen your personal brand inside FCC and gives Google and AI chats a stronger signal that you are an active sponsor with real FCC results.',
                'From where you are now, you are missing ' . $missing_to_top . ' to reach that sponsor level.',
            ]);
        }

        return implode("\n", [
            $qualified_target . '+ / 30d is the first public threshold because it places you on Featured Apps.',
            'The main public goal is ' . $top_target . '+ / 30d, because that is the simplest way for FCC to promote you as an active recommended sponsor.',
            'That public layer strengthens your sponsor profile, personal brand, and how Google and AI systems understand you through FCC.',
            'Right now you are missing ' . $missing_to_qualified . ' to reach Featured Apps and ' . $missing_to_top . ' to reach the recommended sponsor layer.',
        ]);
    }

    if($top_performer) {
        return implode("\n", [
            $top_target . '+ / 30d je tvoj glavni javni FCC cilj i ti ga već držiš.',
            'To je najjednostavniji način da te FCC promovira kao aktivnog preporučenog sponzora na naslovnici i kroz javni sponsor profil.',
            'Tako Google i AI sustavi dobivaju jasniji signal tko si, kako radiš unutar FCC-a i zašto si relevantan kao aktivan sponsor sa stvarnim rezultatima.',
            'Prag ' . $qualified_target . '+ / 7d ostaje samo tjedna provjera ritma: trenutno si na ' . $growth_signal_7d . ' / ' . $weekly_check_target . '.',
        ]);
    }

    if($analysis_unlocked) {
        return implode("\n", [
            $qualified_target . '+ / 30d je prvi javni sloj dokaza jer te drži na popisu Istaknutih aplikacija.',
            'Ali glavni javni cilj je ' . $top_target . '+ / 30d, jer je to najjednostavniji put da te FCC promovira kao aktivnog preporučenog sponzora na naslovnici i kroz javni sponsor profil.',
            'To ti diže osobni brand unutar FCC-a i daje Googleu i AI chatovima jači signal da si aktivan sponsor sa stvarnim FCC rezultatima.',
            'Iz ove točke ti do tog sponsor cilja nedostaje još ' . $missing_to_top . '.',
        ]);
    }

    return implode("\n", [
        $qualified_target . '+ / 30d je prvi javni prag jer te on uvodi na Istaknute aplikacije.',
        'Glavni javni cilj je ' . $top_target . '+ / 30d, jer je to najjednostavniji način da te FCC promovira kao aktivnog preporučenog sponzora.',
        'Na taj način jačaš svoj javni profil, osobni brand i mogućnost da te Google i AI sustavi lakše prepoznaju kroz FCC kontekst.',
        'Trenutno ti do ' . $qualified_target . '+ nedostaje još ' . $missing_to_qualified . ', a do ' . $top_target . '+ još ' . $missing_to_top . '.',
    ]);
}

function fcc_ai_get_internal_coach_campaign_explainer(array $campaign = [], array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);

    if(empty($campaign['id'])) {
        return '';
    }

    $sales_link_summary = is_array($ai_plan['sales_link_summary'] ?? null) ? $ai_plan['sales_link_summary'] : [];
    $sales_link_ready = !empty($sales_link_summary['has_valid_enabled_link']);
    $campaign_title = trim((string) ($campaign['title'] ?? ''));
    $campaign_period_label = trim((string) ($campaign['period_label'] ?? ''));
    $campaign_summary = trim((string) ($campaign['summary'] ?? ''));
    $setup_steps = array_values(array_filter((array) ($campaign['setup_steps'] ?? []), static function($step) {
        return is_scalar($step) && trim((string) $step) !== '';
    }));

    if($language === 'en') {
        $lines = [];
        $lines[] = $campaign_title !== ''
            ? $campaign_title . ($campaign_period_label !== '' ? ' is active through ' . $campaign_period_label . '.' : ' is active right now.')
            : 'There is an active Forever promotion right now.';

        if($campaign_summary !== '') {
            $lines[] = $campaign_summary;
        }

        if(!$sales_link_ready) {
            $lines[] = 'First fix your Forever sales link setup, and immediately after that use this promotion through a dedicated app button or link block.';
        } else {
            $lines[] = 'The cleanest move is to place this offer on your main FCC app through a dedicated button or link block and connect it to your own personal Link Builder URL.';
        }

        $lines[] = 'Do not paste the raw Forever product URL into your app, because without your own Link Builder URL the recommendation path and signal are not truly yours.';

        foreach(array_slice($setup_steps, 0, 3) as $step) {
            $lines[] = '- ' . $step;
        }

        $lines[] = 'If you want, I can now turn this promotion into a story angle, a DM follow-up and a simple CTA for your app.';

        return implode("\n", array_filter($lines));
    }

    $lines = [];
    $lines[] = $campaign_title !== ''
        ? $campaign_title . ($campaign_period_label !== '' ? ' traje do ' . $campaign_period_label . '.' : ' je aktivna upravo sada.')
        : 'Trenutačno je aktivna posebna Forever akcija.';

    if($campaign_summary !== '') {
        $lines[] = $campaign_summary;
    }

    if(!$sales_link_ready) {
        $lines[] = 'Prvo sredi osnovni Forever prodajni link, a odmah nakon toga iskoristi ovu akciju kroz poseban gumb ili link blok na aplikaciji.';
    } else {
        $lines[] = 'Najčišći potez sada je da ovu ponudu postaviš na svoju glavnu FCC aplikaciju kroz poseban gumb ili link blok i povežeš je sa svojim osobnim Link Builder URL-om.';
    }

    $lines[] = 'Nemoj lijepiti običan Forever URL u aplikaciju, jer bez tvog osobnog Link Builder URL-a preporučni put i signal nisu stvarno tvoji.';

    foreach(array_slice($setup_steps, 0, 3) as $step) {
        $lines[] = '- ' . $step;
    }

    $lines[] = 'Ako želiš, iz ove akcije ti odmah mogu složiti story smjer, DM follow-up i jednostavan CTA za aplikaciju.';

    return implode("\n", array_filter($lines));
}

function fcc_ai_get_internal_coach_settings_explainer(string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);

    if($language === 'en') {
        return implode("\n", [
            'Here you set up the public AI assistants that appear on your FCC apps.',
            'You can adjust the assistant name, language, communication tone, personality instructions and rules or limits.',
            'Use personality instructions to shape how the assistant sounds. Use rules to define what it should emphasize, avoid or never say.',
            'The fastest approach is: keep the tone simple, define who the assistant helps, and add a few clear guardrails for recommendations and communication.',
        ]);
    }

    return implode("\n", [
        'Ovdje podešavaš javne AI asistente koji se prikazuju na tvojim FCC aplikacijama.',
        'Možeš urediti naziv savjetnika, jezik, ton komunikacije, upute za osobnost te pravila i ograničenja.',
        'Upute za osobnost koriste se da odrediš kako savjetnik zvuči. Pravila služe da definiraš što treba naglašavati, izbjegavati ili nikad ne govoriti.',
        'Najbolji početak je: zadrži jednostavan ton, jasno napiši kome pomaže i dodaj nekoliko jasnih zaštitnih pravila za preporuke i komunikaciju.',
    ]);
}

function fcc_ai_get_internal_coach_blocked_reset(array $ai_plan = [], string $language = 'hr'): string {
    $language = fcc_ai_resolve_public_reply_language($language);
    $focus = trim((string) ($ai_plan['latest_weekly_plan']['focus'] ?? ''));

    if($language === 'en') {
        $focus_line = $focus !== '' ? ' Keep the focus on: ' . $focus . '.' : '';

        return implode("\n", [
            'You are not stuck because you are incapable, you are overloaded. We fix that by shrinking the next move.' . $focus_line,
            'Do only this now:',
            '- open one FCC page that matters most',
            '- send one simple message',
            '- finish with one clear question',
        ]);
    }

    $focus_line = $focus !== '' ? ' Zadrži fokus na ovome: ' . $focus . '.' : '';

    return implode("\n", [
        'Nisi stao zato što ne znaš, nego zato što ti je svega previše. To rješavamo tako da smanjimo sljedeći potez.' . $focus_line,
        'Sada napravi samo ovo:',
        '- otvori jednu FCC stranicu koja ti je trenutno najvažnija',
        '- pošalji jednu jednostavnu poruku',
        '- završi je jednim jasnim pitanjem',
    ]);
}

function fcc_ai_get_conversation_by_public_id(string $public_id): ?object {
    if(trim($public_id) === '') {
        return null;
    }

    fcc_ai_ensure_tables();

    $conversation = db()->where('public_id', trim($public_id))->getOne('fcc_ai_conversations');

    if(!$conversation) {
        return null;
    }

    $conversation->meta = json_decode($conversation->meta ?? '{}');

    return $conversation;
}

function fcc_ai_get_conversation_by_id(int $conversation_id): ?object {
    if($conversation_id <= 0) {
        return null;
    }

    fcc_ai_ensure_tables();

    $conversation = db()->where('fcc_ai_conversation_id', $conversation_id)->getOne('fcc_ai_conversations');

    if(!$conversation) {
        return null;
    }

    $conversation->meta = json_decode($conversation->meta ?? '{}');

    if(is_array($conversation->meta)) {
        $conversation->meta = (object) $conversation->meta;
    }

    if(!is_object($conversation->meta)) {
        $conversation->meta = (object) [];
    }

    return $conversation;
}

function fcc_ai_normalize_feedback_type(string $feedback_type): string {
    $feedback_type = trim(mb_strtolower($feedback_type));

    return in_array($feedback_type, ['up', 'down'], true) ? $feedback_type : '';
}

function fcc_ai_get_feedback_reason_options(string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);

    return [
        'not_helpful' => $language === 'en' ? 'Not helpful' : 'Nije korisno',
        'not_accurate' => $language === 'en' ? 'Not accurate' : 'Nije točno',
        'did_not_understand' => $language === 'en' ? 'Did not understand the question' : 'Nije razumio pitanje',
        'too_generic' => $language === 'en' ? 'Too generic' : 'Preopćenito',
        'tone_issue' => $language === 'en' ? 'Tone was not good' : 'Ton nije dobar',
        'other' => $language === 'en' ? 'Other' : 'Drugo',
    ];
}

function fcc_ai_normalize_feedback_reason(string $reason): string {
    $reason = trim(mb_strtolower($reason));
    $options = fcc_ai_get_feedback_reason_options('hr');

    return array_key_exists($reason, $options) ? $reason : '';
}

function fcc_ai_get_feedback_reason_label(string $reason, string $language = 'hr'): string {
    $reason = fcc_ai_normalize_feedback_reason($reason);
    $options = fcc_ai_get_feedback_reason_options($language);

    return $options[$reason] ?? ($language === 'en' ? 'Feedback' : 'Povratna informacija');
}

function fcc_ai_build_feedback_actor(string $actor_type, string $actor_identifier, ?int $actor_user_id = null): array {
    $actor_type = trim(mb_strtolower($actor_type));

    if(!in_array($actor_type, ['visitor', 'owner', 'admin'], true)) {
        $actor_type = 'visitor';
    }

    return [
        'actor_type' => $actor_type,
        'actor_identifier' => mb_substr(trim($actor_identifier), 0, 128),
        'actor_user_id' => $actor_user_id ? max(0, (int) $actor_user_id) : null,
    ];
}

function fcc_ai_get_message_feedback_map(array $message_ids, array $viewer_actor = []): array {
    $message_ids = array_values(array_unique(array_filter(array_map('intval', $message_ids), static function($message_id) {
        return $message_id > 0;
    })));

    if(empty($message_ids) || !fcc_ai_tables_ready()) {
        return [];
    }

    $message_sql = implode(',', $message_ids);
    $map = [];

    $totals_result = database()->query("SELECT
            `fcc_ai_message_id`,
            SUM(CASE WHEN `feedback_type` = 'up' THEN 1 ELSE 0 END) AS `positive_total`,
            SUM(CASE WHEN `feedback_type` = 'down' AND COALESCE(`status`, 'new') != 'resolved' THEN 1 ELSE 0 END) AS `negative_total`
        FROM `fcc_ai_message_feedback`
        WHERE `fcc_ai_message_id` IN ({$message_sql})
          AND " . fcc_ai_get_feedback_visibility_sql() . "
        GROUP BY `fcc_ai_message_id`");

    while($totals_result && $row = $totals_result->fetch_assoc()) {
        $message_id = (int) ($row['fcc_ai_message_id'] ?? 0);

        if($message_id <= 0) {
            continue;
        }

        $map[$message_id] = [
            'positive_total' => (int) ($row['positive_total'] ?? 0),
            'negative_total' => (int) ($row['negative_total'] ?? 0),
            'viewer_feedback_type' => '',
            'viewer_reason' => '',
            'viewer_note' => '',
            'has_negative_signal' => (int) ($row['negative_total'] ?? 0) > 0,
        ];
    }

    $actor_type = trim((string) ($viewer_actor['actor_type'] ?? ''));
    $actor_identifier = trim((string) ($viewer_actor['actor_identifier'] ?? ''));

    if($actor_type !== '' && $actor_identifier !== '') {
        $actor_type_sql = database()->real_escape_string($actor_type);
        $actor_identifier_sql = database()->real_escape_string($actor_identifier);
        $viewer_result = database()->query("SELECT
                `fcc_ai_message_id`,
                `feedback_type`,
                `reason`,
                `note`
            FROM `fcc_ai_message_feedback`
            WHERE `fcc_ai_message_id` IN ({$message_sql})
              AND " . fcc_ai_get_feedback_visibility_sql() . "
              AND `actor_type` = '{$actor_type_sql}'
              AND `actor_identifier` = '{$actor_identifier_sql}'");

        while($viewer_result && $row = $viewer_result->fetch_assoc()) {
            $message_id = (int) ($row['fcc_ai_message_id'] ?? 0);

            if($message_id <= 0) {
                continue;
            }

            if(!isset($map[$message_id])) {
                $map[$message_id] = [
                    'positive_total' => 0,
                    'negative_total' => 0,
                    'viewer_feedback_type' => '',
                    'viewer_reason' => '',
                    'viewer_note' => '',
                    'has_negative_signal' => false,
                ];
            }

            $map[$message_id]['viewer_feedback_type'] = (string) ($row['feedback_type'] ?? '');
            $map[$message_id]['viewer_reason'] = (string) ($row['reason'] ?? '');
            $map[$message_id]['viewer_note'] = (string) ($row['note'] ?? '');
        }
    }

    foreach($message_ids as $message_id) {
        if(!isset($map[$message_id])) {
            $map[$message_id] = [
                'positive_total' => 0,
                'negative_total' => 0,
                'viewer_feedback_type' => '',
                'viewer_reason' => '',
                'viewer_note' => '',
                'has_negative_signal' => false,
            ];
        }
    }

    return $map;
}

function fcc_ai_get_conversation_messages(int $conversation_id, int $limit = 40, array $viewer_actor = []): array {
    if($conversation_id <= 0) {
        return [];
    }

    fcc_ai_ensure_tables();

    $limit = max(1, min(80, $limit));
    $messages = db()
        ->where('fcc_ai_conversation_id', $conversation_id)
        ->orderBy('fcc_ai_message_id', 'DESC')
        ->get('fcc_ai_messages', $limit, [
            'fcc_ai_message_id',
            'role',
            'message_type',
            'content',
            'datetime',
            'meta',
        ]);

    if(!$messages) {
        return [];
    }

    $messages = array_reverse($messages);
    $feedback_map = fcc_ai_get_message_feedback_map(array_map(static function($message) {
        return (int) ($message->fcc_ai_message_id ?? 0);
    }, $messages), $viewer_actor);

    return array_values(array_filter(array_map(static function($message) use ($feedback_map) {
        $content = trim((string) ($message->content ?? ''));

        if($content === '') {
            return null;
        }

        $message_id = (int) ($message->fcc_ai_message_id ?? 0);

        return [
            'message_id' => $message_id,
            'role' => (string) ($message->role ?? 'assistant'),
            'message_type' => (string) ($message->message_type ?? 'chat'),
            'content' => $content,
            'datetime' => (string) ($message->datetime ?? ''),
            'meta' => json_decode($message->meta ?? '{}', true) ?: [],
            'feedback' => $feedback_map[$message_id] ?? [
                'positive_total' => 0,
                'negative_total' => 0,
                'viewer_feedback_type' => '',
                'viewer_reason' => '',
                'viewer_note' => '',
                'has_negative_signal' => false,
            ],
        ];
    }, $messages)));
}

function fcc_ai_is_low_context_follow_up_message(string $message): bool {
    $message = trim($message);

    if($message === '') {
        return true;
    }

    if(
        fcc_ai_is_ambiguous_same_problem_followup_request($message)
        || fcc_ai_is_public_business_hesitation_followup_request($message)
        || fcc_ai_is_public_owner_help_followup_request($message)
    ) {
        return true;
    }

    if(count(fcc_ai_extract_search_tokens($message)) <= 4) {
        if(fcc_ai_contains_keywords($message, [
            'što je dobro',
            'sto je dobro',
            'što se preporuča',
            'što se preporučuje',
            'sto se preporuca',
            'preporuka za',
            'što koristiti',
            'sto koristiti',
            'imam problem',
            'imam',
            'kod ',
            'za ',
        ])) {
            return false;
        }

        return true;
    }

    return fcc_ai_contains_keywords($message, [
        'nastavi',
        'nastavi razgovor',
        'nastavi dalje',
        'može dalje',
        'moze dalje',
        'što dalje',
        'sto dalje',
        'sljedeći korak',
        'sledeci korak',
        'next step',
        'what next',
        'continue',
        'go on',
        'carry on',
        'keep going',
    ]);
}

