function fcc_ai_build_contextual_public_message(int $conversation_id, string $message): array {
    $message = trim($message);

    if($conversation_id <= 0 || !fcc_ai_is_low_context_follow_up_message($message)) {
        return [
            'message' => $message,
            'recent_user_context' => '',
            'used_context' => false,
        ];
    }

    $messages = fcc_ai_get_conversation_messages($conversation_id, 12);
    $user_messages = array_values(array_filter($messages, static function(array $row) use ($message) {
        return ($row['role'] ?? '') === 'user'
            && trim((string) ($row['content'] ?? '')) !== ''
            && trim((string) ($row['content'] ?? '')) !== trim($message);
    }));

    if(empty($user_messages)) {
        return [
            'message' => $message,
            'recent_user_context' => '',
            'used_context' => false,
        ];
    }

    $last_user_message = end($user_messages);
    $recent_user_context = trim((string) ($last_user_message['content'] ?? ''));

    if($recent_user_context === '') {
        return [
            'message' => $message,
            'recent_user_context' => '',
            'used_context' => false,
        ];
    }

    return [
        'message' => $recent_user_context . "\n\nFollow-up: " . $message,
        'recent_user_context' => $recent_user_context,
        'used_context' => true,
    ];
}

function fcc_ai_get_previous_public_user_message(int $conversation_id, string $current_message = ''): string {
    if($conversation_id <= 0) {
        return '';
    }

    $current_message = trim($current_message);
    $messages = array_reverse(fcc_ai_get_conversation_messages($conversation_id, 16));

    foreach($messages as $row) {
        if(($row['role'] ?? '') !== 'user') {
            continue;
        }

        $content = trim((string) ($row['content'] ?? ''));

        if($content === '' || ($current_message !== '' && $content === $current_message)) {
            continue;
        }

        return $content;
    }

    return '';
}

function fcc_ai_get_previous_internal_coach_user_message(int $conversation_id, string $current_message = ''): string {
    return fcc_ai_get_previous_public_user_message($conversation_id, $current_message);
}

function fcc_ai_get_previous_internal_coach_assistant_message(int $conversation_id): string {
    if($conversation_id <= 0) {
        return '';
    }

    $messages = array_reverse(fcc_ai_get_conversation_messages($conversation_id, 16));

    foreach($messages as $row) {
        if(($row['role'] ?? '') !== 'assistant') {
            continue;
        }

        $message_type = trim((string) ($row['message_type'] ?? 'chat'));
        if($message_type !== 'chat') {
            continue;
        }

        $content = trim((string) ($row['content'] ?? ''));
        if($content !== '') {
            return $content;
        }
    }

    return '';
}

