function fcc_ai_detect_thread_suspicion(array $thread_row, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $text = mb_strtolower(trim(implode(' ', array_filter([
        (string) ($thread_row['summary'] ?? ''),
        (string) ($thread_row['core_issue'] ?? ''),
        (string) ($thread_row['last_user_preview'] ?? ''),
        (string) ($thread_row['last_assistant_preview'] ?? ''),
    ]))));

    $flags = [];
    $score = 0;

    $append_flag = static function(string $key, string $label, int $weight) use (&$flags, &$score): void {
        if(!isset($flags[$key])) {
            $flags[$key] = [
                'key' => $key,
                'label' => $label,
                'weight' => $weight,
            ];
            $score += $weight;
        }
    };

    if($text !== '') {
        if(preg_match('/\b(lijek|lijekovi|terapij|dijagnoz|doktor|liječ|lijec|izliječ|izlijec|bolest|trudn|dojen|nuspojav|krvni tlak|štitnjača|stitnjaca)\b/ui', $text)) {
            $append_flag('compliance_health', $language === 'en' ? 'Health / compliance sensitive' : 'Zdravstveno / compliance osjetljivo', 65);
        }

        if(preg_match('/\b(zarada|zaraditi|provizij|bonus|plaća|placa|mjesečno|mjesecno|income|earn|guaranteed income|1000 ?e|500 ?e)\b/ui', $text)) {
            $append_flag('compliance_income', $language === 'en' ? 'Income-claim sensitive' : 'Osjetljivo na income claim', 65);
        }

        if(preg_match('/\b(ignore|zanemari|prompt|system prompt|pravila|upute sustava|developer message|otkrij pravila)\b/ui', $text)) {
            $append_flag('prompt_break', $language === 'en' ? 'Prompt-break attempt' : 'Pokušaj zaobilaženja pravila', 70);
        }

        if(preg_match('/\b(ne radi|glupo|katastrofa|prevara|laž|laz|bezveze|užas|uzas|frustrir|ljut|idiot)\b/ui', $text)) {
            $append_flag('friction_spike', $language === 'en' ? 'Frustration spike' : 'Skok frustracije', 40);
        }
    }

    if(
        trim((string) ($thread_row['scope'] ?? '')) === 'internal_coach'
        && (int) ($thread_row['total_user_messages'] ?? 0) >= 5
        && trim((string) ($thread_row['outcome_signal'] ?? '')) !== 'lead_captured'
        && empty($thread_row['needs_review'])
    ) {
        $append_flag('coach_dependency', $language === 'en' ? 'Coach dependency pattern' : 'Pattern ovisnosti o Coachu', 30);
    }

    $flags = array_values($flags);
    usort($flags, static function(array $a, array $b) {
        return (($b['weight'] ?? 0) <=> ($a['weight'] ?? 0))
            ?: strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
    });

    return [
        'score' => $score,
        'is_suspicious' => $score >= 50,
        'top_label' => (string) ($flags[0]['label'] ?? ''),
        'flags' => array_map(static function(array $flag): array {
            return [
                'key' => (string) ($flag['key'] ?? ''),
                'label' => (string) ($flag['label'] ?? ''),
            ];
        }, $flags),
    ];
}

function fcc_ai_build_chat_intelligence_thread_row(array $conversation_row, array $insight_map = [], string $language = 'hr'): array {
    $conversation_id = (int) ($conversation_row['conversation_id'] ?? 0);
    $insight = $insight_map[$conversation_id] ?? [];
    $summary = trim((string) ($insight['summary'] ?? ''));
    $core_issue = trim((string) ($insight['core_issue'] ?? ''));
    $primary_topic_label = trim((string) (($insight['primary_topic_label'] ?? '') ?: ($insight['primary_topic'] ?? '')));
    $quality_signal = trim((string) ($insight['quality_signal'] ?? 'neutral'));
    $outcome_signal = trim((string) ($insight['outcome_signal'] ?? (($conversation_row['lead_status'] ?? '') === 'captured' ? 'lead_captured' : 'active')));
    $needs_review = !empty($insight['needs_review']);

    $row = array_merge($conversation_row, [
        'summary' => $summary !== '' ? $summary : (string) ($conversation_row['last_user_preview'] ?? ''),
        'core_issue' => $core_issue !== '' ? $core_issue : (string) ($conversation_row['last_user_preview'] ?? ''),
        'primary_topic_label' => $primary_topic_label !== '' ? $primary_topic_label : ($language === 'en' ? 'General' : 'Opće'),
        'intent' => (string) ($insight['intent'] ?? ''),
        'quality_signal' => $quality_signal,
        'quality_badge' => fcc_ai_get_quality_signal_badge($quality_signal, $language),
        'outcome_signal' => $outcome_signal,
        'outcome_badge' => fcc_ai_get_outcome_signal_badge($outcome_signal, $language),
        'needs_review' => $needs_review,
        'source_page_title' => (string) (($insight['meta']['source_page_title'] ?? '') ?: ($insight['meta']['source_context'] ?? '')),
        'last_user_preview' => (string) ($conversation_row['last_user_preview'] ?? ''),
        'last_assistant_preview' => (string) ($conversation_row['last_assistant_preview'] ?? ''),
    ]);

    $row['suspicion'] = fcc_ai_detect_thread_suspicion($row, $language);

    return $row;
}

function fcc_ai_get_period_window_from_start(string $period_start_datetime): array {
    try {
        $now = new \DateTimeImmutable('now');
        $current_start = new \DateTimeImmutable(trim($period_start_datetime) !== '' ? $period_start_datetime : '-30 days');
    } catch(\Throwable $exception) {
        $now = new \DateTimeImmutable('now');
        $current_start = $now->modify('-30 days');
    }

    if($current_start > $now) {
        $current_start = $now->modify('-30 days');
    }

    $window_seconds = max(86400, $now->getTimestamp() - $current_start->getTimestamp());
    $previous_end = $current_start;
    $previous_start = $current_start->modify('-' . $window_seconds . ' seconds');

    return [
        'current_start' => $current_start->format('Y-m-d H:i:s'),
        'current_end' => $now->format('Y-m-d H:i:s'),
        'previous_start' => $previous_start->format('Y-m-d H:i:s'),
        'previous_end' => $previous_end->format('Y-m-d H:i:s'),
        'window_days' => max(1, (int) ceil($window_seconds / 86400)),
    ];
}

function fcc_ai_ensure_internal_notifications_enabled(bool $enable_users = false, bool $enable_admins = false): void {
    $settings_payload = settings()->internal_notifications ?? null;

    if(is_array($settings_payload)) {
        $settings_payload = (object) $settings_payload;
    }

    if(!$settings_payload instanceof \stdClass) {
        $settings_payload = (object) [];
    }

    $value = [
        'users_is_enabled' => (int) (($settings_payload->users_is_enabled ?? 0) || $enable_users),
        'admins_is_enabled' => (int) (($settings_payload->admins_is_enabled ?? 0) || $enable_admins),
        'new_user' => (int) (($settings_payload->new_user ?? 0)),
        'delete_user' => (int) (($settings_payload->delete_user ?? 0)),
        'new_newsletter_subscriber' => (int) (($settings_payload->new_newsletter_subscriber ?? 0)),
        'new_payment' => (int) (($settings_payload->new_payment ?? 0)),
        'new_affiliate_withdrawal' => (int) (($settings_payload->new_affiliate_withdrawal ?? 0)),
    ];

    if(
        (int) ($settings_payload->users_is_enabled ?? 0) === $value['users_is_enabled']
        && (int) ($settings_payload->admins_is_enabled ?? 0) === $value['admins_is_enabled']
    ) {
        return;
    }

    $existing_row = db()->where('`key`', 'internal_notifications')->getOne('settings');

    if($existing_row) {
        db()->where('`key`', 'internal_notifications')->update('settings', [
            'value' => json_encode($value),
        ]);
    } else {
        db()->insert('settings', [
            'key' => 'internal_notifications',
            'value' => json_encode($value),
        ]);
    }

    settings()->internal_notifications = (object) $value;
    cache()->deleteItem('settings');
}

function fcc_ai_push_internal_notification(?int $user_id, string $for_who, string $title, string $description, string $url = '', string $icon = 'fas fa-robot', string $from_who = 'system'): void {
    $for_who = trim(mb_strtolower($for_who));
    $from_who = trim(mb_strtolower($from_who));

    if(!in_array($for_who, ['user', 'admin'], true)) {
        return;
    }

    if(!in_array($from_who, ['system', 'admin'], true)) {
        $from_who = 'system';
    }

    if($for_who === 'user' && (int) $user_id <= 0) {
        return;
    }

    fcc_ai_ensure_internal_notifications_enabled($for_who === 'user', $for_who === 'admin');

    db()->insert('internal_notifications', [
        'user_id' => $for_who === 'user' ? (int) $user_id : null,
        'for_who' => $for_who,
        'from_who' => $from_who,
        'icon' => $icon,
        'title' => mb_substr(trim($title), 0, 256),
        'description' => mb_substr(trim($description), 0, 1000),
        'url' => trim($url),
        'datetime' => get_date(),
    ]);

    if($for_who === 'user' && (int) $user_id > 0) {
        db()->where('user_id', (int) $user_id)->update('users', [
            'has_pending_internal_notifications' => 1,
        ]);

        cache()->deleteItemsByTag('user_id=' . (int) $user_id);
        cache()->deleteItem('user?user_id=' . (int) $user_id);
    }
}

function fcc_ai_get_admin_review_url_for_conversation(object $conversation): string {
    $user_id = (int) ($conversation->user_id ?? 0);

    if($user_id <= 0) {
        return url('admin/leader-operating-system?tab=ai_intelligence&period=30d');
    }

    return url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=30d') . '#leader-os-ai-chats';
}

function fcc_ai_notify_feedback_review(object $conversation, string $reason = '', string $note = ''): void {
    $language = fcc_ai_resolve_public_reply_language((string) ($conversation->language ?? \Altum\Language::$code ?? 'hr'));
    $assistant_label = fcc_ai_get_assistant_label((string) ($conversation->assistant_type ?? ''));
    $reason_label = fcc_ai_get_feedback_reason_label($reason, $language);
    $user_url = url('fcc-ai?conversation=' . urlencode((string) ($conversation->public_id ?? ''))) . '#fcc-ai-review';
    $admin_url = fcc_ai_get_admin_review_url_for_conversation($conversation);

    $user_title = $language === 'en' ? 'AI answer needs review' : 'AI odgovor traži provjeru';
    $user_description = $language === 'en'
        ? $assistant_label . ' received a bad-answer signal' . ($reason_label !== '' ? ' (' . $reason_label . ')' : '') . '. Open the conversation and refine the assistant settings or communication.'
        : $assistant_label . ' je dobio signal lošeg odgovora' . ($reason_label !== '' ? ' (' . $reason_label . ')' : '') . '. Otvori razgovor i doradi postavke ili komunikaciju asistenta.';

    if(trim($note) !== '') {
        $user_description .= ' ' . ($language === 'en' ? 'Note:' : 'Napomena:') . ' ' . fcc_ai_excerpt(trim($note), 120);
    }

    fcc_ai_push_internal_notification((int) ($conversation->user_id ?? 0), 'user', $user_title, $user_description, $user_url, 'fas fa-comment-exclamation');

    $admin_title = $language === 'en' ? 'AI answer reported for review' : 'AI odgovor prijavljen za provjeru';
    $admin_description = $assistant_label . ' · user #' . (int) ($conversation->user_id ?? 0) . ($reason_label !== '' ? ' · ' . $reason_label : '');
    fcc_ai_push_internal_notification(null, 'admin', $admin_title, $admin_description, $admin_url, 'fas fa-comment-exclamation');
}

function fcc_ai_notify_lead_captured(object $conversation, int $datum_id, string $lead_type, int $lead_score): void {
    $language = fcc_ai_resolve_public_reply_language((string) ($conversation->language ?? \Altum\Language::$code ?? 'hr'));
    $assistant_label = fcc_ai_get_assistant_label((string) ($conversation->assistant_type ?? ''));
    $lead_type_label = fcc_ai_get_lead_type_label($lead_type, $language);
    $user_url = $datum_id > 0 ? url('data?datum_id=' . $datum_id) : url('data');
    $admin_url = fcc_ai_get_admin_review_url_for_conversation($conversation);

    $user_title = $language === 'en' ? 'New AI lead arrived' : 'Stigao je novi AI lead';
    $user_description = $language === 'en'
        ? $assistant_label . ' captured a new ' . mb_strtolower($lead_type_label) . ' signal with score ' . nr($lead_score) . '. Open the contact and continue the follow-up.'
        : $assistant_label . ' je uhvatio novi signal za ' . mb_strtolower($lead_type_label) . ' s ocjenom ' . nr($lead_score) . '. Otvori kontakt i nastavi follow-up.';

    fcc_ai_push_internal_notification((int) ($conversation->user_id ?? 0), 'user', $user_title, $user_description, $user_url, 'fas fa-user-plus');

    $admin_title = $language === 'en' ? 'New FCC AI lead' : 'Novi FCC AI lead';
    $admin_description = $assistant_label . ' · ' . $lead_type_label . ' · score ' . nr($lead_score);
    fcc_ai_push_internal_notification(null, 'admin', $admin_title, $admin_description, $admin_url, 'fas fa-user-plus');
}

function fcc_ai_get_recent_user_alerts(int $user_id, int $limit = 4, bool $hide_coach_review = false): array {
    if($user_id <= 0) {
        return [];
    }

    $limit = max(1, min(8, $limit));
    $alerts = [];
    $icon_sql = "'fas fa-user-plus','fas fa-check-circle'";
    $query_limit = $hide_coach_review ? max(16, $limit * 4) : max(12, $limit * 3);
    $result = database()->query("SELECT
            `internal_notification_id`,
            `icon`,
            `title`,
            `description`,
            `url`,
            `is_read`,
            `datetime`
        FROM `internal_notifications`
        WHERE `for_who` = 'user'
          AND `user_id` = {$user_id}
          AND `icon` IN ({$icon_sql})
        ORDER BY `internal_notification_id` DESC
        LIMIT {$query_limit}");

    while($result && $row = $result->fetch_assoc()) {
        $alerts[] = [
            'title' => (string) ($row['title'] ?? ''),
            'description' => (string) ($row['description'] ?? ''),
            'url' => (string) ($row['url'] ?? ''),
            'icon' => (string) ($row['icon'] ?? ''),
            'is_read' => (int) ($row['is_read'] ?? 0),
            'datetime' => (string) ($row['datetime'] ?? ''),
        ];
    }

    $is_ai_alert = static function(array $alert): bool {
        $icon = trim((string) ($alert['icon'] ?? ''));
        $title = mb_strtolower(trim((string) ($alert['title'] ?? '')));
        $url = mb_strtolower(trim((string) ($alert['url'] ?? '')));

        if($icon === 'fas fa-user-plus') {
            return strpos($title, 'ai lead') !== false;
        }

        if($icon === 'fas fa-check-circle') {
            return in_array($title, [
                'ai improved thanks to your signal',
                'ai je unaprijeđen zahvaljujući tvom signalu',
                'ai je izboljšan zaradi vašega signala',
                'ai е подобрен благодарение на вашия сигнал',
            ], true);
        }

        return false;
    };

    $alerts = array_values(array_filter($alerts, $is_ai_alert));

    $extract_conversation_public_id = static function(string $url): string {
        if(trim($url) === '') {
            return '';
        }

        $query = parse_url($url, PHP_URL_QUERY);

        if(!is_string($query) || $query === '') {
            return '';
        }

        parse_str($query, $query_payload);

        return trim((string) ($query_payload['conversation'] ?? ''));
    };

    $resolved_cutoff = (new \DateTimeImmutable('-5 days'))->format('Y-m-d H:i:s');

    $alerts = array_values(array_filter($alerts, static function(array $alert) use ($resolved_cutoff): bool {
        $icon = trim((string) ($alert['icon'] ?? ''));
        $title = trim((string) ($alert['title'] ?? ''));

        $is_ai_lead_alert = $icon === 'fas fa-user-plus'
            && preg_match('/\bAI lead\b/ui', $title);

        $is_ai_resolution_alert = $icon === 'fas fa-check-circle'
            && preg_match('/^AI\b/ui', $title);

        if(!$is_ai_lead_alert && !$is_ai_resolution_alert) {
            return false;
        }

        if($is_ai_resolution_alert) {
            $datetime = (string) ($alert['datetime'] ?? '');

            if($datetime === '' || $datetime < $resolved_cutoff) {
                return false;
            }
        }

        return true;
    }));

    return array_slice($alerts, 0, $limit);
}

function fcc_ai_build_user_recent_alerts(array $recent_negative_feedback, array $system_alerts, string $language = 'hr', int $limit = 4): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(1, min(8, $limit));
    $alerts = [];

    $review_title = match($language) {
        'en' => 'AI answer needs review',
        'sl' => 'AI odgovor potrebuje pregled',
        'bg' => 'AI отговорът изисква проверка',
        default => 'AI odgovor traži provjeru',
    };

    foreach($recent_negative_feedback as $feedback_row) {
        $assistant_label = trim((string) ($feedback_row['assistant_label'] ?? 'AI'));
        $reason_label = trim((string) ($feedback_row['reason_label'] ?? ''));
        $note = trim((string) ($feedback_row['note'] ?? ''));
        $message_excerpt = trim((string) ($feedback_row['message_excerpt'] ?? ''));
        $case_summary = $note !== '' ? $note : $message_excerpt;

        if($case_summary === '') {
            $case_summary = $reason_label;
        }

        $description = match($language) {
            'en' => $assistant_label . ' received a review signal'
                . ($reason_label !== '' ? ' (' . $reason_label . ')' : '')
                . '.'
                . ($case_summary !== '' ? ' Case: ' . $case_summary : ' Open the conversation and check what should be improved.'),
            'sl' => $assistant_label . ' je prejel signal za pregled'
                . ($reason_label !== '' ? ' (' . $reason_label . ')' : '')
                . '.'
                . ($case_summary !== '' ? ' Primer: ' . $case_summary : ' Odprite pogovor in preverite, kaj je treba izboljšati.'),
            'bg' => $assistant_label . ' получи сигнал за проверка'
                . ($reason_label !== '' ? ' (' . $reason_label . ')' : '')
                . '.'
                . ($case_summary !== '' ? ' Случай: ' . $case_summary : ' Отворете разговора и вижте какво трябва да се подобри.'),
            default => $assistant_label . ' je dobio signal za provjeru'
                . ($reason_label !== '' ? ' (' . $reason_label . ')' : '')
                . '.'
                . ($case_summary !== '' ? ' Slučaj: ' . $case_summary : ' Otvori razgovor i provjeri što treba doraditi.'),
        };

        $alerts[] = [
            'title' => $review_title,
            'description' => fcc_ai_excerpt($description, 220),
            'url' => !empty($feedback_row['conversation_public_id']) ? url('fcc-ai?conversation=' . urlencode((string) $feedback_row['conversation_public_id']) . '#fcc-ai-review') : '',
            'icon' => 'fas fa-comment-exclamation',
            'is_read' => 0,
            'datetime' => (string) ($feedback_row['datetime'] ?? ''),
        ];
    }

    foreach($system_alerts as $alert_row) {
        $alerts[] = $alert_row;
    }

    usort($alerts, static function(array $a, array $b) {
        return strcmp((string) ($b['datetime'] ?? ''), (string) ($a['datetime'] ?? ''));
    });

    return array_slice($alerts, 0, $limit);
}

function fcc_ai_get_topic_trend_rows(string $period_start_datetime, array $allowed_user_ids = [], int $limit = 6, bool $exclude_coach = false): array {
    if(!fcc_ai_tables_ready()) {
        return [];
    }

    $window = fcc_ai_get_period_window_from_start($period_start_datetime);
    $current_start_sql = db()->escape($window['current_start']);
    $previous_start_sql = db()->escape($window['previous_start']);
    $previous_end_sql = db()->escape($window['previous_end']);
    $allowed_user_ids = array_values(array_unique(array_filter(array_map('intval', $allowed_user_ids), static function($user_id) {
        return $user_id > 0;
    })));
    $user_sql = $allowed_user_ids ? implode(',', $allowed_user_ids) : '';
    $user_filter = $user_sql !== '' ? " AND `user_id` IN ({$user_sql})" : '';
    $coach_filter = $exclude_coach ? " AND COALESCE(`assistant_type`, '') != 'coach' AND COALESCE(`scope`, '') != 'internal_coach'" : '';
    $limit = max(1, min(12, $limit));

    $current_topics = [];
    $current_result = database()->query("SELECT
            `primary_topic`,
            `primary_topic_label`,
            COUNT(*) AS `total`
        FROM `fcc_ai_conversation_insights`
        WHERE COALESCE(`last_datetime`, `datetime`) >= '{$current_start_sql}'{$user_filter}{$coach_filter}
          AND `primary_topic` IS NOT NULL
          AND `primary_topic` != ''
        GROUP BY `primary_topic`, `primary_topic_label`");

    while($current_result && $row = $current_result->fetch_assoc()) {
        $topic_key = (string) ($row['primary_topic'] ?? '');

        if($topic_key === '') {
            continue;
        }

        $current_topics[$topic_key] = [
            'key' => $topic_key,
            'label' => (string) (($row['primary_topic_label'] ?? '') ?: $topic_key),
            'current_total' => (int) ($row['total'] ?? 0),
            'previous_total' => 0,
            'delta_total' => 0,
            'growth_percent' => null,
        ];
    }

    $previous_result = database()->query("SELECT
            `primary_topic`,
            COUNT(*) AS `total`
        FROM `fcc_ai_conversation_insights`
        WHERE COALESCE(`last_datetime`, `datetime`) >= '{$previous_start_sql}'
          AND COALESCE(`last_datetime`, `datetime`) < '{$previous_end_sql}'{$user_filter}{$coach_filter}
          AND `primary_topic` IS NOT NULL
          AND `primary_topic` != ''
        GROUP BY `primary_topic`");

    while($previous_result && $row = $previous_result->fetch_assoc()) {
        $topic_key = (string) ($row['primary_topic'] ?? '');

        if($topic_key === '' || !isset($current_topics[$topic_key])) {
            continue;
        }

        $current_topics[$topic_key]['previous_total'] = (int) ($row['total'] ?? 0);
    }

    foreach($current_topics as $topic_key => $topic_row) {
        $current_total = (int) ($topic_row['current_total'] ?? 0);
        $previous_total = (int) ($topic_row['previous_total'] ?? 0);
        $delta_total = $current_total - $previous_total;
        $current_topics[$topic_key]['delta_total'] = $delta_total;
        $current_topics[$topic_key]['growth_percent'] = $previous_total > 0 ? round(($delta_total / $previous_total) * 100, 1) : ($current_total > 0 ? 100.0 : 0.0);
    }

    $rows = array_values(array_filter($current_topics, static function(array $row) {
        return (int) ($row['current_total'] ?? 0) > 0 && (int) ($row['delta_total'] ?? 0) > 0;
    }));

    usort($rows, static function(array $a, array $b) {
        return (($b['delta_total'] ?? 0) <=> ($a['delta_total'] ?? 0))
            ?: (($b['current_total'] ?? 0) <=> ($a['current_total'] ?? 0))
            ?: strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
    });

    return array_slice($rows, 0, $limit);
}

function fcc_ai_build_webinar_candidate_rows(array $top_topics, array $rising_topics, array $recent_negative_feedback, string $language = 'hr', int $limit = 4): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $rows = [];
    $used_topics = [];
    $limit = max(1, min(6, $limit));

    $review_hint = !empty($recent_negative_feedback)
        ? ($language === 'en'
            ? 'Add examples of unclear AI answers and show how to improve the next step.'
            : 'Uključi i primjere nejasnih AI odgovora te pokaži kako izgleda bolji sljedeći korak.')
        : ($language === 'en'
            ? 'Connect the topic to practical scripts, examples, and the next move for the collaborator.'
            : 'Poveži temu s praktičnim skriptama, primjerima i sljedećim potezom za suradnika.');

    $sources = array_merge(
        array_map(static function(array $row) {
            $row['source_type'] = 'rising';
            return $row;
        }, $rising_topics),
        array_map(static function(array $row) {
            $row['source_type'] = 'top';
            $row['current_total'] = (int) ($row['total'] ?? 0);
            $row['delta_total'] = 0;
            return $row;
        }, $top_topics)
    );

    foreach($sources as $source_row) {
        $topic_key = trim((string) ($source_row['key'] ?? ''));
        $topic_label = trim((string) ($source_row['label'] ?? ''));

        if($topic_label === '' || isset($used_topics[$topic_key !== '' ? $topic_key : $topic_label])) {
            continue;
        }

        $current_total = (int) ($source_row['current_total'] ?? 0);
        $delta_total = (int) ($source_row['delta_total'] ?? 0);
        $is_rising = (string) ($source_row['source_type'] ?? '') === 'rising';

        $rows[] = [
            'topic_key' => $topic_key,
            'topic_label' => $topic_label,
            'title' => ($language === 'en' ? 'Webinar:' : 'Webinar:') . ' ' . $topic_label,
            'why_now' => $is_rising
                ? ($language === 'en'
                    ? 'This topic is rising through real AI conversations (+' . nr($delta_total) . ' vs previous period, ' . nr($current_total) . ' total now).'
                    : 'Ova tema raste kroz stvarne AI razgovore (+' . nr($delta_total) . ' u odnosu na prošli period, sada ukupno ' . nr($current_total) . ').')
                : ($language === 'en'
                    ? 'This topic repeats through ' . nr($current_total) . ' conversations and deserves a clearer team explanation.'
                    : 'Ova tema se ponavlja kroz ' . nr($current_total) . ' razgovora i zaslužuje jasnije timsko objašnjenje.'),
            'agenda' => $review_hint,
        ];

        $used_topics[$topic_key !== '' ? $topic_key : $topic_label] = true;

        if(count($rows) >= $limit) {
            break;
        }
    }

    return $rows;
}

function fcc_ai_build_help_watchlist(array $top_users, string $language = 'hr', int $limit = 5): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $rows = [];

    foreach($top_users as $user_row) {
        $coach_conversations = (int) ($user_row['coach_conversations'] ?? 0);
        $public_conversations = (int) ($user_row['public_conversations'] ?? 0);
        $leads = (int) ($user_row['leads'] ?? 0);
        $negative_feedback = (int) ($user_row['negative_feedback'] ?? 0);
        $conversations = (int) ($user_row['conversations'] ?? 0);

        $help_score = ($coach_conversations * 10) + ($negative_feedback * 14) + (max(0, $public_conversations - ($leads * 2)) * 4);

        if($conversations >= 3 && $leads === 0) {
            $help_score += 10;
        }

        if($help_score < 16) {
            continue;
        }

        if($negative_feedback >= 2) {
            $reason = $language === 'en'
                ? 'More than one AI answer was marked for review, so the communication or rules likely need correction.'
                : 'Više AI odgovora označeno je za provjeru, pa komunikacija ili pravila vjerojatno traže korekciju.';
        } elseif($coach_conversations >= 2 && $leads === 0) {
            $reason = $language === 'en'
                ? 'The collaborator actively uses Coach, but the work still is not turning into visible lead or follow-up signal.'
                : 'Suradnik aktivno koristi Coach, ali rad se još ne pretvara u vidljiv lead ili follow-up signal.';
        } else {
            $reason = $language === 'en'
                ? 'The public AI has traffic, but the result is still weak and likely needs mentor support or sharper settings.'
                : 'Javni AI ima promet, ali rezultat je još slab i vjerojatno treba mentorsku pomoć ili preciznije postavke.';
        }

        $rows[] = [
            'user_id' => (int) ($user_row['user_id'] ?? 0),
            'name' => (string) ($user_row['name'] ?? l('global.unknown')),
            'detail_url' => (string) ($user_row['detail_url'] ?? ''),
            'help_score' => $help_score,
            'reason' => $reason,
            'coach_conversations' => $coach_conversations,
            'public_conversations' => $public_conversations,
            'leads' => $leads,
            'negative_feedback' => $negative_feedback,
        ];
    }

    usort($rows, static function(array $a, array $b) {
        return (($b['help_score'] ?? 0) <=> ($a['help_score'] ?? 0))
            ?: (($b['negative_feedback'] ?? 0) <=> ($a['negative_feedback'] ?? 0))
            ?: (($b['coach_conversations'] ?? 0) <=> ($a['coach_conversations'] ?? 0));
    });

    return array_slice($rows, 0, max(1, min(8, $limit)));
}

function fcc_ai_build_assistant_performance_rows(array $assistant_breakdown, string $language = 'hr', int $limit = 6): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $rows = [];

    foreach($assistant_breakdown as $assistant_row) {
        $conversations = (int) ($assistant_row['conversations'] ?? 0);

        if($conversations <= 0) {
            continue;
        }

        $leads = (int) ($assistant_row['leads'] ?? 0);
        $business_leads = (int) ($assistant_row['business_leads'] ?? 0);
        $negative_feedback = (int) ($assistant_row['negative_feedback'] ?? 0);
        $positive_feedback = (int) ($assistant_row['positive_feedback'] ?? 0);
        $lead_rate = round(($leads / max(1, $conversations)) * 100, 1);
        $review_rate = round(($negative_feedback / max(1, $conversations)) * 100, 1);
        $result_score = ($leads * 8) + ($business_leads * 12) + ($positive_feedback * 2) - ($negative_feedback * 6);

        $summary = $language === 'en'
            ? 'Lead rate ' . nr($lead_rate) . '% · business leads ' . nr($business_leads) . ' · review rate ' . nr($review_rate) . '%.'
            : 'Lead rate ' . nr($lead_rate) . '% · business leadovi ' . nr($business_leads) . ' · review rate ' . nr($review_rate) . '%.';

        $opportunity = $negative_feedback > $leads
            ? ($language === 'en'
                ? 'First improve clarity, rules, and the next-step CTA.'
                : 'Prvo doradi jasnoću, pravila i CTA za sljedeći korak.')
            : ($language === 'en'
                ? 'This assistant is a good candidate for extra scaling and sharper CTA experiments.'
                : 'Ovaj asistent je dobar kandidat za dodatni scale i preciznije CTA eksperimente.');

        $rows[] = [
            'assistant_type' => (string) ($assistant_row['assistant_type'] ?? ''),
            'label' => (string) ($assistant_row['label'] ?? ''),
            'conversations' => $conversations,
            'leads' => $leads,
            'business_leads' => $business_leads,
            'negative_feedback' => $negative_feedback,
            'lead_rate' => $lead_rate,
            'review_rate' => $review_rate,
            'result_score' => $result_score,
            'summary' => $summary,
            'opportunity' => $opportunity,
        ];
    }

    usort($rows, static function(array $a, array $b) {
        return (($b['result_score'] ?? 0) <=> ($a['result_score'] ?? 0))
            ?: (($b['lead_rate'] ?? 0) <=> ($a['lead_rate'] ?? 0))
            ?: (($a['review_rate'] ?? 0) <=> ($b['review_rate'] ?? 0));
    });

    return array_slice($rows, 0, max(1, min(8, $limit)));
}

function fcc_ai_build_team_useful_items(array $team_payload, string $language = 'hr', int $limit = 4): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $items = [];
    $top_topic = $team_payload['top_topics'][0]['label'] ?? '';
    $rising_topic = $team_payload['rising_topics'][0]['label'] ?? '';
    $top_watch = $team_payload['help_watchlist'][0]['name'] ?? '';
    $top_assistant = $team_payload['assistant_performance'][0]['label'] ?? '';

    if((int) ($team_payload['totals']['negative_feedback'] ?? 0) > 0) {
        $items[] = $language === 'en'
            ? 'Open the review queue first because bad-answer signals already show where quality is breaking.'
            : 'Prvo otvori review red jer loši odgovori već pokazuju gdje kvaliteta puca.';
    }

    if($rising_topic !== '') {
        $items[] = $language === 'en'
            ? 'The topic "' . $rising_topic . '" is rising and is the strongest immediate candidate for webinar or FAQ.'
            : 'Tema "' . $rising_topic . '" je u rastu i trenutno je najjači kandidat za webinar ili FAQ.';
    } elseif($top_topic !== '') {
        $items[] = $language === 'en'
            ? 'The most repeated AI topic right now is "' . $top_topic . '", so it deserves clearer scripts and explanation.'
            : 'Najponavljanija AI tema sada je "' . $top_topic . '", pa zaslužuje jasnije skripte i objašnjenje.';
    }

    if($top_watch !== '') {
        $items[] = $language === 'en'
            ? 'The first collaborator to open for mentor help is ' . $top_watch . '.'
            : 'Prvi suradnik kojeg vrijedi otvoriti za mentorsku pomoć je ' . $top_watch . '.';
    }

    if($top_assistant !== '') {
        $items[] = $language === 'en'
            ? $top_assistant . ' currently carries the strongest AI result, so use it as the first optimization reference.'
            : $top_assistant . ' trenutno nosi najjači AI rezultat pa ga koristi kao prvi referentni primjer za optimizaciju.';
    }

    return array_slice(array_values(array_unique(array_filter($items))), 0, max(1, min(6, $limit)));
}

function fcc_ai_get_team_recent_conversation_rows(string $period_start_datetime, array $allowed_user_ids = [], int $limit = 12, string $language = 'hr', string $detail_period = '30d'): array {
    if(!fcc_ai_tables_ready()) {
        return [];
    }

    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(1, min(30, $limit));
    $period_start_datetime = trim($period_start_datetime) !== '' ? trim($period_start_datetime) : date('Y-m-d 00:00:00', strtotime('-30 days'));
    $period_start_sql = db()->escape($period_start_datetime);
    $allowed_user_ids = array_values(array_unique(array_filter(array_map('intval', $allowed_user_ids), static function($user_id) {
        return $user_id > 0;
    })));
    $user_sql = $allowed_user_ids ? implode(',', $allowed_user_ids) : '';
    $conversation_user_filter = $user_sql !== '' ? " AND `c`.`user_id` IN ({$user_sql})" : '';
    $rows = [];

    $conversation_result = database()->query("SELECT
            `c`.`fcc_ai_conversation_id`,
            `c`.`assistant_type`,
            `c`.`scope`,
            `c`.`public_id`,
            `c`.`lead_status`,
            `c`.`total_user_messages`,
            `c`.`total_assistant_messages`,
            `c`.`meta` AS `conversation_meta`,
            COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`) AS `activity_at`,
            `a`.`display_name` AS `assistant_display_name`,
            `u`.`user_id`,
            `u`.`name` AS `owner_name`
        FROM `fcc_ai_conversations` AS `c`
        LEFT JOIN `fcc_ai_assistants` AS `a` ON `a`.`fcc_ai_assistant_id` = `c`.`fcc_ai_assistant_id`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `c`.`user_id`
        WHERE COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`) >= '{$period_start_sql}'{$conversation_user_filter}
        ORDER BY `activity_at` DESC
        LIMIT {$limit}");

    while($conversation_result && $row = $conversation_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $assistant_label = trim((string) ($row['assistant_display_name'] ?? ''));

        if($assistant_label === '') {
            $assistant_label = fcc_ai_get_assistant_label($assistant_type);
        }

        $conversation_id = (int) ($row['fcc_ai_conversation_id'] ?? 0);
        $user_id = (int) ($row['user_id'] ?? 0);
        $conversation_meta = json_decode((string) ($row['conversation_meta'] ?? '{}'), true) ?: [];

        $rows[] = [
            'conversation_id' => $conversation_id,
            'user_id' => $user_id,
            'owner_name' => (string) ($row['owner_name'] ?? l('global.unknown')),
            'detail_url' => $user_id > 0 ? url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)) . '#leader-os-chat-review-inbox' : '',
            'assistant_type' => $assistant_type,
            'assistant_label' => $assistant_label,
            'scope' => (string) ($row['scope'] ?? ''),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'lead_status' => (string) ($row['lead_status'] ?? 'none'),
            'total_user_messages' => (int) ($row['total_user_messages'] ?? 0),
            'total_assistant_messages' => (int) ($row['total_assistant_messages'] ?? 0),
            'last_user_preview' => fcc_ai_get_conversation_role_preview($conversation_id, 'user'),
            'last_assistant_preview' => fcc_ai_get_conversation_role_preview($conversation_id, 'assistant'),
            'thread_preview' => $conversation_id > 0 ? array_slice(fcc_ai_get_conversation_messages($conversation_id, 12), -8) : [],
            'activity_at' => (string) ($row['activity_at'] ?? ''),
            'public_id' => (string) ($row['public_id'] ?? ''),
            'source_label' => trim((string) (($conversation_meta['source_page_title'] ?? '') ?: ($conversation_meta['source_context'] ?? ''))),
        ];
    }

    if(empty($rows)) {
        return [];
    }

    $insight_map = fcc_ai_get_conversation_insight_map(array_map(static function(array $row): int {
        return (int) ($row['conversation_id'] ?? 0);
    }, $rows));

    return array_map(static function(array $row) use ($insight_map, $language): array {
        return fcc_ai_build_chat_intelligence_thread_row($row, $insight_map, $language);
    }, $rows);
}

function fcc_ai_build_team_control_tower_payload(array $team_payload, string $language = 'hr', int $limit = 6): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(3, min(10, $limit));
    $recent_threads = array_values((array) ($team_payload['recent_threads'] ?? []));
    $top_users = array_values((array) ($team_payload['top_users'] ?? []));
    $help_watchlist = array_values((array) ($team_payload['help_watchlist'] ?? []));
    $recent_negative_feedback = array_values((array) ($team_payload['recent_negative_feedback'] ?? []));
    $recent_hot_leads = array_values((array) ($team_payload['recent_hot_leads'] ?? []));
    $rising_topics = array_values((array) ($team_payload['rising_topics'] ?? []));
    $top_topics = array_values((array) ($team_payload['top_topics'] ?? []));

    $payload = [
        'headline' => '',
        'executive_summary' => '',
        'admin_changes' => [],
        'counts' => [
            'review_threads' => 0,
            'suspicious_threads' => 0,
            'coach_priority' => 0,
            'public_priority' => 0,
            'lead_threads' => 0,
        ],
        'coach' => [
            'summary' => '',
            'blocker' => '',
            'next_admin_move' => '',
            'top_topics' => [],
            'queue' => [],
        ],
        'public_ai' => [
            'summary' => '',
            'blocker' => '',
            'next_admin_move' => '',
            'top_topics' => [],
            'queue' => [],
        ],
        'suspicious_threads' => [],
        'review_threads' => [],
        'lead_threads' => array_slice($recent_hot_leads, 0, $limit),
        'inbox' => [
            'tabs' => [],
            'coach_threads' => [],
            'public_threads' => [],
            'suspicious_threads' => [],
            'review_threads' => [],
            'lead_threads' => [],
        ],
    ];

    if(empty($recent_threads) && empty($recent_negative_feedback) && empty($recent_hot_leads)) {
        $payload['headline'] = 'Još nema dovoljno AI signala za team control tower.';
        $payload['executive_summary'] = 'Kad se skupi više razgovora, leadova i review slučajeva, ovdje ćeš odmah vidjeti gdje treba intervenirati.';
        return $payload;
    }

    $top_users_map = [];
    foreach($top_users as $user_row) {
        $top_users_map[(int) ($user_row['user_id'] ?? 0)] = $user_row;
    }

    $coach_topics = [];
    $public_topics = [];
    $coach_thread_total = 0;
    $public_thread_total = 0;
    $public_conversion_threads = 0;
    $coach_threads = [];
    $public_threads = [];
    $suspicious_threads = [];

    foreach($recent_threads as $thread_row) {
        $scope = trim((string) ($thread_row['scope'] ?? ''));
        $topic_label = trim((string) ($thread_row['primary_topic_label'] ?? ''));
        $quality_signal = (string) ($thread_row['quality_signal'] ?? 'neutral');
        $outcome_signal = (string) ($thread_row['outcome_signal'] ?? '');
        $is_coach = $scope === 'internal_coach';

        if($is_coach) {
            $coach_thread_total++;
            $coach_threads[] = $thread_row;
            if($topic_label !== '') {
                $coach_topics[$topic_label] = ($coach_topics[$topic_label] ?? 0) + 1;
            }
        } else {
            $public_thread_total++;
            $public_threads[] = $thread_row;
            if($topic_label !== '') {
                $public_topics[$topic_label] = ($public_topics[$topic_label] ?? 0) + 1;
            }
            if(in_array($outcome_signal, ['lead_captured', 'business_interest', 'mixed_interest'], true)) {
                $public_conversion_threads++;
            }
        }

        if(!empty($thread_row['needs_review']) || !empty($thread_row['suspicion']['is_suspicious']) || (int) ($thread_row['suspicion']['score'] ?? 0) >= 40 || $quality_signal === 'needs_review') {
            $suspicious_threads[] = $thread_row;
        }
    }

    arsort($coach_topics);
    arsort($public_topics);

    $coach_topic_rows = array_map(static function(string $label, int $total): array {
        return ['label' => $label, 'total' => $total];
    }, array_keys($coach_topics), array_values($coach_topics));
    $public_topic_rows = array_map(static function(string $label, int $total): array {
        return ['label' => $label, 'total' => $total];
    }, array_keys($public_topics), array_values($public_topics));

    $coach_queue = [];
    foreach($help_watchlist as $watch_row) {
        $user_id = (int) ($watch_row['user_id'] ?? 0);
        $user_row = $top_users_map[$user_id] ?? [];
        $coach_conversations = (int) ($user_row['coach_conversations'] ?? ($watch_row['coach_conversations'] ?? 0));
        $public_conversations = (int) ($user_row['public_conversations'] ?? ($watch_row['public_conversations'] ?? 0));
        $leads = (int) ($user_row['leads'] ?? ($watch_row['leads'] ?? 0));
        $negative_feedback = (int) ($user_row['negative_feedback'] ?? ($watch_row['negative_feedback'] ?? 0));

        if($coach_conversations < 2 && $negative_feedback <= 0) {
            continue;
        }

        $reason = trim((string) ($watch_row['reason'] ?? ''));
        if($negative_feedback > 1) {
            $reason = 'Coach i AI signal zajedno pokazuju više review slučajeva pa ovoj osobi treba precizniji mentorski follow-up.';
        } elseif($coach_conversations >= 3 && $leads === 0) {
            $reason = 'Coach je aktivan, ali se pomoć još ne pretvara u execution i jasan rezultatski signal.';
        } elseif($reason === '') {
            $reason = 'Vrijedi otvoriti zadnje Coach razgovore i srezati fokus na jedan mjerljiv potez.';
        }

        $coach_queue[] = [
            'user_id' => $user_id,
            'name' => (string) ($watch_row['name'] ?? ($user_row['name'] ?? l('global.unknown'))),
            'detail_url' => (string) (($watch_row['detail_url'] ?? '') ?: ($user_row['detail_url'] ?? '')),
            'coach_conversations' => $coach_conversations,
            'public_conversations' => $public_conversations,
            'leads' => $leads,
            'negative_feedback' => $negative_feedback,
            'reason' => $reason,
        ];
    }

    usort($coach_queue, static function(array $a, array $b) {
        return (($b['coach_conversations'] ?? 0) <=> ($a['coach_conversations'] ?? 0))
            ?: (($b['negative_feedback'] ?? 0) <=> ($a['negative_feedback'] ?? 0))
            ?: (($a['leads'] ?? 0) <=> ($b['leads'] ?? 0));
    });

    $public_queue = [];
    foreach($top_users as $user_row) {
        $public_conversations = (int) ($user_row['public_conversations'] ?? 0);
        $coach_conversations = (int) ($user_row['coach_conversations'] ?? 0);
        $leads = (int) ($user_row['leads'] ?? 0);
        $business_leads = (int) ($user_row['business_leads'] ?? 0);
        $negative_feedback = (int) ($user_row['negative_feedback'] ?? 0);

        if($public_conversations < 2) {
            continue;
        }

        $reason = '';
        if($negative_feedback > 0) {
            $reason = 'Javni AI već ima review signal, pa prvo treba doraditi jasnoću odgovora i sljedeći korak.';
        } elseif($public_conversations >= 3 && $leads === 0) {
            $reason = 'Razgovori postoje, ali još ne prelaze u lead. Fokus je na CTA-u i conversion putu.';
        } elseif($leads > 0 && $business_leads === 0) {
            $reason = 'Leadovi dolaze, ali još ne nose dovoljno jak business signal. Vrijedi dotjerati positioning i kvalifikaciju.';
        }

        if($reason === '') {
            continue;
        }

        $public_queue[] = [
            'user_id' => (int) ($user_row['user_id'] ?? 0),
            'name' => (string) ($user_row['name'] ?? l('global.unknown')),
            'detail_url' => (string) ($user_row['detail_url'] ?? ''),
            'coach_conversations' => $coach_conversations,
            'public_conversations' => $public_conversations,
            'leads' => $leads,
            'business_leads' => $business_leads,
            'negative_feedback' => $negative_feedback,
            'reason' => $reason,
        ];
    }

    usort($public_queue, static function(array $a, array $b) {
        return (($b['negative_feedback'] ?? 0) <=> ($a['negative_feedback'] ?? 0))
            ?: (($b['public_conversations'] ?? 0) <=> ($a['public_conversations'] ?? 0))
            ?: (($a['leads'] ?? 0) <=> ($b['leads'] ?? 0));
    });

    usort($suspicious_threads, static function(array $a, array $b) {
        return (((int) ($b['suspicion']['score'] ?? 0)) <=> ((int) ($a['suspicion']['score'] ?? 0)))
            ?: (((int) ($b['needs_review'] ?? 0)) <=> ((int) ($a['needs_review'] ?? 0)))
            ?: strcmp((string) ($b['activity_at'] ?? ''), (string) ($a['activity_at'] ?? ''));
    });

    $review_threads = array_map(static function(array $feedback_row): array {
        return [
            'owner_name' => (string) ($feedback_row['owner_name'] ?? l('global.unknown')),
            'detail_url' => (string) ($feedback_row['detail_url'] ?? ''),
            'assistant_label' => (string) ($feedback_row['assistant_label'] ?? 'AI'),
            'scope_label' => (string) ($feedback_row['scope_label'] ?? ''),
            'reason_label' => (string) ($feedback_row['reason_label'] ?? ''),
            'note' => (string) ($feedback_row['note'] ?? ''),
            'message_excerpt' => (string) ($feedback_row['message_excerpt'] ?? ''),
            'source_label' => (string) ($feedback_row['source_label'] ?? ''),
            'datetime' => (string) ($feedback_row['datetime'] ?? ''),
            'thread_preview' => $feedback_row['thread_preview'] ?? [],
        ];
    }, $recent_negative_feedback);

    $coach_top_topic = (string) ($coach_topic_rows[0]['label'] ?? '');
    $public_top_topic = (string) (($public_topic_rows[0]['label'] ?? '') ?: ($top_topics[0]['label'] ?? ''));
    $review_total = (int) ($team_payload['totals']['review_conversations'] ?? 0);
    $negative_feedback_total = (int) ($team_payload['totals']['negative_feedback'] ?? 0);
    $lead_total = (int) ($team_payload['totals']['leads'] ?? 0);
    $hot_lead_total = (int) ($team_payload['totals']['hot_leads'] ?? 0);

    if($review_total > 0) {
        $payload['admin_changes'][] = 'Prvo otvori AI review slučajeve jer se kvaliteta odgovora već javno lomi na stvarnim threadovima.';
    }

    if(!empty($suspicious_threads)) {
        $payload['admin_changes'][] = 'Pregledaj suspektne razgovore i provjeri traže li doradu compliance copyja, prompt zaštite ili jasnija pravila.';
    }

    if(!empty($coach_queue)) {
        $payload['admin_changes'][] = 'Za Coach prioritetne suradnike svedi pomoć na jedan jasan tjedni potez i provjeri jesu li ga stvarno odradili.';
    }

    if(!empty($public_queue)) {
        $payload['admin_changes'][] = 'Doradi CTA i conversion put na javnim AI aplikacijama gdje razgovori postoje, ali lead još ne dolazi ili je slab.';
    }

    if(!empty($rising_topics[0]['label'])) {
        $payload['admin_changes'][] = 'Tema "' . (string) $rising_topics[0]['label'] . '" trenutno raste i vrijedi je pretvoriti u sadržaj, FAQ ili webinar.';
    } elseif($public_top_topic !== '') {
        $payload['admin_changes'][] = 'Najviše javnog interesa sada ide prema temi "' . $public_top_topic . '", pa nju vrijedi prvu brusiti.';
    }

    if($hot_lead_total > 0) {
        $payload['admin_changes'][] = 'Postoje vrući AI leadovi, pa ih vrijedi odmah spojiti s mentorstvom i nastavkom follow-upa.';
    }

    $payload['coach']['summary'] = $coach_thread_total === 0
        ? 'Coach još nema dovoljno aktivnih threadova za team zaključak.'
        : (!empty($coach_queue)
            ? 'Coach se koristi, ali dio suradnika ostaje u petlji pomoći bez dovoljno izvedbe i stvarnog pomaka.'
            : 'Coach razgovori pokazuju uredan ritam pomoći bez jačeg signala zastoja.');
    $payload['coach']['blocker'] = !empty($coach_queue)
        ? 'Glavni team blocker je execution: savjet postoji, ali dio suradnika ne pretvara Coach u provedivu tjednu akciju.'
        : ($coach_top_topic !== '' ? 'Najčešća Coach tema je "' . $coach_top_topic . '".' : 'Još nema dominantnog Coach blockera.');
    $payload['coach']['next_admin_move'] = !empty($coach_queue)
        ? 'Otvori prioritetne Coach suradnike i svedi svaki slučaj na jedan sljedeći potez s rokom.'
        : 'Nastavi pratiti Coach teme i pretvarati ih u jasne tjedne zadatke.';
    $payload['coach']['top_topics'] = array_slice($coach_topic_rows, 0, 4);
    $payload['coach']['queue'] = array_slice($coach_queue, 0, $limit);

    $payload['public_ai']['summary'] = $public_thread_total === 0
        ? 'Javni AI još nema dovoljno razgovora za team zaključak.'
        : ($lead_total > 0
            ? 'Javni AI već donosi interes i leadove, ali na dijelu aplikacija i dalje postoji conversion gap ili review signal.'
            : 'Javni AI razgovori postoje, ali conversion i kvaliteta još nisu dovoljno stabilni na svim aplikacijama.');
    $payload['public_ai']['blocker'] = $negative_feedback_total > 0
        ? 'Glavni blocker je kvaliteta dijela odgovora i potreba za jačim sljedećim korakom.'
        : (!empty($public_queue)
            ? 'Glavni blocker je conversion: promet i pitanja postoje, ali lead i business signal još ne prate svugdje.'
            : ($public_top_topic !== '' ? 'Najjači javni interes sada ide prema temi "' . $public_top_topic . '".' : 'Još nema dominantnog blockera javnog AI-ja.'));
    $payload['public_ai']['next_admin_move'] = !empty($public_queue)
        ? 'Prvo otvori javne AI slučajeve s prometom bez leadova i dotjeraj CTA, ponudu i positioning.'
        : 'Zadrži najjaču temu i pretvori je u bolji FAQ, CTA i lead capture put.';
    $payload['public_ai']['top_topics'] = array_slice($public_top_topic !== '' ? $public_topic_rows : $top_topics, 0, 4);
    $payload['public_ai']['queue'] = array_slice($public_queue, 0, $limit);

    $payload['suspicious_threads'] = array_slice($suspicious_threads, 0, $limit);
    $payload['review_threads'] = array_slice($review_threads, 0, $limit);
    $payload['counts']['review_threads'] = count($review_threads);
    $payload['counts']['suspicious_threads'] = count($suspicious_threads);
    $payload['counts']['coach_priority'] = count($coach_queue);
    $payload['counts']['public_priority'] = count($public_queue);
    $payload['counts']['lead_threads'] = count($recent_hot_leads);
    $payload['inbox'] = [
        'tabs' => [
            [
                'key' => 'coach',
                'label' => $language === 'en' ? 'Coach' : 'Coach',
                'count' => min(count($coach_threads), $limit),
            ],
            [
                'key' => 'public_ai',
                'label' => $language === 'en' ? 'Public AI' : 'AI za ljude',
                'count' => min(count($public_threads), $limit),
            ],
            [
                'key' => 'suspicious',
                'label' => $language === 'en' ? 'Suspicious' : 'Suspektni',
                'count' => min(count($suspicious_threads), $limit),
            ],
            [
                'key' => 'review',
                'label' => $language === 'en' ? 'Review' : 'Review',
                'count' => min(count($review_threads), $limit),
            ],
            [
                'key' => 'leads',
                'label' => $language === 'en' ? 'Lead / conversion' : 'Lead / conversion',
                'count' => min(count($recent_hot_leads), $limit),
            ],
        ],
        'coach_threads' => array_slice($coach_threads, 0, $limit),
        'public_threads' => array_slice($public_threads, 0, $limit),
        'suspicious_threads' => array_slice($suspicious_threads, 0, $limit),
        'review_threads' => array_slice($review_threads, 0, $limit),
        'lead_threads' => array_slice($recent_hot_leads, 0, $limit),
    ];

    $payload['headline'] = $review_total > 0 && !empty($suspicious_threads)
        ? 'AI promet raste, ali prva admin intervencija su quality i suspektni threadovi.'
        : (!empty($public_queue) && $lead_total === 0
            ? 'Interes postoji, ali javni AI još propušta conversion i traži oštriji put do leada.'
            : (!empty($coach_queue)
                ? 'Coach je aktivan, ali dio suradnika još vrti pomoć bez jasnog execution pomaka.'
                : ($lead_total > 0
                    ? 'AI već daje rezultat, a sada ga treba održati kroz kvalitetu, CTA i mentorsko preuzimanje.'
                    : 'AI chatovi daju jasan timski signal gdje treba otvoriti razgovore i što prvo promijeniti.')));

    $summary_parts = [];
    if($coach_thread_total > 0) {
        $summary_parts[] = 'Coach threadovi ' . nr($coach_thread_total) . ($coach_top_topic !== '' ? ' · top tema "' . $coach_top_topic . '"' : '');
    }
    if($public_thread_total > 0) {
        $summary_parts[] = 'Javni AI threadovi ' . nr($public_thread_total) . ($public_top_topic !== '' ? ' · top tema "' . $public_top_topic . '"' : '');
    }
    if($lead_total > 0) {
        $summary_parts[] = 'AI leadovi ' . nr($lead_total) . ' · vrući ' . nr($hot_lead_total);
    }
    if($review_total > 0) {
        $summary_parts[] = 'Review slučajevi ' . nr($review_total);
    }
    if(!empty($suspicious_threads)) {
        $summary_parts[] = 'Suspektni threadovi ' . nr(count($suspicious_threads));
    }

    $payload['executive_summary'] = !empty($summary_parts)
        ? implode(' · ', $summary_parts) . '.'
        : 'Još nema dovoljno AI signala za pouzdan team summary.';
    $payload['admin_changes'] = array_values(array_slice(array_unique(array_filter($payload['admin_changes'])), 0, 6));

    return $payload;
}

function fcc_ai_build_team_executive_report_payload(array $team_payload, array $queue_rows = [], string $language = 'hr', int $limit = 5): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(3, min(8, $limit));
    $control_tower = (array) ($team_payload['control_tower'] ?? []);
    $mentor_rows = array_values(array_filter($queue_rows, static function($row) {
        return !empty($row['ai_mentor_stage_label']);
    }));
    $blocked_rows = array_values(array_filter($mentor_rows, static function($row) {
        return (string) ($row['ai_mentor_stage_key'] ?? '') === 'blocked_setup';
    }));
    $top_rows = array_values(array_filter($mentor_rows, static function($row) {
        return (string) ($row['ai_mentor_stage_key'] ?? '') === 'top_momentum';
    }));
    $serious_rows = array_values(array_filter($mentor_rows, static function($row) {
        return (string) ($row['ai_mentor_stage_key'] ?? '') === 'serious_focus';
    }));
    $scattered_rows = array_values(array_filter($mentor_rows, static function($row) {
        return (string) ($row['ai_mentor_stage_key'] ?? '') === 'scattered_focus';
    }));

    $payload = [
        'headline' => (string) ($control_tower['headline'] ?? ''),
        'summary' => (string) ($control_tower['executive_summary'] ?? ''),
        'alerts' => [],
        'opportunities' => [],
        'focus_users' => [],
        'next_moves' => array_values(array_slice((array) ($control_tower['admin_changes'] ?? []), 0, $limit)),
    ];

    if((int) ($control_tower['counts']['review_threads'] ?? 0) > 0) {
        $payload['alerts'][] = [
            'severity_class' => 'status-danger',
            'severity_label' => 'Hitno',
            'title' => 'Review queue već pokazuje gdje kvaliteta puca',
            'text' => 'Postoji ' . nr((int) ($control_tower['counts']['review_threads'] ?? 0)) . ' review slučajeva koje vrijedi otvoriti prije daljnjeg scalea AI-ja.',
        ];
    }

    if((int) ($control_tower['counts']['suspicious_threads'] ?? 0) > 0) {
        $payload['alerts'][] = [
            'severity_class' => 'status-warning',
            'severity_label' => 'Rizik',
            'title' => 'Suspektni threadovi traže compliance pregled',
            'text' => 'Trenutno imaš ' . nr((int) ($control_tower['counts']['suspicious_threads'] ?? 0)) . ' threadova sa sumnjivim ili osjetljivim signalom koje vrijedi pregledati.',
        ];
    }

    if(!empty($blocked_rows)) {
        $payload['alerts'][] = [
            'severity_class' => 'status-warning',
            'severity_label' => 'Setup',
            'title' => 'Dio tima još je blokiran osnovnim setupom',
            'text' => nr(count($blocked_rows)) . ' suradnika još nema valjan prodajni put ili im je setup blokiran, pa im scale trenutno nema smisla.',
        ];
    }

    if((int) ($control_tower['counts']['public_priority'] ?? 0) > 0) {
        $payload['alerts'][] = [
            'severity_class' => 'status-info',
            'severity_label' => 'Conversion',
            'title' => 'Javni AI ima promet, ali conversion još curi',
            'text' => 'Na ' . nr((int) ($control_tower['counts']['public_priority'] ?? 0)) . ' slučajeva treba doraditi CTA, lead capture ili positioning.',
        ];
    }

    if(!empty($team_payload['rising_topics'][0]['label'])) {
        $payload['opportunities'][] = [
            'severity_class' => 'status-info',
            'severity_label' => 'Tema',
            'title' => 'Tema "' . (string) ($team_payload['rising_topics'][0]['label'] ?? '') . '" sada ubrzano raste',
            'text' => 'To je najčišći kandidat za novi webinar, FAQ ili doradu AI skripte dok interes još raste.',
        ];
    }

    if(!empty($top_rows)) {
        $payload['opportunities'][] = [
            'severity_class' => 'status-success',
            'severity_label' => 'Sponsor',
            'title' => 'Tim već ima ljude spremne za jači sponsor positioning',
            'text' => nr(count($top_rows)) . ' suradnika drži top momentum i vrijedi ih jače isticati kroz sponsor vidljivost i primjer rada.',
        ];
    }

    if((int) ($team_payload['totals']['hot_leads'] ?? 0) > 0) {
        $payload['opportunities'][] = [
            'severity_class' => 'status-success',
            'severity_label' => 'Lead',
            'title' => 'AI već donosi vruće leadove',
            'text' => 'Imaš ' . nr((int) ($team_payload['totals']['hot_leads'] ?? 0)) . ' vrućih leadova koje vrijedi brzo spojiti s mentorstvom i follow-upom.',
        ];
    }

    $focus_users = [];
    if(!empty($blocked_rows[0])) {
        $focus_users[] = [
            'name' => (string) ($blocked_rows[0]['name'] ?? ''),
            'detail_url' => (string) ($blocked_rows[0]['detail_url'] ?? ''),
            'label' => (string) (($blocked_rows[0]['ai_mentor_stage_label'] ?? '') ?: 'Blokiran setupom'),
            'reason' => (string) (($blocked_rows[0]['ai_mentor_admin_action'] ?? '') ?: 'Prvo riješi setup i prodajni put.'),
        ];
    }
    if(!empty($control_tower['coach']['queue'][0])) {
        $focus_users[] = [
            'name' => (string) ($control_tower['coach']['queue'][0]['name'] ?? ''),
            'detail_url' => (string) ($control_tower['coach']['queue'][0]['detail_url'] ?? ''),
            'label' => 'Coach prioritet',
            'reason' => (string) ($control_tower['coach']['queue'][0]['reason'] ?? ''),
        ];
    }
    if(!empty($control_tower['public_ai']['queue'][0])) {
        $focus_users[] = [
            'name' => (string) ($control_tower['public_ai']['queue'][0]['name'] ?? ''),
            'detail_url' => (string) ($control_tower['public_ai']['queue'][0]['detail_url'] ?? ''),
            'label' => 'Public prioritet',
            'reason' => (string) ($control_tower['public_ai']['queue'][0]['reason'] ?? ''),
        ];
    }
    if(!empty($top_rows[0])) {
        $focus_users[] = [
            'name' => (string) ($top_rows[0]['name'] ?? ''),
            'detail_url' => (string) ($top_rows[0]['detail_url'] ?? ''),
            'label' => (string) (($top_rows[0]['ai_mentor_stage_label'] ?? '') ?: 'Preporučeni sponzor'),
            'reason' => (string) (($top_rows[0]['ai_mentor_admin_action'] ?? '') ?: 'Vrijedi ga gurati kao dokaz rezultata i mentor primjer.'),
        ];
    } elseif(!empty($serious_rows[0])) {
        $focus_users[] = [
            'name' => (string) ($serious_rows[0]['name'] ?? ''),
            'detail_url' => (string) ($serious_rows[0]['detail_url'] ?? ''),
            'label' => (string) (($serious_rows[0]['ai_mentor_stage_label'] ?? '') ?: 'Ozbiljan i fokusiran'),
            'reason' => (string) (($serious_rows[0]['ai_mentor_admin_action'] ?? '') ?: 'Vrijedi ga zadržati u ritmu i pratiti scale.'),
        ];
    } elseif(!empty($scattered_rows[0])) {
        $focus_users[] = [
            'name' => (string) ($scattered_rows[0]['name'] ?? ''),
            'detail_url' => (string) ($scattered_rows[0]['detail_url'] ?? ''),
            'label' => (string) (($scattered_rows[0]['ai_mentor_stage_label'] ?? '') ?: 'Raspršen fokus'),
            'reason' => (string) (($scattered_rows[0]['ai_mentor_admin_action'] ?? '') ?: 'Treba cleanup i jači fokus na jednu glavnu aplikaciju.'),
        ];
    }

    $seen_focus_users = [];
    $payload['focus_users'] = array_values(array_filter(array_map(static function(array $row) use (&$seen_focus_users) {
        $name_key = trim((string) ($row['name'] ?? ''));
        if($name_key === '' || isset($seen_focus_users[$name_key])) {
            return null;
        }
        $seen_focus_users[$name_key] = true;
        return $row;
    }, $focus_users)));

    if(trim((string) $payload['headline']) === '') {
        $payload['headline'] = !empty($payload['alerts'][0]['title'])
            ? (string) $payload['alerts'][0]['title']
            : 'AI executive report još čeka jači signal.';
    }

    if(trim((string) $payload['summary']) === '') {
        $parts = [];
        if(!empty($payload['alerts'])) {
            $parts[] = 'Najveći rizik sada je "' . (string) ($payload['alerts'][0]['title'] ?? '') . '".';
        }
        if(!empty($payload['opportunities'])) {
            $parts[] = 'Najveća prilika je "' . (string) ($payload['opportunities'][0]['title'] ?? '') . '".';
        }
        $payload['summary'] = !empty($parts) ? implode(' ', $parts) : 'Još nema dovoljno signala za team executive report.';
    }

    $payload['alerts'] = array_values(array_slice($payload['alerts'], 0, $limit));
    $payload['opportunities'] = array_values(array_slice($payload['opportunities'], 0, $limit));
    $payload['focus_users'] = array_values(array_slice($payload['focus_users'], 0, min(4, $limit)));
    $payload['next_moves'] = array_values(array_slice($payload['next_moves'], 0, $limit));

    return $payload;
}

function fcc_ai_build_user_executive_report_payload(array $dossier, string $language = 'hr', int $limit = 5): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(3, min(8, $limit));

    $payload = [
        'headline' => (string) ($dossier['headline'] ?? ''),
        'summary' => (string) ($dossier['executive_summary'] ?? ''),
        'alerts' => [],
        'opportunities' => [],
        'next_moves' => array_values(array_slice((array) ($dossier['admin_changes'] ?? []), 0, $limit)),
        'working' => array_values(array_slice((array) ($dossier['strengths'] ?? []), 0, 3)),
        'blocking' => array_values(array_slice((array) ($dossier['weaknesses'] ?? []), 0, 3)),
    ];

    $review_total = count((array) ($dossier['review_threads'] ?? []));
    $suspicious_total = count((array) ($dossier['suspicious_threads'] ?? []));
    $public_threads_total = count((array) ($dossier['public_ai']['threads'] ?? []));
    $coach_threads_total = count((array) ($dossier['coach']['threads'] ?? []));
    $public_top_topic = (string) ($dossier['public_ai']['top_topics'][0]['label'] ?? '');
    $coach_top_topic = (string) ($dossier['coach']['top_topics'][0]['label'] ?? '');

    if($review_total > 0) {
        $payload['alerts'][] = [
            'severity_class' => 'status-danger',
            'severity_label' => 'Review',
            'title' => 'Dio javnih odgovora traži ručni pregled',
            'text' => 'Otvoreno je ' . nr($review_total) . ' review slučajeva i to je prvi signal koji treba zatvoriti prije daljnjeg scalea ovog profila.',
        ];
    }

    if($suspicious_total > 0) {
        $payload['alerts'][] = [
            'severity_class' => 'status-warning',
            'severity_label' => 'Rizik',
            'title' => 'Postoje suspektni ili osjetljivi chatovi',
            'text' => 'Trenutno ima ' . nr($suspicious_total) . ' threadova koji traže dodatni compliance ili prompt pregled.',
        ];
    }

    if($coach_threads_total >= 3 && empty($dossier['strengths'])) {
        $payload['alerts'][] = [
            'severity_class' => 'status-warning',
            'severity_label' => 'Coach',
            'title' => 'Coach aktivnost još nema dovoljno jasan rezultat',
            'text' => 'Suradnik traži pomoć, ali još nema dovoljno signala da se to pretvara u izvedbu i napredak.',
        ];
    }

    if(!empty($dossier['strengths'][0])) {
        $payload['opportunities'][] = [
            'severity_class' => 'status-success',
            'severity_label' => 'Radi',
            'title' => 'Postoji jasan signal što već funkcionira',
            'text' => (string) ($dossier['strengths'][0] ?? ''),
        ];
    }

    if($public_top_topic !== '') {
        $payload['opportunities'][] = [
            'severity_class' => 'status-info',
            'severity_label' => 'Tema',
            'title' => 'Publika najviše reagira na temu "' . $public_top_topic . '"',
            'text' => 'To je tema koju vrijedi prvu pretvoriti u jači CTA, FAQ ili sadržajni fokus.',
        ];
    }

    if($coach_top_topic !== '') {
        $payload['opportunities'][] = [
            'severity_class' => 'status-info',
            'severity_label' => 'Coach',
            'title' => 'Coach se najviše vrti oko teme "' . $coach_top_topic . '"',
            'text' => 'Vrijedi srezati tu temu na jedan konkretan tjedni potez koji suradnik mora odraditi.',
        ];
    }

    if(trim((string) $payload['headline']) === '') {
        $payload['headline'] = !empty($payload['alerts'][0]['title'])
            ? (string) ($payload['alerts'][0]['title'] ?? '')
            : 'AI executive report za ovog suradnika još čeka jači signal.';
    }

    if(trim((string) $payload['summary']) === '') {
        $summary_parts = [];
        if(!empty($payload['alerts'][0]['title'])) {
            $summary_parts[] = 'Najveći rizik je "' . (string) ($payload['alerts'][0]['title'] ?? '') . '".';
        }
        if(!empty($payload['opportunities'][0]['title'])) {
            $summary_parts[] = 'Najveća prilika je "' . (string) ($payload['opportunities'][0]['title'] ?? '') . '".';
        }
        $payload['summary'] = !empty($summary_parts) ? implode(' ', $summary_parts) : 'Još nema dovoljno signala za dublji executive report ovog suradnika.';
    }

    $payload['alerts'] = array_values(array_slice($payload['alerts'], 0, $limit));
    $payload['opportunities'] = array_values(array_slice($payload['opportunities'], 0, $limit));
    $payload['next_moves'] = array_values(array_slice($payload['next_moves'], 0, $limit));

    return $payload;
}

function fcc_ai_build_user_useful_items(array $dashboard_payload, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $items = [];
    $top_topic = $dashboard_payload['top_topics'][0]['label'] ?? '';

    if((int) ($dashboard_payload['totals']['review_conversations'] ?? 0) > 0) {
        $items[] = [
            'title' => $language === 'en' ? 'Review the bad-answer signals' : 'Provjeri loše odgovore',
            'text' => $language === 'en'
                ? 'Open the review queue first because users already marked some answers as unclear or not useful.'
                : 'Prvo otvori red za provjeru jer su korisnici već označili dio odgovora kao nejasan ili nekoristan.',
            'url' => url('fcc-ai#fcc-ai-review'),
        ];
    }

    if((int) ($dashboard_payload['totals']['leads'] ?? 0) > 0) {
        $items[] = [
            'title' => $language === 'en' ? 'Continue the AI leads' : 'Nastavi AI leadove',
            'text' => $language === 'en'
                ? 'You already have AI leads, so the most useful next move is to open contacts and continue the follow-up.'
                : 'AI je već doveo leadove, pa je najkorisnije odmah otvoriti kontakte i nastaviti follow-up.',
            'url' => url('data'),
        ];
    }

    if($top_topic !== '') {
        $items[] = [
            'title' => $language === 'en' ? 'Refine what repeats most' : 'Doradi ono što se najviše ponavlja',
            'text' => $language === 'en'
                ? 'The topic "' . $top_topic . '" appears most often, so adjust the tone, persona, or rules around that theme.'
                : 'Tema "' . $top_topic . '" pojavljuje se najčešće, pa doradi ton, osobnost ili pravila baš oko te teme.',
            'url' => url('fcc-ai#fcc-ai-assistants'),
        ];
    }

    if((int) ($dashboard_payload['totals']['conversations'] ?? 0) === 0) {
        $items[] = [
            'title' => $language === 'en' ? 'Activate AI on the app' : 'Aktiviraj AI na aplikaciji',
            'text' => $language === 'en'
                ? 'If there are still no conversations, the next step is to add the AI block to the FCC App and test the full flow.'
                : 'Ako još nema razgovora, sljedeći korak je dodati AI blok na FCC aplikaciju i testirati cijeli tok.',
            'url' => url('links'),
        ];
    }

    return array_slice($items, 0, 4);
}

function fcc_ai_get_team_dashboard_payload(string $period_start_datetime, array $allowed_user_ids = [], int $limit = 6, string $language = 'hr', string $detail_period = '30d'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(1, min(12, $limit));

    $payload = [
        'is_available' => false,
        'period_start_datetime' => $period_start_datetime,
        'totals' => [
            'conversations' => 0,
            'coach_conversations' => 0,
            'public_conversations' => 0,
            'user_messages' => 0,
            'assistant_messages' => 0,
            'messages' => 0,
            'leads' => 0,
            'business_leads' => 0,
            'hot_leads' => 0,
            'active_users' => 0,
            'positive_feedback' => 0,
            'negative_feedback' => 0,
            'review_conversations' => 0,
        ],
        'assistant_breakdown' => [],
        'scope_breakdown' => [],
        'top_users' => [],
        'recent_hot_leads' => [],
        'top_topics' => [],
        'recent_negative_feedback' => [],
        'rising_topics' => [],
        'webinar_candidates' => [],
        'help_watchlist' => [],
        'assistant_performance' => [],
        'useful_items' => [],
        'recent_threads' => [],
        'control_tower' => [],
    ];

    if(!fcc_ai_tables_ready()) {
        return $payload;
    }

    $payload['is_available'] = true;
    $period_start_datetime = trim($period_start_datetime) !== '' ? trim($period_start_datetime) : date('Y-m-d 00:00:00', strtotime('-30 days'));
    $period_start_sql = db()->escape($period_start_datetime);
    $allowed_user_ids = array_values(array_unique(array_filter(array_map('intval', $allowed_user_ids), static function($user_id) {
        return $user_id > 0;
    })));
    $user_sql = $allowed_user_ids ? implode(',', $allowed_user_ids) : '';
    $conversation_user_filter = $user_sql !== '' ? " AND `c`.`user_id` IN ({$user_sql})" : '';
    $lead_user_filter = $user_sql !== '' ? " AND `l`.`user_id` IN ({$user_sql})" : '';
    $feedback_user_filter = $user_sql !== '' ? " AND `f`.`user_id` IN ({$user_sql})" : '';
    $insight_user_filter = $user_sql !== '' ? " AND `user_id` IN ({$user_sql})" : '';

    $assistant_breakdown = [];
    foreach(fcc_ai_get_assistant_types() as $assistant_type => $definition) {
        $assistant_breakdown[$assistant_type] = [
            'assistant_type' => $assistant_type,
            'label' => (string) ($definition['label'] ?? $assistant_type),
            'conversations' => 0,
            'messages' => 0,
            'leads' => 0,
            'business_leads' => 0,
            'positive_feedback' => 0,
            'negative_feedback' => 0,
            'active_users_map' => [],
        ];
    }

    $scope_breakdown = [];
    $user_totals = [];

    $conversation_result = database()->query("SELECT
            `c`.`user_id`,
            `u`.`name`,
            `c`.`assistant_type`,
            `c`.`scope`,
            COUNT(*) AS `conversations`,
            SUM(`c`.`total_user_messages`) AS `user_messages`,
            SUM(`c`.`total_assistant_messages`) AS `assistant_messages`,
            MAX(COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`)) AS `last_message_at`
        FROM `fcc_ai_conversations` AS `c`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `c`.`user_id`
        WHERE COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`) >= '{$period_start_sql}'{$conversation_user_filter}
        GROUP BY `c`.`user_id`, `u`.`name`, `c`.`assistant_type`, `c`.`scope`");

    while($row = $conversation_result->fetch_assoc()) {
        $user_id = (int) ($row['user_id'] ?? 0);
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $scope = (string) ($row['scope'] ?? 'public_app');
        $conversation_total = (int) ($row['conversations'] ?? 0);
        $user_messages = (int) ($row['user_messages'] ?? 0);
        $assistant_messages = (int) ($row['assistant_messages'] ?? 0);
        $message_total = $user_messages + $assistant_messages;
        $assistant_definition = $assistant_type !== '' ? fcc_ai_get_assistant_type($assistant_type) : null;

        if(!isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type] = [
                'assistant_type' => $assistant_type,
                'label' => (string) ($assistant_definition['label'] ?? ($assistant_type !== '' ? $assistant_type : 'AI')),
                'conversations' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'active_users_map' => [],
            ];
        }

        $assistant_breakdown[$assistant_type]['conversations'] += $conversation_total;
        $assistant_breakdown[$assistant_type]['messages'] += $message_total;
        $assistant_breakdown[$assistant_type]['active_users_map'][$user_id] = true;

        if(!isset($scope_breakdown[$scope])) {
            $scope_breakdown[$scope] = [
                'scope' => $scope,
                'label' => fcc_ai_get_scope_label($scope, $language),
                'conversations' => 0,
                'messages' => 0,
            ];
        }

        $scope_breakdown[$scope]['conversations'] += $conversation_total;
        $scope_breakdown[$scope]['messages'] += $message_total;

        if(!isset($user_totals[$user_id])) {
            $user_totals[$user_id] = [
                'user_id' => $user_id,
                'name' => (string) ($row['name'] ?? l('global.unknown')),
                'detail_url' => url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)),
                'conversations' => 0,
                'coach_conversations' => 0,
                'public_conversations' => 0,
                'user_messages' => 0,
                'assistant_messages' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'last_message_at' => '',
            ];
        }

        $user_totals[$user_id]['conversations'] += $conversation_total;
        $user_totals[$user_id]['user_messages'] += $user_messages;
        $user_totals[$user_id]['assistant_messages'] += $assistant_messages;
        $user_totals[$user_id]['messages'] += $message_total;
        $user_totals[$user_id][$scope === 'internal_coach' ? 'coach_conversations' : 'public_conversations'] += $conversation_total;

        if((string) ($row['last_message_at'] ?? '') > (string) ($user_totals[$user_id]['last_message_at'] ?? '')) {
            $user_totals[$user_id]['last_message_at'] = (string) ($row['last_message_at'] ?? '');
        }

        $payload['totals']['conversations'] += $conversation_total;
        $payload['totals']['user_messages'] += $user_messages;
        $payload['totals']['assistant_messages'] += $assistant_messages;
        $payload['totals']['messages'] += $message_total;
        $payload['totals'][$scope === 'internal_coach' ? 'coach_conversations' : 'public_conversations'] += $conversation_total;
    }

    $lead_result = database()->query("SELECT
            `l`.`user_id`,
            `u`.`name`,
            `l`.`assistant_type`,
            `l`.`lead_type`,
            COUNT(*) AS `leads`,
            SUM(CASE WHEN `l`.`lead_score` >= 75 THEN 1 ELSE 0 END) AS `hot_leads`
        FROM `fcc_ai_leads` AS `l`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `l`.`user_id`
        WHERE `l`.`datetime` >= '{$period_start_sql}'{$lead_user_filter}
        GROUP BY `l`.`user_id`, `u`.`name`, `l`.`assistant_type`, `l`.`lead_type`");

    while($row = $lead_result->fetch_assoc()) {
        $user_id = (int) ($row['user_id'] ?? 0);
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $lead_type = (string) ($row['lead_type'] ?? '');
        $lead_total = (int) ($row['leads'] ?? 0);
        $hot_leads = (int) ($row['hot_leads'] ?? 0);
        $business_leads = in_array($lead_type, ['business_interest', 'mixed_interest'], true) ? $lead_total : 0;
        $assistant_definition = $assistant_type !== '' ? fcc_ai_get_assistant_type($assistant_type) : null;

        if(!isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type] = [
                'assistant_type' => $assistant_type,
                'label' => (string) ($assistant_definition['label'] ?? ($assistant_type !== '' ? $assistant_type : 'AI')),
                'conversations' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'active_users_map' => [],
            ];
        }

        $assistant_breakdown[$assistant_type]['leads'] += $lead_total;
        $assistant_breakdown[$assistant_type]['business_leads'] += $business_leads;
        $assistant_breakdown[$assistant_type]['active_users_map'][$user_id] = true;

        if(!isset($user_totals[$user_id])) {
            $user_totals[$user_id] = [
                'user_id' => $user_id,
                'name' => (string) ($row['name'] ?? l('global.unknown')),
                'detail_url' => url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)),
                'conversations' => 0,
                'coach_conversations' => 0,
                'public_conversations' => 0,
                'user_messages' => 0,
                'assistant_messages' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'last_message_at' => '',
            ];
        }

        $user_totals[$user_id]['leads'] += $lead_total;
        $user_totals[$user_id]['business_leads'] += $business_leads;
        $payload['totals']['leads'] += $lead_total;
        $payload['totals']['business_leads'] += $business_leads;
        $payload['totals']['hot_leads'] += $hot_leads;
    }

    $feedback_result = database()->query("SELECT
            `f`.`user_id`,
            `u`.`name`,
            `f`.`assistant_type`,
            SUM(CASE WHEN `f`.`feedback_type` = 'up' THEN 1 ELSE 0 END) AS `positive_feedback`,
            SUM(CASE WHEN `f`.`feedback_type` = 'down' AND COALESCE(`f`.`status`, 'new') != 'resolved' THEN 1 ELSE 0 END) AS `negative_feedback`
        FROM `fcc_ai_message_feedback` AS `f`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `f`.`user_id`
        WHERE COALESCE(`f`.`last_datetime`, `f`.`datetime`) >= '{$period_start_sql}'{$feedback_user_filter}
          AND " . fcc_ai_get_feedback_visibility_sql('f') . "
        GROUP BY `f`.`user_id`, `u`.`name`, `f`.`assistant_type`");

    while($feedback_result && $row = $feedback_result->fetch_assoc()) {
        $user_id = (int) ($row['user_id'] ?? 0);
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $positive_feedback = (int) ($row['positive_feedback'] ?? 0);
        $negative_feedback = (int) ($row['negative_feedback'] ?? 0);
        $assistant_definition = $assistant_type !== '' ? fcc_ai_get_assistant_type($assistant_type) : null;

        if(!isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type] = [
                'assistant_type' => $assistant_type,
                'label' => (string) ($assistant_definition['label'] ?? ($assistant_type !== '' ? $assistant_type : 'AI')),
                'conversations' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'active_users_map' => [],
            ];
        }

        $assistant_breakdown[$assistant_type]['positive_feedback'] += $positive_feedback;
        $assistant_breakdown[$assistant_type]['negative_feedback'] += $negative_feedback;

        if(!isset($user_totals[$user_id])) {
            $user_totals[$user_id] = [
                'user_id' => $user_id,
                'name' => (string) ($row['name'] ?? l('global.unknown')),
                'detail_url' => url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)),
                'conversations' => 0,
                'coach_conversations' => 0,
                'public_conversations' => 0,
                'user_messages' => 0,
                'assistant_messages' => 0,
                'messages' => 0,
                'leads' => 0,
                'business_leads' => 0,
                'positive_feedback' => 0,
                'negative_feedback' => 0,
                'last_message_at' => '',
            ];
        }

        $user_totals[$user_id]['positive_feedback'] += $positive_feedback;
        $user_totals[$user_id]['negative_feedback'] += $negative_feedback;
        $payload['totals']['positive_feedback'] += $positive_feedback;
        $payload['totals']['negative_feedback'] += $negative_feedback;
    }

    if(fcc_ai_tables_ready()) {
        $topics_result = database()->query("SELECT
                `primary_topic`,
                `primary_topic_label`,
                COUNT(*) AS `total`
            FROM `fcc_ai_conversation_insights`
            WHERE COALESCE(`last_datetime`, `datetime`) >= '{$period_start_sql}'{$insight_user_filter}
              AND `primary_topic` IS NOT NULL
              AND `primary_topic` != ''
            GROUP BY `primary_topic`, `primary_topic_label`
            ORDER BY `total` DESC, `primary_topic_label` ASC
            LIMIT {$limit}");

        while($topics_result && $row = $topics_result->fetch_assoc()) {
            $payload['top_topics'][] = [
                'key' => (string) ($row['primary_topic'] ?? ''),
                'label' => (string) (($row['primary_topic_label'] ?? '') ?: ($row['primary_topic'] ?? '')),
                'total' => (int) ($row['total'] ?? 0),
            ];
        }

        $review_conversations_result = database()->query("SELECT COUNT(DISTINCT `f`.`fcc_ai_conversation_id`) AS `total`
            FROM `fcc_ai_message_feedback` AS `f`
            WHERE `f`.`feedback_type` = 'down'
              AND COALESCE(`f`.`status`, 'new') != 'resolved'
              AND " . fcc_ai_get_feedback_visibility_sql('f') . "
              AND COALESCE(`f`.`last_datetime`, `f`.`datetime`) >= '{$period_start_sql}'{$feedback_user_filter}");

        if($review_conversations_result && $review_row = $review_conversations_result->fetch_assoc()) {
            $payload['totals']['review_conversations'] = (int) ($review_row['total'] ?? 0);
        }
    }

    foreach($assistant_breakdown as $assistant_type => $row) {
        $assistant_breakdown[$assistant_type]['active_users'] = count($row['active_users_map'] ?? []);
        unset($assistant_breakdown[$assistant_type]['active_users_map']);
    }

    $payload['assistant_breakdown'] = array_values($assistant_breakdown);
    usort($payload['assistant_breakdown'], static function(array $a, array $b) {
        return (($b['conversations'] ?? 0) <=> ($a['conversations'] ?? 0))
            ?: (($b['messages'] ?? 0) <=> ($a['messages'] ?? 0))
            ?: strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
    });

    $payload['scope_breakdown'] = array_values($scope_breakdown);
    usort($payload['scope_breakdown'], static function(array $a, array $b) {
        return (($b['conversations'] ?? 0) <=> ($a['conversations'] ?? 0))
            ?: strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
    });

    $payload['totals']['active_users'] = count(array_filter($user_totals, static function(array $row) {
        return (int) ($row['conversations'] ?? 0) > 0 || (int) ($row['leads'] ?? 0) > 0;
    }));

    $top_users = array_values($user_totals);
    usort($top_users, static function(array $a, array $b) {
        return (($b['conversations'] ?? 0) <=> ($a['conversations'] ?? 0))
            ?: (($b['leads'] ?? 0) <=> ($a['leads'] ?? 0))
            ?: (($b['messages'] ?? 0) <=> ($a['messages'] ?? 0))
            ?: strcmp((string) ($b['last_message_at'] ?? ''), (string) ($a['last_message_at'] ?? ''));
    });
    $payload['top_users'] = array_slice($top_users, 0, $limit);

    $recent_hot_leads_result = database()->query("SELECT
            `l`.`user_id`,
            `u`.`name` AS `owner_name`,
            `l`.`assistant_type`,
            `l`.`lead_type`,
            `l`.`lead_score`,
            `l`.`name`,
            `l`.`email`,
            `l`.`phone`,
            `l`.`preferred_contact_channel`,
            `l`.`datetime`,
            `c`.`scope`
        FROM `fcc_ai_leads` AS `l`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `l`.`user_id`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `l`.`fcc_ai_conversation_id`
        WHERE `l`.`datetime` >= '{$period_start_sql}'{$lead_user_filter}
        ORDER BY `l`.`lead_score` DESC, `l`.`datetime` DESC
        LIMIT {$limit}");

    while($row = $recent_hot_leads_result->fetch_assoc()) {
        $user_id = (int) ($row['user_id'] ?? 0);
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $payload['recent_hot_leads'][] = [
            'owner_name' => (string) ($row['owner_name'] ?? l('global.unknown')),
            'detail_url' => $user_id > 0 ? url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)) . '#leader-os-ai-chats' : '',
            'assistant_label' => fcc_ai_get_assistant_label($assistant_type),
            'lead_type_label' => fcc_ai_get_lead_type_label((string) ($row['lead_type'] ?? ''), $language),
            'lead_score' => (int) ($row['lead_score'] ?? 0),
            'contact_name' => trim((string) ($row['name'] ?? '')),
            'contact_value' => trim((string) (($row['email'] ?? '') ?: ($row['phone'] ?? ''))),
            'preferred_contact_channel' => trim((string) ($row['preferred_contact_channel'] ?? '')),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'datetime' => (string) ($row['datetime'] ?? ''),
        ];
    }

    $recent_negative_feedback_result = database()->query("SELECT
            `f`.`fcc_ai_message_feedback_id`,
            `f`.`fcc_ai_conversation_id`,
            `f`.`fcc_ai_message_id`,
            `f`.`user_id`,
            `u`.`name` AS `owner_name`,
            `f`.`assistant_type`,
            `f`.`reason`,
            `f`.`note`,
            `f`.`feedback_type`,
            `f`.`datetime`,
            `c`.`public_id`,
            `c`.`scope`,
            `c`.`link_id`,
            `c`.`blog_post_id`,
            `c`.`meta` AS `conversation_meta`,
            `m`.`content` AS `message_content`
        FROM `fcc_ai_message_feedback` AS `f`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `f`.`fcc_ai_conversation_id`
        LEFT JOIN `fcc_ai_messages` AS `m` ON `m`.`fcc_ai_message_id` = `f`.`fcc_ai_message_id`
        LEFT JOIN `users` AS `u` ON `u`.`user_id` = `f`.`user_id`
        WHERE `f`.`feedback_type` = 'down'
          AND COALESCE(`f`.`status`, 'new') != 'resolved'
          AND " . fcc_ai_get_feedback_visibility_sql('f') . "
          AND COALESCE(`f`.`last_datetime`, `f`.`datetime`) >= '{$period_start_sql}'{$feedback_user_filter}
        ORDER BY COALESCE(`f`.`last_datetime`, `f`.`datetime`) DESC
        LIMIT {$limit}");

    while($recent_negative_feedback_result && $row = $recent_negative_feedback_result->fetch_assoc()) {
        $user_id = (int) ($row['user_id'] ?? 0);
        $conversation_id = (int) ($row['fcc_ai_conversation_id'] ?? 0);
        $conversation_meta = json_decode((string) ($row['conversation_meta'] ?? '{}'), true) ?: [];
        $thread_preview = $conversation_id > 0 ? array_slice(fcc_ai_get_conversation_messages($conversation_id, 12), -8) : [];
        $payload['recent_negative_feedback'][] = [
            'feedback_id' => (int) ($row['fcc_ai_message_feedback_id'] ?? 0),
            'conversation_id' => $conversation_id,
            'conversation_public_id' => (string) ($row['public_id'] ?? ''),
            'owner_name' => (string) ($row['owner_name'] ?? l('global.unknown')),
            'user_id' => $user_id,
            'detail_url' => $user_id > 0 ? url('admin/leader-operating-system-leader?user_id=' . $user_id . '&period=' . urlencode($detail_period)) . '#leader-os-ai-chats' : '',
            'assistant_type' => (string) ($row['assistant_type'] ?? ''),
            'assistant_label' => fcc_ai_get_assistant_label((string) ($row['assistant_type'] ?? '')),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'reason' => (string) ($row['reason'] ?? ''),
            'reason_label' => fcc_ai_get_feedback_reason_label((string) ($row['reason'] ?? ''), $language),
            'note' => trim((string) ($row['note'] ?? '')),
            'message_excerpt' => fcc_ai_excerpt((string) ($row['message_content'] ?? ''), 220),
            'source_label' => trim((string) (($conversation_meta['source_page_title'] ?? '') ?: ($conversation_meta['source_context'] ?? ''))),
            'datetime' => (string) ($row['datetime'] ?? ''),
            'thread_preview' => $thread_preview,
        ];
    }

    $payload['rising_topics'] = fcc_ai_get_topic_trend_rows($period_start_datetime, $allowed_user_ids, $limit);
    $payload['webinar_candidates'] = fcc_ai_build_webinar_candidate_rows($payload['top_topics'], $payload['rising_topics'], $payload['recent_negative_feedback'], $language, $limit);
    $payload['help_watchlist'] = fcc_ai_build_help_watchlist($payload['top_users'], $language, $limit);
    $payload['assistant_performance'] = fcc_ai_build_assistant_performance_rows($payload['assistant_breakdown'], $language, $limit);
    $payload['useful_items'] = fcc_ai_build_team_useful_items($payload, $language, 4);
    $payload['recent_threads'] = fcc_ai_get_team_recent_conversation_rows($period_start_datetime, $allowed_user_ids, max($limit * 2, 12), $language, $detail_period);
    $payload['control_tower'] = fcc_ai_build_team_control_tower_payload($payload, $language, $limit);

    return $payload;
}

function fcc_ai_get_user_dashboard_payload(int $user_id, string $period_start_datetime, int $limit = 6, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(1, min(12, $limit));

    $payload = [
        'is_available' => false,
        'period_start_datetime' => $period_start_datetime,
        'totals' => [
            'conversations' => 0,
            'coach_conversations' => 0,
            'public_conversations' => 0,
            'user_messages' => 0,
            'assistant_messages' => 0,
            'messages' => 0,
            'leads' => 0,
            'business_leads' => 0,
            'captured_threads' => 0,
            'hot_leads' => 0,
            'positive_feedback' => 0,
            'negative_feedback' => 0,
            'review_conversations' => 0,
        ],
        'assistant_breakdown' => [],
        'recent_conversations' => [],
        'recent_leads' => [],
        'top_topics' => [],
        'recent_negative_feedback' => [],
        'rising_topics' => [],
        'recent_alerts' => [],
        'useful_items' => [],
    ];

    if($user_id <= 0 || !fcc_ai_tables_ready()) {
        return $payload;
    }

    $payload['is_available'] = true;
    $period_start_datetime = trim($period_start_datetime) !== '' ? trim($period_start_datetime) : date('Y-m-d 00:00:00', strtotime('-30 days'));
    $period_start_sql = db()->escape($period_start_datetime);
    $assistant_breakdown = [];

    foreach(fcc_ai_get_assistant_types() as $assistant_type => $definition) {
        $assistant_breakdown[$assistant_type] = [
            'assistant_type' => $assistant_type,
            'label' => (string) ($definition['label'] ?? $assistant_type),
            'conversations' => 0,
            'messages' => 0,
            'leads' => 0,
            'business_leads' => 0,
            'positive_feedback' => 0,
            'negative_feedback' => 0,
        ];
    }

    $aggregate_result = database()->query("SELECT
            `assistant_type`,
            `scope`,
            COUNT(*) AS `conversations`,
            SUM(`total_user_messages`) AS `user_messages`,
            SUM(`total_assistant_messages`) AS `assistant_messages`,
            SUM(CASE WHEN `lead_status` = 'captured' THEN 1 ELSE 0 END) AS `captured_threads`
        FROM `fcc_ai_conversations`
        WHERE `user_id` = {$user_id}
          AND COALESCE(`last_message_at`, `last_datetime`, `datetime`) >= '{$period_start_sql}'
        GROUP BY `assistant_type`, `scope`");

    while($row = $aggregate_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $scope = (string) ($row['scope'] ?? 'public_app');
        $conversation_total = (int) ($row['conversations'] ?? 0);
        $user_messages = (int) ($row['user_messages'] ?? 0);
        $assistant_messages = (int) ($row['assistant_messages'] ?? 0);

        if(isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type]['conversations'] += $conversation_total;
            $assistant_breakdown[$assistant_type]['messages'] += ($user_messages + $assistant_messages);
        }

        $payload['totals']['conversations'] += $conversation_total;
        $payload['totals']['user_messages'] += $user_messages;
        $payload['totals']['assistant_messages'] += $assistant_messages;
        $payload['totals']['messages'] += ($user_messages + $assistant_messages);
        $payload['totals'][$scope === 'internal_coach' ? 'coach_conversations' : 'public_conversations'] += $conversation_total;
        $payload['totals']['captured_threads'] += (int) ($row['captured_threads'] ?? 0);
    }

    $lead_aggregate_result = database()->query("SELECT
            `assistant_type`,
            `lead_type`,
            COUNT(*) AS `leads`,
            SUM(CASE WHEN `lead_score` >= 75 THEN 1 ELSE 0 END) AS `hot_leads`
        FROM `fcc_ai_leads`
        WHERE `user_id` = {$user_id}
          AND `datetime` >= '{$period_start_sql}'
        GROUP BY `assistant_type`, `lead_type`");

    while($row = $lead_aggregate_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $lead_type = (string) ($row['lead_type'] ?? '');
        $lead_total = (int) ($row['leads'] ?? 0);

        if(isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type]['leads'] += $lead_total;
            if(in_array($lead_type, ['business_interest', 'mixed_interest'], true)) {
                $assistant_breakdown[$assistant_type]['business_leads'] += $lead_total;
            }
        }

        $payload['totals']['leads'] += $lead_total;
        if(in_array($lead_type, ['business_interest', 'mixed_interest'], true)) {
            $payload['totals']['business_leads'] += $lead_total;
        }
        $payload['totals']['hot_leads'] += (int) ($row['hot_leads'] ?? 0);
    }

    $feedback_aggregate_result = database()->query("SELECT
            `assistant_type`,
            SUM(CASE WHEN `feedback_type` = 'up' THEN 1 ELSE 0 END) AS `positive_feedback`,
            SUM(CASE WHEN `feedback_type` = 'down' AND COALESCE(`status`, 'new') != 'resolved' THEN 1 ELSE 0 END) AS `negative_feedback`
        FROM `fcc_ai_message_feedback`
        WHERE `user_id` = {$user_id}
          AND `assistant_type` != 'coach'
          AND " . fcc_ai_get_feedback_visibility_sql() . "
          AND COALESCE(`last_datetime`, `datetime`) >= '{$period_start_sql}'
        GROUP BY `assistant_type`");

    while($feedback_aggregate_result && $row = $feedback_aggregate_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $positive_feedback = (int) ($row['positive_feedback'] ?? 0);
        $negative_feedback = (int) ($row['negative_feedback'] ?? 0);

        if(isset($assistant_breakdown[$assistant_type])) {
            $assistant_breakdown[$assistant_type]['positive_feedback'] += $positive_feedback;
            $assistant_breakdown[$assistant_type]['negative_feedback'] += $negative_feedback;
        }

        $payload['totals']['positive_feedback'] += $positive_feedback;
        $payload['totals']['negative_feedback'] += $negative_feedback;
    }

    $review_conversations_result = database()->query("SELECT COUNT(DISTINCT `f`.`fcc_ai_conversation_id`) AS `total`
        FROM `fcc_ai_message_feedback` AS `f`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `f`.`fcc_ai_conversation_id`
        WHERE `f`.`user_id` = {$user_id}
          AND `f`.`feedback_type` = 'down'
          AND COALESCE(`c`.`assistant_type`, '') != 'coach'
          AND COALESCE(`f`.`status`, 'new') != 'resolved'
          AND " . fcc_ai_get_feedback_visibility_sql('f') . "
          AND COALESCE(`f`.`last_datetime`, `f`.`datetime`) >= '{$period_start_sql}'");

    if($review_conversations_result && $review_row = $review_conversations_result->fetch_assoc()) {
        $payload['totals']['review_conversations'] = (int) ($review_row['total'] ?? 0);
    }

    $topics_result = database()->query("SELECT
            `primary_topic`,
            `primary_topic_label`,
            COUNT(*) AS `total`
        FROM `fcc_ai_conversation_insights`
        WHERE `user_id` = {$user_id}
          AND COALESCE(`assistant_type`, '') != 'coach'
          AND COALESCE(`scope`, '') != 'internal_coach'
          AND COALESCE(`last_datetime`, `datetime`) >= '{$period_start_sql}'
          AND `primary_topic` IS NOT NULL
          AND `primary_topic` != ''
        GROUP BY `primary_topic`, `primary_topic_label`
        ORDER BY `total` DESC, `primary_topic_label` ASC
        LIMIT {$limit}");

    while($topics_result && $row = $topics_result->fetch_assoc()) {
        $payload['top_topics'][] = [
            'key' => (string) ($row['primary_topic'] ?? ''),
            'label' => (string) (($row['primary_topic_label'] ?? '') ?: ($row['primary_topic'] ?? '')),
            'total' => (int) ($row['total'] ?? 0),
        ];
    }

    $payload['assistant_breakdown'] = array_values($assistant_breakdown);
    usort($payload['assistant_breakdown'], static function(array $a, array $b) {
        return (($b['conversations'] ?? 0) <=> ($a['conversations'] ?? 0))
            ?: (($b['messages'] ?? 0) <=> ($a['messages'] ?? 0))
            ?: strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
    });

    $conversation_result = database()->query("SELECT
            `c`.`fcc_ai_conversation_id`,
            `c`.`assistant_type`,
            `c`.`scope`,
            `c`.`public_id`,
            `c`.`lead_status`,
            `c`.`total_user_messages`,
            `c`.`total_assistant_messages`,
            COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`) AS `activity_at`,
            `a`.`display_name` AS `assistant_display_name`
        FROM `fcc_ai_conversations` AS `c`
        LEFT JOIN `fcc_ai_assistants` AS `a` ON `a`.`fcc_ai_assistant_id` = `c`.`fcc_ai_assistant_id`
        WHERE `c`.`user_id` = {$user_id}
          AND COALESCE(`c`.`last_message_at`, `c`.`last_datetime`, `c`.`datetime`) >= '{$period_start_sql}'
        ORDER BY `activity_at` DESC
        LIMIT {$limit}");

    while($row = $conversation_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $assistant_label = trim((string) ($row['assistant_display_name'] ?? ''));

        if($assistant_label === '') {
            $assistant_label = fcc_ai_get_assistant_label($assistant_type);
        }

        $conversation_id = (int) ($row['fcc_ai_conversation_id'] ?? 0);

        $payload['recent_conversations'][] = [
            'conversation_id' => $conversation_id,
            'assistant_label' => $assistant_label,
            'scope' => (string) ($row['scope'] ?? ''),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'lead_status' => (string) ($row['lead_status'] ?? 'none'),
            'total_user_messages' => (int) ($row['total_user_messages'] ?? 0),
            'total_assistant_messages' => (int) ($row['total_assistant_messages'] ?? 0),
            'last_user_preview' => fcc_ai_get_conversation_role_preview($conversation_id, 'user'),
            'last_assistant_preview' => fcc_ai_get_conversation_role_preview($conversation_id, 'assistant'),
            'thread_preview' => $conversation_id > 0 ? array_slice(fcc_ai_get_conversation_messages($conversation_id, 12), -8) : [],
            'activity_at' => (string) ($row['activity_at'] ?? ''),
            'public_id' => (string) ($row['public_id'] ?? ''),
        ];
    }

    if(!empty($payload['recent_conversations'])) {
        $insight_map = fcc_ai_get_conversation_insight_map(array_map(static function(array $row): int {
            return (int) ($row['conversation_id'] ?? 0);
        }, $payload['recent_conversations']));

        $payload['recent_conversations'] = array_map(static function(array $row) use ($insight_map, $language): array {
            return fcc_ai_build_chat_intelligence_thread_row($row, $insight_map, $language);
        }, $payload['recent_conversations']);
    }

    $lead_result = database()->query("SELECT
            `l`.`assistant_type`,
            `l`.`lead_type`,
            `l`.`lead_score`,
            `l`.`name`,
            `l`.`email`,
            `l`.`phone`,
            `l`.`preferred_contact_channel`,
            `l`.`message`,
            `l`.`datetime`,
            `c`.`scope`
        FROM `fcc_ai_leads` AS `l`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `l`.`fcc_ai_conversation_id`
        WHERE `l`.`user_id` = {$user_id}
          AND `l`.`datetime` >= '{$period_start_sql}'
        ORDER BY `l`.`datetime` DESC
        LIMIT {$limit}");

    while($row = $lead_result->fetch_assoc()) {
        $assistant_type = (string) ($row['assistant_type'] ?? '');
        $payload['recent_leads'][] = [
            'assistant_label' => fcc_ai_get_assistant_label($assistant_type),
            'lead_type_label' => fcc_ai_get_lead_type_label((string) ($row['lead_type'] ?? ''), $language),
            'lead_score' => (int) ($row['lead_score'] ?? 0),
            'contact_name' => trim((string) ($row['name'] ?? '')),
            'contact_value' => trim((string) (($row['email'] ?? '') ?: ($row['phone'] ?? ''))),
            'preferred_contact_channel' => trim((string) ($row['preferred_contact_channel'] ?? '')),
            'message_preview' => fcc_ai_excerpt((string) ($row['message'] ?? ''), 120),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'datetime' => (string) ($row['datetime'] ?? ''),
        ];
    }

    $recent_negative_feedback_result = database()->query("SELECT
            `f`.`fcc_ai_message_feedback_id`,
            `f`.`fcc_ai_conversation_id`,
            `f`.`reason`,
            `f`.`note`,
            `f`.`datetime`,
            `c`.`assistant_type`,
            `c`.`public_id`,
            `c`.`scope`,
            `m`.`content` AS `message_content`
        FROM `fcc_ai_message_feedback` AS `f`
        LEFT JOIN `fcc_ai_conversations` AS `c` ON `c`.`fcc_ai_conversation_id` = `f`.`fcc_ai_conversation_id`
        LEFT JOIN `fcc_ai_messages` AS `m` ON `m`.`fcc_ai_message_id` = `f`.`fcc_ai_message_id`
        WHERE `f`.`user_id` = {$user_id}
          AND COALESCE(`c`.`assistant_type`, '') != 'coach'
          AND `f`.`feedback_type` = 'down'
          AND COALESCE(`f`.`status`, 'new') != 'resolved'
          AND " . fcc_ai_get_feedback_visibility_sql('f') . "
          AND COALESCE(`f`.`last_datetime`, `f`.`datetime`) >= '{$period_start_sql}'
        ORDER BY COALESCE(`f`.`last_datetime`, `f`.`datetime`) DESC
        LIMIT {$limit}");

    while($recent_negative_feedback_result && $row = $recent_negative_feedback_result->fetch_assoc()) {
        $conversation_id = (int) ($row['fcc_ai_conversation_id'] ?? 0);

        $payload['recent_negative_feedback'][] = [
            'feedback_id' => (int) ($row['fcc_ai_message_feedback_id'] ?? 0),
            'conversation_id' => $conversation_id,
            'conversation_public_id' => (string) ($row['public_id'] ?? ''),
            'assistant_type' => (string) ($row['assistant_type'] ?? ''),
            'assistant_label' => fcc_ai_get_assistant_label((string) ($row['assistant_type'] ?? '')),
            'scope_label' => fcc_ai_get_scope_label((string) ($row['scope'] ?? ''), $language),
            'reason_label' => fcc_ai_get_feedback_reason_label((string) ($row['reason'] ?? ''), $language),
            'note' => trim((string) ($row['note'] ?? '')),
            'message_excerpt' => fcc_ai_excerpt((string) ($row['message_content'] ?? ''), 180),
            'datetime' => (string) ($row['datetime'] ?? ''),
            'thread_preview' => $conversation_id > 0 ? array_slice(fcc_ai_get_conversation_messages($conversation_id, 10), -6) : [],
        ];
    }

    $payload['rising_topics'] = fcc_ai_get_topic_trend_rows($period_start_datetime, [$user_id], $limit, true);
    $payload['recent_alerts'] = fcc_ai_build_user_recent_alerts(
        $payload['recent_negative_feedback'],
        fcc_ai_get_recent_user_alerts($user_id, 4, true),
        $language,
        4
    );
    $payload['useful_items'] = fcc_ai_build_user_useful_items($payload, $language);

    return $payload;
}

function fcc_ai_get_user_chat_intelligence_payload(int $user_id, string $period_start_datetime, int $limit = 6, string $language = 'hr'): array {
    $language = fcc_ai_resolve_public_reply_language($language);
    $limit = max(3, min(12, $limit));
    $dashboard = fcc_ai_get_user_dashboard_payload($user_id, $period_start_datetime, max(8, $limit * 2), $language);

    $payload = [
        'is_available' => !empty($dashboard['is_available']),
        'headline' => '',
        'executive_summary' => '',
        'coach' => [
            'summary' => '',
            'blocker' => '',
            'next_admin_move' => '',
            'next_user_move' => '',
            'top_topics' => [],
            'threads' => [],
        ],
        'public_ai' => [
            'summary' => '',
            'blocker' => '',
            'next_admin_move' => '',
            'next_user_move' => '',
            'top_topics' => [],
            'threads' => [],
        ],
        'strengths' => [],
        'weaknesses' => [],
        'admin_changes' => [],
        'risky_threads' => [],
        'suspicious_threads' => [],
        'review_threads' => [],
        'source' => $dashboard,
    ];

    if(empty($dashboard['is_available'])) {
        return $payload;
    }

    $period_start_sql = db()->escape(trim($period_start_datetime) !== '' ? trim($period_start_datetime) : date('Y-m-d 00:00:00', strtotime('-30 days')));
    $coach_topics = [];
    $public_topics = [];
    $coach_thread_total = 0;
    $public_thread_total = 0;
    $coach_review_total = 0;
    $public_review_total = 0;
    $public_captured_total = 0;

    $insight_result = database()->query("SELECT
            `fcc_ai_conversation_id`,
            `scope`,
            `primary_topic`,
            `primary_topic_label`,
            `intent`,
            `outcome_signal`,
            `quality_signal`
        FROM `fcc_ai_conversation_insights`
        WHERE `user_id` = {$user_id}
          AND COALESCE(`last_datetime`, `datetime`) >= '{$period_start_sql}'");

    while($insight_result && $row = $insight_result->fetch_assoc()) {
        $scope = (string) ($row['scope'] ?? 'public_app');
        $topic_label = trim((string) (($row['primary_topic_label'] ?? '') ?: ($row['primary_topic'] ?? '')));
        $quality_signal = (string) ($row['quality_signal'] ?? 'neutral');
        $outcome_signal = (string) ($row['outcome_signal'] ?? '');

        if($scope === 'internal_coach') {
            $coach_thread_total++;
            if($quality_signal === 'needs_review') {
                $coach_review_total++;
            }
            if($topic_label !== '') {
                $coach_topics[$topic_label] = ($coach_topics[$topic_label] ?? 0) + 1;
            }
        } else {
            $public_thread_total++;
            if($quality_signal === 'needs_review') {
                $public_review_total++;
            }
            if($outcome_signal === 'lead_captured') {
                $public_captured_total++;
            }
            if($topic_label !== '') {
                $public_topics[$topic_label] = ($public_topics[$topic_label] ?? 0) + 1;
            }
        }
    }

    arsort($coach_topics);
    arsort($public_topics);

    $coach_topic_rows = array_map(static function(string $label, int $total): array {
        return ['label' => $label, 'total' => $total];
    }, array_keys($coach_topics), array_values($coach_topics));
    $public_topic_rows = array_map(static function(string $label, int $total): array {
        return ['label' => $label, 'total' => $total];
    }, array_keys($public_topics), array_values($public_topics));

    $coach_threads = array_values(array_filter(($dashboard['recent_conversations'] ?? []), static function(array $row): bool {
        return (string) ($row['scope_label'] ?? '') === 'Coach' || trim((string) ($row['scope'] ?? '')) === 'internal_coach';
    }));
    $public_threads = array_values(array_filter(($dashboard['recent_conversations'] ?? []), static function(array $row): bool {
        return !((string) ($row['scope_label'] ?? '') === 'Coach' || trim((string) ($row['scope'] ?? '')) === 'internal_coach');
    }));

    $risky_threads = [];
    foreach($dashboard['recent_conversations'] ?? [] as $thread_row) {
        $is_risky = !empty($thread_row['needs_review'])
            || !empty($thread_row['suspicion']['is_suspicious'])
            || (int) ($thread_row['suspicion']['score'] ?? 0) >= 40;

        if($is_risky) {
            $risky_threads[] = $thread_row;
        }
    }

    usort($risky_threads, static function(array $a, array $b) {
        return (((int) ($b['suspicion']['score'] ?? 0)) <=> ((int) ($a['suspicion']['score'] ?? 0)))
            ?: (((int) ($b['needs_review'] ?? 0)) <=> ((int) ($a['needs_review'] ?? 0)))
            ?: strcmp((string) ($b['activity_at'] ?? ''), (string) ($a['activity_at'] ?? ''));
    });

    $suspicious_threads = array_values(array_filter($risky_threads, static function(array $thread_row): bool {
        return !empty($thread_row['suspicion']['is_suspicious']);
    }));

    $review_threads = [];
    foreach(($dashboard['recent_negative_feedback'] ?? []) as $feedback_row) {
        $review_threads[] = [
            'assistant_label' => (string) ($feedback_row['assistant_label'] ?? 'AI'),
            'scope_label' => (string) ($feedback_row['scope_label'] ?? ''),
            'reason_label' => (string) ($feedback_row['reason_label'] ?? ''),
            'note' => (string) ($feedback_row['note'] ?? ''),
            'message_excerpt' => (string) ($feedback_row['message_excerpt'] ?? ''),
            'datetime' => (string) ($feedback_row['datetime'] ?? ''),
            'thread_preview' => $feedback_row['thread_preview'] ?? [],
        ];
    }

    $coach_top_topic = (string) ($coach_topic_rows[0]['label'] ?? '');
    $public_top_topic = (string) ($public_topic_rows[0]['label'] ?? '');
    $total_leads = (int) ($dashboard['totals']['leads'] ?? 0);
    $review_total = (int) ($dashboard['totals']['review_conversations'] ?? 0);

    if($public_captured_total > 0) {
        $payload['strengths'][] = 'Javni AI već hvata konkretne leadove i ima vidljiv conversion signal.';
    }

    if($public_top_topic !== '' && $public_thread_total >= 2) {
        $payload['strengths'][] = 'Publika pokazuje jasan interes za temu "' . $public_top_topic . '", što daje dobar fokus za sadržaj i CTA.';
    }

    if($coach_top_topic !== '' && $coach_review_total === 0 && $coach_thread_total >= 2) {
        $payload['strengths'][] = 'Coach komunikacija je fokusirana oko teme "' . $coach_top_topic . '" bez review signala.';
    }

    if($review_total > 0) {
        $payload['weaknesses'][] = 'Dio javnih AI odgovora traži doradu jer korisnici signaliziraju nejasnoću ili slabiji odgovor.';
    }

    if($coach_thread_total >= 3 && $total_leads === 0) {
        $payload['weaknesses'][] = 'Coach se koristi, ali još nema dovoljno execution signala koji bi se pretvorio u lead ili jasan pomak.';
    }

    if($public_thread_total >= 4 && $public_captured_total === 0) {
        $payload['weaknesses'][] = 'Javni AI ima razgovore, ali još ne pretvara interes u uhvaćeni lead.';
    }

    if(count($public_topics) >= 4) {
        $payload['weaknesses'][] = 'Pitanja publike su raspršena kroz više tema pa positioning i sljedeći korak nisu dovoljno oštri.';
    }

    if($review_total > 0) {
        $payload['admin_changes'][] = 'Prvo otvori review queue i doradi odgovore koji već imaju signal lošeg odgovora.';
    }

    if(!empty($suspicious_threads)) {
        $payload['admin_changes'][] = 'Pregledaj suspektne razgovore i provjeri traže li doradu pravila, compliance copyja ili prompt zaštite.';
    }

    if($coach_thread_total >= 3 && $total_leads === 0) {
        $payload['admin_changes'][] = 'Pošalji mentorski follow-up i svedi Coach fokus na jedan provedivi tjedni potez.';
    }

    if($public_thread_total >= 4 && $public_captured_total === 0) {
        $payload['admin_changes'][] = 'Doradi lead capture CTA i sljedeći korak na javnoj FCC aplikaciji jer razgovori postoje bez conversiona.';
    }

    if($public_top_topic !== '') {
        $payload['admin_changes'][] = 'Pretvori temu "' . $public_top_topic . '" u jači script, FAQ ili sadržaj koji će AI i suradnik koristiti dosljednije.';
    }

    $payload['coach']['summary'] = $coach_thread_total === 0
        ? 'Coach se još ne koristi dovoljno da bi dao pouzdan signal.'
        : ($coach_thread_total >= 3 && $total_leads === 0
            ? 'Coach je aktivan, ali razgovori još ne prelaze dovoljno jasno u execution i rezultat.'
            : 'Coach signal pokazuje gdje suradnik aktivno traži pomoć i na kojim temama mu treba vodstvo.');
    $payload['coach']['blocker'] = $coach_thread_total >= 3 && $total_leads === 0
        ? 'Glavni blocker je provedba: puno Coach angažmana, ali premalo rezultatskog pomaka.'
        : ($coach_top_topic !== '' ? 'Najviše se vrti tema "' . $coach_top_topic . '".' : 'Još nema dominantnog Coach blockera.');
    $payload['coach']['next_admin_move'] = $coach_thread_total > 0
        ? 'Provjeri zadnje Coach threadove i svedi sljedeći mentorski potez na jednu konkretnu tjednu obvezu.'
        : 'Prvo potakni suradnika da aktivno koristi Coach na stvarnom tjednom cilju.';
    $payload['coach']['next_user_move'] = $coach_thread_total >= 3 && $total_leads === 0
        ? 'Prevesti zadnji Coach savjet u jednu mjerljivu akciju ovaj tjedan.'
        : 'Nastaviti Coach kroz jednu jasnu temu i jedan konkretan sljedeći korak.';
    $payload['coach']['top_topics'] = array_slice($coach_topic_rows, 0, 4);
    $payload['coach']['threads'] = array_slice($coach_threads, 0, $limit);

    $payload['public_ai']['summary'] = $public_thread_total === 0
        ? 'Javni AI još nema dovoljno razgovora za pouzdan signal.'
        : ($public_captured_total > 0
            ? 'Javni AI već pokazuje conversion potencijal kroz uhvaćene leadove i ponavljajuće teme publike.'
            : 'Javni AI ima razgovore, ali još traži oštriji positioning i jači conversion put.');
    $payload['public_ai']['blocker'] = $review_total > 0
        ? 'Glavni blocker je kvaliteta dijela javnih odgovora i potreba za jasnijim sljedećim korakom.'
        : ($public_thread_total >= 4 && $public_captured_total === 0
            ? 'Glavni blocker je conversion: interes postoji, ali CTA i lead capture još nisu dovoljno jaki.'
            : ($public_top_topic !== '' ? 'Najviše interesa dolazi kroz temu "' . $public_top_topic . '".' : 'Još nema dominantnog javnog AI blockera.'));
    $payload['public_ai']['next_admin_move'] = $public_thread_total > 0
        ? 'Pregledaj javne threadove s najviše interesa i uskladi CTA, FAQ ili skriptu oko najjače teme.'
        : 'Prvo dovedi više javnih AI razgovora kroz bolju vidljivost AI bloka.';
    $payload['public_ai']['next_user_move'] = $public_captured_total > 0
        ? 'Zadržati temu koja već hvata leadove i pojačati sadržaj oko nje.'
        : 'Pojačati jedan jasan CTA i jednu glavnu temu koja vodi prema kontaktu ili preporuci.';
    $payload['public_ai']['top_topics'] = array_slice($public_topic_rows, 0, 4);
    $payload['public_ai']['threads'] = array_slice($public_threads, 0, $limit);

    $payload['risky_threads'] = array_slice($risky_threads, 0, $limit);
    $payload['suspicious_threads'] = array_slice($suspicious_threads, 0, $limit);
    $payload['review_threads'] = array_slice($review_threads, 0, $limit);

    $payload['headline'] = $public_captured_total > 0
        ? 'AI već daje rezultat, ali traži čišće upravljanje temama i review signalima.'
        : ($coach_thread_total >= 3 && $total_leads === 0
            ? 'Suradnik traži dosta Coach pomoći, ali to se još ne pretvara u jasan execution signal.'
            : ($review_total > 0
                ? 'Najveći operativni problem trenutno su javni AI odgovori koji traže provjeru.'
                : 'AI signal je aktivan, ali treba jasnije odvojiti teme, conversion put i mentorski fokus.'));

    $summary_parts = [];
    if($coach_thread_total > 0) {
        $summary_parts[] = 'Coach razgovori: ' . nr($coach_thread_total) . ($coach_top_topic !== '' ? ' · najviše se vrti "' . $coach_top_topic . '"' : '');
    }
    if($public_thread_total > 0) {
        $summary_parts[] = 'Javni AI razgovori: ' . nr($public_thread_total) . ($public_top_topic !== '' ? ' · top tema "' . $public_top_topic . '"' : '');
    }
    if($public_captured_total > 0) {
        $summary_parts[] = 'Uhvaćeni public leadovi: ' . nr($public_captured_total);
    }
    if($review_total > 0) {
        $summary_parts[] = 'Review threadovi: ' . nr($review_total);
    }
    if(!empty($suspicious_threads)) {
        $summary_parts[] = 'Suspektni razgovori: ' . nr(count($suspicious_threads));
    }

    $payload['executive_summary'] = !empty($summary_parts)
        ? implode(' · ', $summary_parts) . '.'
        : 'Još nema dovoljno AI signala za dublji admin zaključak.';

    $payload['strengths'] = array_values(array_slice(array_unique(array_filter($payload['strengths'])), 0, 4));
    $payload['weaknesses'] = array_values(array_slice(array_unique(array_filter($payload['weaknesses'])), 0, 4));
    $payload['admin_changes'] = array_values(array_slice(array_unique(array_filter($payload['admin_changes'])), 0, 5));

    $payload['inbox'] = [
        'tabs' => [
            [
                'key' => 'coach',
                'label' => $language === 'en' ? 'Coach' : 'Coach',
                'count' => count($payload['coach']['threads'] ?? []),
            ],
            [
                'key' => 'public_ai',
                'label' => $language === 'en' ? 'Public AI' : 'AI za ljude',
                'count' => count($payload['public_ai']['threads'] ?? []),
            ],
            [
                'key' => 'suspicious',
                'label' => $language === 'en' ? 'Suspicious' : 'Suspektni',
                'count' => count($payload['suspicious_threads'] ?? []),
            ],
            [
                'key' => 'review',
                'label' => $language === 'en' ? 'Review' : 'Review',
                'count' => count($payload['review_threads'] ?? []),
            ],
            [
                'key' => 'leads',
                'label' => $language === 'en' ? 'Lead / conversion' : 'Lead / conversion',
                'count' => count($dashboard['recent_leads'] ?? []),
            ],
        ],
        'coach_threads' => array_slice($payload['coach']['threads'] ?? [], 0, $limit),
        'public_threads' => array_slice($payload['public_ai']['threads'] ?? [], 0, $limit),
        'suspicious_threads' => array_slice($payload['suspicious_threads'] ?? [], 0, $limit),
        'review_threads' => array_slice($payload['review_threads'] ?? [], 0, $limit),
        'lead_threads' => array_slice($dashboard['recent_leads'] ?? [], 0, $limit),
    ];
    $payload['executive_report'] = fcc_ai_build_user_executive_report_payload($payload, $language, 5);

    return $payload;
}

function fcc_ai_create_or_resume_public_conversation(array $payload): array {
    fcc_ai_ensure_tables();

    $context = fcc_ai_resolve_public_owner_context($payload);
    if(!$context) {
        throw new \RuntimeException('Nije moguce povezati razgovor s FCC aplikacijom.');
    }

    $user = $context['user'];
    $link = $context['link'];
    $conversation = $context['conversation'];
    $assistant_type = fcc_ai_validate_assistant_type((string) ($payload['assistant_type'] ?? ''), true);

    if(!$assistant_type && $conversation) {
        $assistant_type = fcc_ai_validate_assistant_type((string) ($conversation->assistant_type ?? ''), true);
    }

    if(!$assistant_type) {
        throw new \RuntimeException('Nepoznat AI assistant tip.');
    }

    if(!fcc_ai_user_has_public_ai_access($user)) {
        throw new \RuntimeException(l('global.info_message.plan_feature_no_access'));
    }

    $scope = fcc_ai_normalize_scope((string) ($payload['scope'] ?? ($conversation->scope ?? '')), $assistant_type);
    $language = fcc_ai_normalize_language((string) ($payload['language'] ?? ($conversation->language ?? '')));
    $source_context = trim((string) ($payload['source_context'] ?? ''));
    $source_page_url = trim((string) ($payload['source_page_url'] ?? ''));
    $source_page_slug = trim((string) ($payload['source_page_slug'] ?? ''));
    $blog_post_id = isset($payload['blog_post_id']) ? (int) $payload['blog_post_id'] : null;
    $visitor_key = trim((string) ($payload['visitor_key'] ?? ''));
    $visitor_key = $visitor_key !== '' ? mb_substr($visitor_key, 0, 64) : fcc_ai_generate_public_id(12);

    fcc_ai_seed_user_assistants((int) $user->user_id, (string) ($user->name ?? ''));
    $assistant_id = fcc_ai_get_assistant_id_for_user((int) $user->user_id, $assistant_type, $scope);

    if($conversation) {
        $meta = is_object($conversation->meta) ? (array) $conversation->meta : (array) json_decode($conversation->meta ?? '{}', true);
        $meta['source_page_url'] = $source_page_url !== '' ? $source_page_url : ($meta['source_page_url'] ?? '');
        $meta['source_page_slug'] = $source_page_slug !== '' ? $source_page_slug : ($meta['source_page_slug'] ?? '');
        $meta['continuation_storage_key'] = fcc_ai_get_public_storage_key();

        db()->where('fcc_ai_conversation_id', $conversation->fcc_ai_conversation_id)->update('fcc_ai_conversations', [
            'fcc_ai_assistant_id' => $assistant_id ?: $conversation->fcc_ai_assistant_id,
            'scope' => $scope,
            'blog_post_id' => $blog_post_id ?: ($conversation->blog_post_id ?: null),
            'language' => $language !== 'auto' ? $language : ($conversation->language ?: null),
            'meta' => json_encode($meta),
            'last_datetime' => get_date(),
        ]);

        fcc_ai_log_event([
            'fcc_ai_conversation_id' => (int) $conversation->fcc_ai_conversation_id,
            'user_id' => (int) $user->user_id,
            'assistant_type' => $assistant_type,
            'event_type' => 'conversation_resumed',
            'link_id' => (int) ($link->link_id ?? $conversation->link_id ?? 0),
            'blog_post_id' => $blog_post_id ?: (int) ($conversation->blog_post_id ?? 0),
            'meta' => [
                'source_context' => $source_context,
                'source_page_url' => $source_page_url,
                'scope' => $scope,
            ],
        ]);

        $resolved_language = fcc_ai_resolve_public_reply_language(
            $language !== 'auto' ? $language : (string) ($conversation->language ?? 'auto')
        );
        fcc_ai_ensure_public_welcome_message((int) $conversation->fcc_ai_conversation_id, $assistant_type, $resolved_language);
        $messages = fcc_ai_get_conversation_messages((int) $conversation->fcc_ai_conversation_id, 40, fcc_ai_build_feedback_actor('visitor', $visitor_key));

        return [
            'conversation_id' => (int) $conversation->fcc_ai_conversation_id,
            'conversation_public_id' => (string) $conversation->public_id,
            'assistant_type' => $assistant_type,
            'assistant_label' => fcc_ai_get_assistant_label($assistant_type),
            'scope' => $scope,
            'link_id' => (int) ($link->link_id ?? $conversation->link_id ?? 0),
            'blog_post_id' => $blog_post_id ?: (int) ($conversation->blog_post_id ?? 0),
            'owner_name' => (string) ($user->name ?? ''),
            'language' => $resolved_language,
            'lead_status' => (string) ($conversation->lead_status ?? 'none'),
            'storage_key' => fcc_ai_get_public_storage_key(),
            'context_storage_key' => fcc_ai_get_public_context_storage_key(),
            'is_resumed' => true,
            'messages' => $messages,
        ];
    }

    $conversation_public_id = fcc_ai_generate_public_id();
    $meta = [
        'source_context' => $source_context,
        'source_page_url' => $source_page_url,
        'source_page_slug' => $source_page_slug,
        'continuation_storage_key' => fcc_ai_get_public_storage_key(),
    ];

    $conversation_id = db()->insert('fcc_ai_conversations', [
        'fcc_ai_assistant_id' => $assistant_id,
        'user_id' => (int) $user->user_id,
        'assistant_type' => $assistant_type,
        'scope' => $scope,
        'link_id' => !empty($link->link_id) ? (int) $link->link_id : null,
        'project_id' => !empty($link->project_id) ? (int) $link->project_id : null,
        'blog_post_id' => $blog_post_id ?: null,
        'public_id' => $conversation_public_id,
        'visitor_key' => $visitor_key,
        'language' => $language !== 'auto' ? $language : null,
        'status' => 'active',
        'lead_status' => 'none',
        'meta' => json_encode($meta),
        'datetime' => get_date(),
        'last_datetime' => get_date(),
    ]);

    fcc_ai_log_event([
        'fcc_ai_conversation_id' => (int) $conversation_id,
        'user_id' => (int) $user->user_id,
        'assistant_type' => $assistant_type,
        'event_type' => 'conversation_started',
        'link_id' => (int) ($link->link_id ?? 0),
        'blog_post_id' => $blog_post_id ?: 0,
        'meta' => [
            'source_context' => $source_context,
            'source_page_url' => $source_page_url,
            'scope' => $scope,
        ],
    ]);
    fcc_ai_increment_daily_stats((int) $user->user_id, $assistant_type, $scope, [
        'conversations' => 1,
    ], [
        'event_type' => 'conversation_started',
    ]);

    $resolved_language = fcc_ai_resolve_public_reply_language($language);
    fcc_ai_ensure_public_welcome_message((int) $conversation_id, $assistant_type, $resolved_language);
    $messages = fcc_ai_get_conversation_messages((int) $conversation_id, 40, fcc_ai_build_feedback_actor('visitor', $visitor_key));

    return [
        'conversation_id' => (int) $conversation_id,
        'conversation_public_id' => $conversation_public_id,
        'assistant_type' => $assistant_type,
        'assistant_label' => fcc_ai_get_assistant_label($assistant_type),
        'scope' => $scope,
        'link_id' => (int) ($link->link_id ?? 0),
        'blog_post_id' => $blog_post_id ?: 0,
        'owner_name' => (string) ($user->name ?? ''),
        'language' => $resolved_language,
        'lead_status' => 'none',
        'storage_key' => fcc_ai_get_public_storage_key(),
        'context_storage_key' => fcc_ai_get_public_context_storage_key(),
        'is_resumed' => false,
        'messages' => $messages,
    ];
}

function fcc_ai_handle_public_message(array $payload): array {
    fcc_ai_ensure_tables();

    $message = trim((string) ($payload['message'] ?? ''));

    if($message === '') {
        throw new \RuntimeException('Poruka ne može biti prazna.');
    }

    $conversation_payload = [
        'assistant_type' => (string) ($payload['assistant_type'] ?? ''),
        'scope' => (string) ($payload['scope'] ?? ''),
        'conversation_public_id' => (string) ($payload['conversation_public_id'] ?? ''),
        'link_id' => (int) ($payload['link_id'] ?? 0),
        'blog_post_id' => !empty($payload['blog_post_id']) ? (int) $payload['blog_post_id'] : null,
        'language' => (string) ($payload['language'] ?? ''),
        'source_context' => (string) ($payload['source_context'] ?? ''),
        'source_page_url' => (string) ($payload['source_page_url'] ?? ''),
        'source_page_slug' => (string) ($payload['source_page_slug'] ?? ''),
        'visitor_key' => (string) ($payload['visitor_key'] ?? ''),
    ];

    $conversation_state = fcc_ai_create_or_resume_public_conversation($conversation_payload);
    $context = fcc_ai_resolve_public_owner_context([
        'conversation_public_id' => (string) $conversation_state['conversation_public_id'],
        'link_id' => (int) ($payload['link_id'] ?? 0),
    ]);

    if(!$context || empty($context['conversation']) || empty($context['user'])) {
        throw new \RuntimeException('Nije moguće spremiti poruku bez valjanog FCC AI razgovora.');
    }

    $conversation = $context['conversation'];
    $user = $context['user'];
    $link = $context['link'];
    $assistant = fcc_ai_get_assistant_by_id((int) ($conversation->fcc_ai_assistant_id ?? 0));
    $resolved_language = (string) ($conversation_state['language'] ?? $conversation->language ?? 'auto');
    $contextual_message_bundle = fcc_ai_build_contextual_public_message((int) ($conversation->fcc_ai_conversation_id ?? 0), $message);
    $current_user_message = trim((string) $message);
    $message_for_matching = trim((string) ($contextual_message_bundle['message'] ?? $current_user_message));
    $recent_user_context = trim((string) ($contextual_message_bundle['recent_user_context'] ?? ''));
    $used_context_for_matching = !empty($contextual_message_bundle['used_context']);
    $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $message_for_matching);
    $previous_user_message = fcc_ai_get_previous_public_user_message((int) ($conversation->fcc_ai_conversation_id ?? 0), $current_user_message);
    $recent_business_context_message = fcc_ai_get_recent_public_business_context_message(
        (int) ($conversation->fcc_ai_conversation_id ?? 0),
        (string) ($conversation->assistant_type ?? ''),
        $current_user_message,
        4
    );
    $previous_intent = $previous_user_message !== ''
        ? fcc_ai_detect_public_intent((string) ($conversation->assistant_type ?? ''), $previous_user_message)
        : [];
    $current_condition_keys = fcc_ai_get_condition_match_keys(
        fcc_ai_get_product_advisor_effective_condition_matches($current_user_message, $resolved_language)
    );
    $previous_condition_keys = fcc_ai_get_condition_match_keys(
        fcc_ai_get_product_advisor_effective_condition_matches($previous_user_message, $resolved_language)
    );
    $is_recommendation_correction_followup = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && $previous_user_message !== ''
        && fcc_ai_is_public_recommendation_correction_message($current_user_message);
    $is_same_problem_followup_clarification = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && $previous_user_message !== ''
        && empty($current_condition_keys)
        && !empty($previous_condition_keys)
        && fcc_ai_is_ambiguous_same_problem_followup_request($current_user_message);
    $is_business_hesitation_followup = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_is_public_business_hesitation_followup_request($current_user_message);
    $is_owner_help_followup = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_is_public_owner_help_followup_request($current_user_message);
    $is_direct_cure_claim_question = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_contains_keywords($current_user_message, ['izliječ', 'izlijec', 'liječi', 'lijeci', 'cure', 'heals'])
        && !empty($intent['medical_sensitive']);
    $is_business_followup_clarification = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && $recent_business_context_message !== ''
        && (
            (
                $previous_user_message !== ''
                && !empty($previous_intent['business_primary'])
                && fcc_ai_is_public_business_followup_clarification_request($current_user_message)
            )
            || $is_business_hesitation_followup
            || $is_owner_help_followup
        );
    $is_broad_beauty_followup_clarification = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_is_broad_beauty_request($current_user_message)
        && (
            $previous_user_message !== ''
            || !empty($current_condition_keys)
            || !empty($previous_condition_keys)
        );

    if($is_recommendation_correction_followup) {
        $message_for_matching = fcc_ai_build_public_correction_followup_message($previous_user_message);
        $recent_user_context = $previous_user_message;
        $used_context_for_matching = true;
        $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $previous_user_message);
    } elseif($is_same_problem_followup_clarification) {
        $message_for_matching = $previous_user_message . "\n\nFollow-up clarification needed: " . $current_user_message;
        $recent_user_context = $previous_user_message;
        $used_context_for_matching = true;
        $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $previous_user_message);
    } elseif($is_business_followup_clarification) {
        $business_context_message = $recent_business_context_message !== '' ? $recent_business_context_message : $previous_user_message;
        $message_for_matching = $business_context_message . "\n\nBusiness follow-up clarification needed: " . $current_user_message;
        $recent_user_context = $business_context_message;
        $used_context_for_matching = true;
        $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $business_context_message);
        $intent['business'] = true;
        $intent['business_primary'] = true;
        $intent['business_content_request'] = false;
        $intent['support_request'] = false;
        $intent['card_review_request'] = false;
        $intent['explicit_product_request'] = false;
        $intent['product'] = false;
        $intent['lead_type'] = 'business_interest';
    } elseif($is_broad_beauty_followup_clarification && $previous_user_message !== '') {
        $message_for_matching = $previous_user_message . "\n\nBeauty clarification needed: " . $current_user_message;
        $recent_user_context = $previous_user_message;
        $used_context_for_matching = true;
        $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $current_user_message);
    }

    $should_reset_problem_context = fcc_ai_should_reset_public_problem_context(
        (string) ($conversation->assistant_type ?? ''),
        $current_user_message,
        $previous_user_message,
        $resolved_language
    );
    $has_high_risk_medical_context = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_has_high_risk_public_medical_context($current_user_message);

    if(($has_high_risk_medical_context || $should_reset_problem_context) && !$is_same_problem_followup_clarification && !$is_broad_beauty_followup_clarification) {
        $message_for_matching = $current_user_message;
        $recent_user_context = '';
        $used_context_for_matching = false;
        $intent = fcc_ai_detect_public_intent((string) $conversation->assistant_type, $message_for_matching);
    }
    $knowledge_suggestions = fcc_ai_get_public_knowledge_suggestions((string) $conversation->assistant_type, $message_for_matching, [
        'language' => $resolved_language,
        'intent' => $intent,
        'exclude_blog_post_id' => (int) ($conversation->blog_post_id ?? 0),
        'referral_slug' => trim((string) ($link->url ?? '')),
    ]);

    if((string) ($conversation->assistant_type ?? '') === 'product_advisor' && !empty($intent['business_primary'])) {
        $knowledge_suggestions = array_values(array_filter($knowledge_suggestions, static function(array $suggestion) {
            return (string) ($suggestion['kind'] ?? '') === 'business_article';
        }));
    }

    $recommendation_payload = fcc_ai_build_public_recommendation_payload((string) $conversation->assistant_type, $message_for_matching, [
        'language' => $resolved_language,
        'intent' => $intent,
        'knowledge_suggestions' => $knowledge_suggestions,
        'correction_follow_up' => $is_recommendation_correction_followup,
        'same_problem_followup_clarification' => $is_same_problem_followup_clarification,
        'broad_beauty_followup_clarification' => $is_broad_beauty_followup_clarification,
        'previous_condition_context_exists' => !empty($previous_condition_keys),
        'follow_up_message' => $current_user_message,
    ]);

    if(!empty($recommendation_payload['skip_product_tail'])) {
        $knowledge_suggestions = [];
    }

    $is_joint_topical_followup = (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && fcc_ai_is_topical_joint_followup_request($current_user_message)
        && fcc_ai_contains_keywords($message_for_matching, ['hrskavic', 'koljen', 'zglob', 'kuk', 'artroz', 'artrit', 'pokretljiv']);

    if($is_joint_topical_followup) {
        $topical_condition_match = [
            'key' => 'joint_topical_followup',
            'label' => $resolved_language === 'en' ? 'joint care from the outside' : ($resolved_language === 'sl' ? 'lokalna nega sklepov' : 'lokalna njega zglobova'),
            'opening_note' => $resolved_language === 'en'
                ? 'If you already have the main joint direction from the inside and are now asking what to use from the outside, the cleaner Forever next step is to stay on the local joint-care route.'
                : ($resolved_language === 'sl'
                    ? 'Če glavno smer za sklepe že imate od znotraj in zdaj sprašujete, kaj uporabiti zunaj, je najbolj čista naslednja Forever smer ostati na lokalni negi sklepov.'
                    : 'Ako glavni smjer za zglobove već imate iznutra i sada pitate što koristiti izvana, najčišći sljedeći Forever korak je ostati na lokalnoj njezi zglobova.'),
            'recommendation_lines' => $resolved_language === 'en'
                ? [
                    'Forever Aloe Cooling Lotion is the clearest first external direction here when you want a calmer local routine for joints and overload.',
                    'Forever Aloe MSM Gel can stay next to that as an additional topical support option if you want a second local layer.',
                ]
                : ($resolved_language === 'sl'
                    ? [
                        'Forever Aloe Cooling Lotion je tukaj najbolj čista prva zunanja smer, ko želite mirnejšo lokalno rutino za sklepe in obremenitev.',
                        'Forever Aloe MSM Gel lahko ostane ob tem kot dodatna topikalna podporna možnost, če želite še drugo lokalno plast.',
                    ]
                    : [
                        'Forever Aloe Cooling Lotion je ovdje najčišći prvi vanjski smjer kada želite mirniju lokalnu rutinu za zglobove i opterećenje.',
                        'Forever Aloe MSM Gel može ostati uz to kao dodatna topikalna support opcija ako želite još jedan lokalni sloj.',
                    ]),
            'primary_product' => 'Forever Aloe Cooling Lotion',
            'support_products' => ['Forever Aloe MSM Gel'],
            'matched_patterns' => ['lokalno', 'krema', 'zglobovi'],
            'lock_product_scope' => true,
            'sensitive_support_only' => true,
        ];

        $knowledge_suggestions = fcc_ai_get_condition_priority_product_suggestions(
            [$topical_condition_match],
            fcc_ai_get_blog_language_name($resolved_language),
            $resolved_language,
            trim((string) ($link->url ?? '')),
            (string) ($conversation->assistant_type ?? 'product_advisor'),
            [],
            $message_for_matching,
            3
        );

        $recommendation_payload = [
            'theme_matches' => [],
            'theme_keys' => ['mobility'],
            'condition_matches' => [$topical_condition_match],
            'condition_keys' => ['joint_topical_followup'],
            'opening_note' => (string) $topical_condition_match['opening_note'],
            'recommendation_lines' => (array) $topical_condition_match['recommendation_lines'],
            'question_lines' => [],
            'needs_clarification' => false,
            'combination_note' => '',
            'discount_note' => '',
            'primary_product' => 'Forever Aloe Cooling Lotion',
            'support_products' => ['Forever Aloe MSM Gel'],
            'monthly_quantity_note' => '',
            'sensitive_support_only' => true,
            'system_brief' => 'Primary product anchor for this exact message: Forever Aloe Cooling Lotion. Allowed Forever product scope for this exact message: Forever Aloe Cooling Lotion | Forever Aloe MSM Gel. Do not mention other skincare, sunscreen, face-care, ingestible drinks, or unrelated fallback products.',
        ];
    }

    fcc_ai_log_message((int) $conversation->fcc_ai_conversation_id, 'user', $message, [
        'message_type' => 'chat',
        'model' => 'fcc-user-message',
    ]);

    $auto_captured_lead = fcc_ai_try_auto_capture_public_lead_from_message($conversation, $user, $link, $payload, $intent, $message);

    if(!empty($auto_captured_lead['saved'])) {
        $conversation = db()
            ->where('fcc_ai_conversation_id', (int) $conversation->fcc_ai_conversation_id)
            ->getOne('fcc_ai_conversations');
    }

    $reply = fcc_ai_generate_public_reply((string) $conversation->assistant_type, $message, [
        'language' => $resolved_language,
        'intent' => $intent,
        'source_context' => (string) ($payload['source_context'] ?? ''),
        'owner_name' => (string) ($user->name ?? ''),
        'lead_status' => (string) ($conversation->lead_status ?? 'none'),
        'knowledge_suggestions' => $knowledge_suggestions,
        'recommendation_payload' => $recommendation_payload,
        'recent_user_context' => $has_high_risk_medical_context ? '' : $recent_user_context,
        'reset_history' => $should_reset_problem_context,
        'correction_follow_up' => $is_recommendation_correction_followup,
        'same_problem_followup_clarification' => $is_same_problem_followup_clarification,
        'business_followup_clarification' => $is_business_followup_clarification,
        'business_hesitation_followup' => $is_business_hesitation_followup,
        'broad_beauty_followup_clarification' => $is_broad_beauty_followup_clarification,
    ]);

    $should_force_local_reply = $is_same_problem_followup_clarification
        || $is_business_followup_clarification
        || $is_business_hesitation_followup
        || $is_broad_beauty_followup_clarification
        || !empty($intent['business_primary'])
        || !empty($intent['medication_interaction_sensitive'])
        || $is_direct_cure_claim_question
        || !empty($recommendation_payload['question_lines']);

    $model_attempt = [
        'success' => false,
        'reason' => $should_force_local_reply ? 'local_context_clarification' : 'local_preview',
    ];

    if(!$should_force_local_reply) {
        $model_attempt = fcc_ai_try_generate_public_model_reply($conversation, [
            'language' => $resolved_language,
            'scope' => (string) ($conversation->scope ?? 'public_app'),
            'source_context' => (string) ($payload['source_context'] ?? ''),
            'blog_post_id' => (int) ($conversation->blog_post_id ?? 0),
            'owner_name' => (string) ($user->name ?? ''),
            'last_user_message' => $is_recommendation_correction_followup ? $message_for_matching : $message,
            'knowledge_suggestions' => $knowledge_suggestions,
            'recommendation_payload' => $recommendation_payload,
            'recent_user_context' => $has_high_risk_medical_context ? '' : $recent_user_context,
            'reset_history' => $should_reset_problem_context,
            'correction_follow_up' => $is_recommendation_correction_followup,
            'same_problem_followup_clarification' => $is_same_problem_followup_clarification,
            'business_followup_clarification' => $is_business_followup_clarification,
            'business_hesitation_followup' => $is_business_hesitation_followup,
            'broad_beauty_followup_clarification' => $is_broad_beauty_followup_clarification,
            'override_user_message' => $is_recommendation_correction_followup ? $message_for_matching : '',
        ], $assistant);
    }

    $reply_meta = [
        'provider' => 'local_preview',
        'model' => 'fcc-local-preview',
        'fallback_reason' => (string) ($model_attempt['reason'] ?? 'local_preview'),
    ];

    if(!empty($model_attempt['success']) && !empty($model_attempt['content'])) {
        $reply['content'] = trim((string) $model_attempt['content']);
        $reply_meta = [
            'provider' => (string) ($model_attempt['provider'] ?? 'openai'),
            'model' => (string) ($model_attempt['model'] ?? 'openai'),
            'input_tokens' => (int) ($model_attempt['input_tokens'] ?? 0),
            'output_tokens' => (int) ($model_attempt['output_tokens'] ?? 0),
            'total_tokens' => (int) ($model_attempt['total_tokens'] ?? 0),
            'api_response_time' => (int) ($model_attempt['api_response_time'] ?? 0),
            'fallback_reason' => '',
        ];
    }

    $reply_content = trim((string) ($reply['content'] ?? ''));
    $owner_name = trim((string) ($user->name ?? ''));

    if(
        (string) ($conversation->assistant_type ?? '') === 'product_advisor'
        && $owner_name !== ''
        && empty($intent['business'])
        && empty($intent['contact'])
        && empty($reply['lead_capture']['recommended'])
        && mb_stripos($reply_content, $owner_name) !== false
    ) {
        $reply_blocks = preg_split('/\n\s*\n/u', $reply_content) ?: [];
        $reply_blocks = array_values(array_filter($reply_blocks, static function($block) use ($owner_name) {
            return mb_stripos((string) $block, $owner_name) === false;
        }));
        $reply_content = trim(implode("\n\n", $reply_blocks));
    }

    $recommendation_primary = trim((string) ($recommendation_payload['primary_product'] ?? ''));
    $support_products = array_values(array_filter(array_map(static function($item) {
        return trim((string) $item);
    }, (array) ($recommendation_payload['support_products'] ?? []))));
    $allow_sensitive_support_anchor = !empty($recommendation_payload['sensitive_support_only']);

    if(
            (string) ($conversation->assistant_type ?? '') === 'product_advisor'
            && $recommendation_primary !== ''
            && empty($intent['serious'])
        && empty($recommendation_payload['skip_product_tail'])
        && (empty($intent['medical_sensitive']) || $allow_sensitive_support_anchor)
        && empty($intent['special_population_sensitive'])
        && empty($intent['medication_interaction_sensitive'])
        && empty($intent['medication_replacement_sensitive'])
    ) {
        $anchor_patterns = array_merge([$recommendation_primary], $support_products);
        $needs_anchor_note = !fcc_ai_public_content_mentions_patterns($reply_content, $anchor_patterns);
        $needs_conversion_cta = !fcc_ai_public_has_conversion_cta($reply_content, $resolved_language);

        if($needs_anchor_note || $needs_conversion_cta) {
            $anchor_note = fcc_ai_get_public_recommendation_decision_note(
                (string) ($conversation->assistant_type ?? 'product_advisor'),
                $recommendation_payload,
                $resolved_language,
                !empty($knowledge_suggestions)
            );

            if($anchor_note !== '') {
                $reply_content = trim($reply_content . "\n\n" . $anchor_note);
            }
        }
    }

    if(!empty($auto_captured_lead['saved'])) {
        $lead_saved_note = fcc_ai_get_public_lead_saved_note($resolved_language, (string) ($user->name ?? ''));
        $contact_only_message = !empty($auto_captured_lead['candidate']['is_contact_only']);

        if($contact_only_message) {
            $reply_content = $lead_saved_note;
        } elseif($lead_saved_note !== '' && !fcc_ai_public_content_mentions_patterns($reply_content, ['kontakt je', 'contact is now saved', 'kontakt je zdaj', 'контактът ви вече'])) {
            $reply_content = trim($reply_content . "\n\n" . $lead_saved_note);
        }
    }

    $reply['content'] = $reply_content;

    $reply['meta'] = $reply_meta;
    $reply['knowledge_suggestions'] = $knowledge_suggestions;

    fcc_ai_log_message((int) $conversation->fcc_ai_conversation_id, 'assistant', (string) ($reply['content'] ?? ''), [
        'message_type' => 'chat',
        'model' => (string) ($reply_meta['model'] ?? 'fcc-local-preview'),
        'provider' => (string) ($reply_meta['provider'] ?? 'local_preview'),
        'input_tokens' => (int) ($reply_meta['input_tokens'] ?? 0),
        'output_tokens' => (int) ($reply_meta['output_tokens'] ?? 0),
        'api_response_time' => (int) ($reply_meta['api_response_time'] ?? 0),
        'fallback_reason' => (string) ($reply_meta['fallback_reason'] ?? ''),
        'lead_capture_recommended' => (bool) ($reply['lead_capture']['recommended'] ?? false),
        'lead_type' => (string) ($reply['lead_capture']['lead_type'] ?? ''),
        'recommendation_theme_keys' => $reply['recommendation_payload']['theme_keys'] ?? [],
        'knowledge_suggestions' => $knowledge_suggestions,
        'used_context_for_matching' => $used_context_for_matching,
        'recent_user_context' => $recent_user_context,
    ]);
    fcc_ai_increment_daily_stats((int) $user->user_id, (string) $conversation->assistant_type, (string) $conversation->scope, [
        'user_messages' => 1,
        'assistant_messages' => 1,
    ], [
        'event_type' => 'message_exchange',
    ]);

    fcc_ai_log_event([
        'fcc_ai_conversation_id' => (int) $conversation->fcc_ai_conversation_id,
        'user_id' => (int) $user->user_id,
        'assistant_type' => (string) $conversation->assistant_type,
        'event_type' => 'message_exchange',
        'link_id' => (int) ($link->link_id ?? $conversation->link_id ?? 0),
        'blog_post_id' => (int) ($conversation->blog_post_id ?? 0),
        'meta' => [
            'lead_capture_recommended' => (bool) ($reply['lead_capture']['recommended'] ?? false),
            'lead_type' => (string) ($reply['lead_capture']['lead_type'] ?? ''),
            'reply_language' => (string) ($reply['language'] ?? 'hr'),
            'reply_provider' => (string) ($reply_meta['provider'] ?? 'local_preview'),
            'reply_model' => (string) ($reply_meta['model'] ?? 'fcc-local-preview'),
            'fallback_reason' => (string) ($reply_meta['fallback_reason'] ?? ''),
            'provider_error' => !empty($model_attempt['success']) ? '' : trim((string) ($model_attempt['error'] ?? '')),
            'recommendation_theme_keys' => $reply['recommendation_payload']['theme_keys'] ?? [],
            'knowledge_suggestion_count' => count($knowledge_suggestions),
            'used_context_for_matching' => $used_context_for_matching,
        ],
    ]);
    fcc_ai_refresh_conversation_insight((int) $conversation->fcc_ai_conversation_id);

    return [
        'conversation_id' => (int) $conversation->fcc_ai_conversation_id,
        'conversation_public_id' => (string) $conversation->public_id,
        'assistant_type' => (string) $conversation->assistant_type,
        'scope' => (string) $conversation->scope,
        'link_id' => (int) ($link->link_id ?? $conversation->link_id ?? 0),
        'blog_post_id' => (int) ($conversation->blog_post_id ?? 0),
        'owner_name' => (string) ($user->name ?? ''),
        'language' => (string) ($reply['language'] ?? 'hr'),
        'reply' => $reply,
        'messages' => fcc_ai_get_conversation_messages((int) $conversation->fcc_ai_conversation_id, 80, fcc_ai_build_feedback_actor('visitor', (string) ($conversation->visitor_key ?? ($payload['visitor_key'] ?? '')))),
        'lead_status' => (string) ($conversation->lead_status ?? 'none'),
    ];
}

function fcc_ai_ensure_internal_coach_welcome_message(int $conversation_id, array $context = []): array {
    if($conversation_id <= 0) {
        return [];
    }

    $has_messages = db()
        ->where('fcc_ai_conversation_id', $conversation_id)
        ->has('fcc_ai_messages');

    $language = fcc_ai_resolve_public_reply_language((string) ($context['language'] ?? 'hr'));
    $user_name = trim((string) ($context['user_name'] ?? ''));
    $suggestions = fcc_ai_get_internal_coach_suggestions($context, '', 4);
    $coach_summary = is_array($context['ai_plan']['coach_summary'] ?? null) ? $context['ai_plan']['coach_summary'] : [];
    $welcome_content = fcc_ai_get_internal_coach_welcome_message($language, $user_name, [
        'coach_summary' => $coach_summary,
        'starter_summary' => is_array($context['ai_plan']['starter_summary'] ?? null) ? $context['ai_plan']['starter_summary'] : [],
        'sales_link_summary' => is_array($context['ai_plan']['sales_link_summary'] ?? null) ? $context['ai_plan']['sales_link_summary'] : [],
        'active_campaign' => is_array($context['ai_plan']['active_campaign'] ?? null) ? $context['ai_plan']['active_campaign'] : [],
    ]);
    $welcome_meta = [
        'message_type' => 'welcome',
        'model' => 'fcc-local-preview',
        'provider' => 'local_preview',
        'knowledge_suggestions' => $suggestions,
    ];

    if(!$has_messages) {
        fcc_ai_log_message($conversation_id, 'assistant', $welcome_content, $welcome_meta);
    } else {
        $welcome_message = db()
            ->where('fcc_ai_conversation_id', $conversation_id)
            ->where('message_type', 'welcome')
            ->orderBy('fcc_ai_message_id', 'ASC')
            ->getOne('fcc_ai_messages', [
                'fcc_ai_message_id',
                'content',
                'meta',
            ]);

        if($welcome_message && !empty($welcome_message->fcc_ai_message_id)) {
            $existing_meta = json_decode((string) ($welcome_message->meta ?? '{}'), true) ?: [];
            $updated_meta = array_merge($existing_meta, $welcome_meta);

            db()->where('fcc_ai_message_id', (int) $welcome_message->fcc_ai_message_id)->update('fcc_ai_messages', [
                'content' => $welcome_content,
                'meta' => json_encode($updated_meta),
            ]);
        }
    }

    return fcc_ai_get_conversation_messages($conversation_id);
}

function fcc_ai_build_internal_coach_system_prompt(array $context = [], ?object $assistant = null): string {
    $language = fcc_ai_resolve_public_reply_language(
        (string) ($context['language'] ?? ($assistant->language ?? 'auto')),
        (string) ($context['last_user_message'] ?? '')
    );
    $language_label = match($language) {
        'en' => 'English',
        'sl' => 'Slovenian',
        'bg' => 'Bulgarian',
        default => 'Croatian',
    };
    $assistant_label = trim((string) ($assistant->display_name ?? fcc_ai_get_assistant_label('coach', 'FCC Coach')));
    $assistant_settings = is_object($assistant->settings ?? null) ? $assistant->settings : (object) [];
    $tone = trim((string) ($assistant_settings->tone ?? 'supportive'));
    $persona_prompt = trim((string) ($assistant->persona_prompt ?? ''));
    $rules_prompt = trim((string) ($assistant->rules_prompt ?? ''));
    $persona_prompt = $persona_prompt !== '' ? $persona_prompt : fcc_ai_get_default_internal_coach_persona_prompt($language);
    $rules_prompt = $rules_prompt !== '' ? $rules_prompt : fcc_ai_get_default_internal_coach_rules_prompt($language);
    $page = is_array($context['page'] ?? null) ? $context['page'] : [];
