                'communication_style' => (string) ($ai_plan['profile']['communication_style_label'] ?? ''),
                'follow_up_readiness' => (string) ($ai_plan['profile']['follow_up_readiness_label'] ?? ''),
                'active_channels' => $ai_plan['profile']['active_channels'] ?? [],
