                'coach_ideas' => $ai_plan['latest_weekly_plan']['coach_ideas'] ?? [],
            ],
            'latest_weekly_outcome' => [
                'completion_level' => (string) ($ai_plan['latest_weekly_outcome']['completion_level_label'] ?? ''),
